import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-e-001","clusterId":"E","werkstueckRef":"E.1.1","stufe":1,"question":"Du liest eine Schlagzeile und merkst, dass dich eine Meldung sofort wütend macht. Du willst gleich einen empörten Kommentar schreiben. Welche Reaktion ist am klügsten?","options":["Den Kommentar sachlich formulieren und auf Beleidigungen verzichten, damit die Diskussion unter deinem Beitrag fair und ruhig bleibt.","Das Gefühl als Warnsignal nehmen, erst den Artikel mit Zahlen und Quellen prüfen und dann entscheiden, ob und was du kommentierst.","Die Meldung mit deinen eigenen Erfahrungen auf den Radwegen deiner Stadt abgleichen und danach entscheiden, ob und was du dazu schreibst.","Die Schlagzeile an Bekannte weiterleiten und abwarten, wie sie reagieren, bevor du dich selbst dazu äußerst und festlegst."],"correctIndex":1,"explanation":"Eine starke, sofortige Emotion bei einer einfach gestrickten Meldung ist ein typisches Zeichen dafür, dass das schnelle, automatische Denken die Führung hat. Das schnelle Denken ist für Routine nützlich, aber bei neuen oder wichtigen Urteilen anfällig für Fehler. Das langsame, anstrengende Prüfen muss man bewusst einschalten, von allein springt es nicht an. Wer nur die Überschrift kennt, weiß weder, wie hoch die Summe wirklich ist, noch, was sie umfasst oder womit sie zu vergleichen ist. Das Gefühl ist also ein Anlass, innezuhalten und zu prüfen, kein Beweis. Deshalb hilft es, erst die Fakten zu lesen und danach zu urteilen. Ein Gefühl der Stimmigkeit ist kein Wahrheitsbeleg. Ein sachlicher Ton ist lobenswert, ändert aber nichts daran, dass du dein Urteil auf eine bloße Überschrift stützt. Eigene Erfahrungen mit Radwegen sagen nichts darüber, wie hoch die Summe ist und was sie umfasst. Und die Reaktionen von Bekannten zeigen nur deren Stimmung, nicht die Faktenlage.","coreRule":"⚡ Starkes Gefühl plus Eile ist ein Signal zum Innehalten: Erst bewusst prüfen, dann urteilen.","quote":"Du spürst eine starke, sofortige emotionale Reaktion auf eine Information.","quoteLabel":"Merksatz:","beleg":"Werkstück E.1.1 (Kernidee; Kontext & Tiefe); Fn. gl-e-zweisystem (Kahneman 2012, Teil I, Kap. 1: „fiktive Figuren“)","status":"entwurf","scenario":"Die Schlagzeile lautet: „Skandal: Stadt verschwendet Millionen für nutzlose Radwege!“ Du hast nur die Überschrift gelesen, spürst aber sofort ein klares Urteil.","kurz":"Eine starke Wut bei einer schlichten Überschrift zeigt, dass das schnelle, automatische Denken führt. Sie ist ein Anlass innezuhalten, kein Beweis: Erst mit Zahlen, Umfang und Vergleichswerten lässt sich ein Urteil fällen.","prueffrage":"Welche Angaben zu Summe, Umfang und Vergleich findest du in der Überschrift, und welche fehlen?","rueckmeldung":[{"option":0,"text":"Ein sachlicher Ton ohne Beleidigungen ist lobenswert und hält die Diskussion fair. Dein Urteil beruht damit aber weiter nur auf einer Überschrift, und an dieser dünnen Grundlage ändert der Ton nichts."},{"option":2,"text":"Eigene Erfahrungen auf den Radwegen geben einen Eindruck vor Ort. Sie sagen aber nichts darüber, wie hoch die Summe ist, was sie umfasst und womit sie zu vergleichen ist. Genau das fehlt dem Urteil."},{"option":3,"text":"Die Reaktionen von Bekannten wirken wie eine zweite Meinung, zeigen aber nur deren Stimmung und nicht die Faktenlage. Zudem verbreitest du so die ungeprüfte Überschrift weiter, statt die Sache erst zu klären."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality: A Perspective on Intuitive Judgment and Choice. Nobelpreis-Vortrag, Nobel Foundation","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"PDF-S. 3, 5–6","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kahneman, D. (2012): Schnelles Denken, langsames Denken. München: Siedler, Teil I","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f4a996099e31826b"}},{"id":"qx-e-002","clusterId":"E","werkstueckRef":"E.1.1","stufe":2,"question":"Du bemerkst, dass du fast automatisch klicken würdest. Was ist in dieser Lage der klügste nächste Schritt, und warum?","scenario":"Du bekommst eine Nachricht: „Ihr Konto wird in einer Stunde gesperrt – jetzt sofort bestätigen!“ Dein Puls steigt, und du willst nur noch schnell klicken.","options":["Kurz innehalten und die Nachricht über einen eigenen, bekannten Weg prüfen, etwa die offizielle App deiner Bank, weil Druck das Prüfen verhindern soll.","Dem Absender der Nachricht antworten und ihn um Bestätigung bitten, dass die Sperrung echt ist, weil eine echte Bank das umgehend bestätigen würde.","Die Nachricht an Freunde und Familie weiterleiten und vor ihr warnen, weil Warnungen vor Betrug möglichst schnell weitergegeben werden sollten.","Die Nachricht auf Rechtschreibfehler und holprige Formulierungen durchsehen, weil sich Betrugsnachrichten oft an ihrer schlechten Sprache erkennen lassen."],"correctIndex":0,"explanation":"Zeitdruck und starke Gefühle wie Angst oder Gier sind ein bewährtes Mittel von Betrügern: Wer unter Druck steht und aufgeregt ist, greift eher auf schnelle, automatische Reaktionen zurück, statt die Lage in Ruhe zu prüfen. Die wirksamste Gegenmaßnahme ist, die Situation zu verlangsamen und die Behauptung unabhängig zu überprüfen, also nicht über den Link in der Nachricht, sondern über einen Kanal, den du selbst kennst. Ein starkes Alarmgefühl ist kein Beweis für eine echte Gefahr, denn es lässt sich gezielt erzeugen. Erst prüfen, dann handeln. Die anderen Schritte klingen sinnvoll, bringen hier aber keine Klarheit. Wer dem Absender antwortet, fragt genau den, der lügen könnte, sodass seine Bestätigung nichts wert ist. Vor einer Nachricht zu warnen, die noch niemand geprüft hat, kann einen Fehlalarm verbreiten. Und fehlende Sprachfehler beweisen nichts, denn gute Fälschungen sind sprachlich einwandfrei.","coreRule":"⚡ Je schneller und emotionaler man dich zu einer Entscheidung drängt, desto dringender brauchst du eine Denkpause und eine unabhängige Prüfung.","beleg":"Werkstück E.1.1 (Anwendung & Relevanz: Bei Betrugsmaschen; Red Flags)","status":"entwurf","kurz":"Wer unter Zeitdruck und Aufregung steht, handelt eher automatisch. Das Gefühl beweist keine echte Gefahr, es lässt sich gezielt erzeugen. Verlangsame deshalb und prüfe die Behauptung über einen Kanal, den du selbst kennst.","prueffrage":"Was weißt du über den Absender sicher, abgesehen von dem, was die Nachricht selbst über sich behauptet?","rueckmeldung":[{"option":1,"text":"Nachfragen wirkt vorsichtig und gründlich. Du fragst aber genau den, der lügen könnte, und seine Bestätigung sagt deshalb nichts. Eine Antwort kann außerdem zeigen, dass die Adresse aktiv ist."},{"option":2,"text":"Andere schützen zu wollen ist ein guter Impuls, und Warnungen vor Betrug sind oft nützlich. Hier hat aber noch niemand geprüft, ob die Nachricht falsch ist. Ein Fehlalarm könnte sich so verbreiten, während du selbst weiter unter Druck stehst."},{"option":3,"text":"Holprige Sprache ist bei Betrugsnachrichten oft ein Hinweis, aber kein verlässlicher. Eine fehlerfreie Nachricht beweist keine Echtheit, denn gute Fälschungen sind sprachlich einwandfrei. Geprüft wird die Behauptung, nicht der Stil."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Federal Trade Commission (FTC): How To Avoid a Scam","oeffentlich":true,"url":"https://consumer.ftc.gov/articles/how-avoid-scam","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality: A Perspective on Intuitive Judgment and Choice. Nobelpreis-Vortrag, Nobel Foundation","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"PDF-S. 5–6","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"1e9c97d3a4512cda"}},{"id":"qx-e-003","clusterId":"E","werkstueckRef":"E.1.1","stufe":3,"question":"In welcher dieser Situationen ist es am riskantesten, dich auf dein schnelles Bauchgefühl zu verlassen?","options":["Du entscheidest über deine Ersparnisse allein nach dem Gefühl, das ein einfach klingendes Anlageversprechen bei dir auslöst.","Du bist seit Jahren Pflegekraft und holst sofort die Ärztin, weil dir ein Patient auf den ersten Blick schlechter vorkommt als am Vortag.","Du bremst im Auto sofort, als vor dir ein Ball auf die Fahrbahn rollt, ohne erst abzuwägen, ob ein Kind hinterherläuft.","Du bist seit Jahren Schachspielerin und wählst in einer Blitzpartie den Zug, der dir auf den ersten Blick richtig erscheint."],"correctIndex":0,"explanation":"Schnelles, intuitives Denken ist zuverlässig, wo man lange geübt hat und oft eine klare Rückmeldung bekam: Die erfahrene Pflegekraft erkennt Veränderungen, die Schachspielerin Stellungen, und das Bremsen vor dem Ball ist eine bewährte Schutzreaktion. Anders bei Geld, Gesundheit oder politischen Weichenstellungen, in denen man selbst keine Erfahrung mit Rückmeldung hat: Hier geht es um viel, die Lage ist komplex oder neu, und gerade ein „einfach klingendes“ Versprechen ist ein typischer Köder für das Bauchgefühl. Wo viel auf dem Spiel steht und die Situation ungewohnt ist, lohnt sich das langsame, bewusste Nachprüfen, weil ein Fehlurteil teuer wird. Die anderen Lagen können ebenfalls folgenreich oder eilig sein, hier aber stützt sich das Urteil auf Übung oder eine bewährte Reaktion und nicht auf ein Gefühl gegenüber etwas Unbekanntem.","coreRule":"⚡ Bei Routine mit geringem Einsatz darf das Bauchgefühl entscheiden; bei hohen Einsätzen oder Neuem lohnt sich das langsame, bewusste Prüfen.","beleg":"Werkstück E.1.1 (Der Kipppunkt; Kontext & Tiefe: Zuständigkeit von System 1)","status":"entwurf","scenario":"","kurz":"Riskant wird das Bauchgefühl dort, wo viel auf dem Spiel steht und du keine Erfahrung mit Rückmeldung hast, wie bei Ersparnissen und einem einfach klingenden Versprechen. Wer nur dem Gefühl folgt, bemerkt den Köder nicht und zahlt womöglich teuer.","prueffrage":"Wie oft hast du jede dieser Entscheidungen schon getroffen, und wie schnell würdest du jeweils merken, dass du falsch lagst?","rueckmeldung":[{"option":1,"text":"Bei Gesundheit steht viel auf dem Spiel, deshalb wirkt das Bauchgefühl hier riskant. Doch jahrelange Übung mit sichtbarem Verlauf macht den ersten Blick verlässlich, und die Ärztin wird hinzugezogen, das Gefühl wird also nachgeprüft."},{"option":2,"text":"Es geht um mögliche Verletzte, und ohne Abwägen kann das fahrlässig wirken. Das sofortige Bremsen ist aber eine bewährte Schutzreaktion auf eine bekannte Gefahr; Zögern wäre hier das größere Risiko."},{"option":3,"text":"Ein Zug ohne langes Rechnen wirkt leichtfertig. Wer lange Schach gespielt und bei jeder Partie ein klares Ergebnis gesehen hat, erkennt Stellungen aber verlässlich auf den ersten Blick. Zudem steht kaum etwas auf dem Spiel."}],"familie":"faustregel-oder-rechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality: A Perspective on Intuitive Judgment and Choice. Nobelpreis-Vortrag, Nobel Foundation","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"PDF-S. 3, 5","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kahneman, D. (2012): Schnelles Denken, langsames Denken. München: Siedler, Teil I","oeffentlich":false},{"typ":"literatur","kurz":"Kahneman, D.; Klein, G. (2009): Conditions for intuitive expertise: A failure to disagree. American Psychologist","oeffentlich":false,"doi":"10.1037/a0016755"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5d5ad012bfd41bfe"}},{"id":"qx-e-004","clusterId":"E","werkstueckRef":"E.1.1","stufe":4,"question":"Wie gehst du mit der Zahl um?","options":["Du behandelst sie als ungeprüft, weil ohne nachprüfbare Studie auch häufiges Wiederholen sie nicht zum Befund macht.","Du übernimmst sie vorläufig, weil mehrere Quellen ähnliche Werte nennen und Übereinstimmung für eine Zahl spricht.","Du hältst sie für ausreichend plausibel, weil intuitives Denken schnell abläuft und deshalb im Alltag sehr häufig vorkommt.","Du akzeptierst sie, weil ein bekannter Psychologe genannt wird, und prüfst nur noch, ob er richtig zitiert wurde."],"correctIndex":0,"explanation":"Eine glatte Prozentzahl ohne nachvollziehbare Studie dahinter ist zunächst nur eine Behauptung. Dass sie in vielen Marketingtexten steht, ist kein Beleg: Die Zahl lässt sich auf keine belastbare Studie zurückführen und kursiert vor allem im Marketing. Die richtige Reaktion ist deshalb: nach der Originalstudie fragen und die Zahl bis dahin als ungeprüft behandeln. Die anderen Gedanken klingen vernünftig, tragen hier aber nicht. Die leicht abweichenden Werte (90, 95, 98 %) sind keine Bestätigung durch mehrere Messungen, sondern eher ein Zeichen, dass eine Zahl weitergereicht und dabei abgewandelt wird. Dass intuitives Denken im Alltag sehr häufig ist, rechtfertigt noch keine feste Prozentzahl. Und auch ein berühmter Name ersetzt keine Quelle.","coreRule":"⚡ Eine glatte Prozentzahl ohne Studie dahinter ist eine Behauptung, kein Befund.","beleg":"Werkstück E.1.1; Fn. gl-e-95prozent; Fn. gl-e-hirnenergie (Raichle & Gusnard 2002, S. 10237–10238)","status":"entwurf","scenario":"Eine Werbeagentur wirbt mit der Aussage: „Unser intuitives Denken steuert 95 % unserer Entscheidungen.“ Die Zahl steht in einer Präsentation, mit der sie ihren Kunden „neurowissenschaftlich fundiertes Marketing“ verkauft. Eine Studie nennt die Agentur nicht, sie verweist nur auf einen bekannten Psychologen. Auf Nachfrage heißt es, die Zahl stehe „in jedem Marketingbuch“, und je nach Quelle seien es 90, 95 oder 98 %.","quote":"","quoteLabel":"","kurz":"Eine glatte Prozentzahl ohne nachprüfbare Studie ist zunächst nur eine Behauptung, auch wenn sie oft wiederholt wird. Der naheliegende Fehler: Häufigkeit des Zitierens mit Beleg zu verwechseln. Frag nach der Originalstudie und behandle die Zahl bis dahin als ungeprüft.","prueffrage":"Lässt sich verfolgen, woher die 95 % ursprünglich stammen, und warum nennen andere Bücher 90 oder 98 %?","rueckmeldung":[{"option":1,"text":"Mehrere ähnliche Werte wirken wie eine Bestätigung. Es sind aber keine unabhängigen Messungen, sondern Zahlen, die weitergereicht und dabei abgewandelt werden: Aus 90, 95 und 98 % entsteht keine belastbarere Aussage."},{"option":2,"text":"Dass intuitives Denken im Alltag sehr häufig vorkommt, stimmt. Daraus folgt aber keine bestimmte Prozentzahl: Ob es 95 % oder deutlich weniger sind, müsste eine Messung zeigen, nicht die bloße Häufigkeit."},{"option":3,"text":"Ein bekannter Name wirkt wie eine Quelle, ist aber keine. Selbst wenn er korrekt zitiert wäre, bliebe offen, auf welche Untersuchung sich die Zahl stützt. Die Frage nach der Studie wird so nur verschoben."}],"familie":"zahl-zur-quelle","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Harvey, C. (2025): 3 dangerous behavioural science myths – and what to do about them. Research World (ESOMAR)","oeffentlich":true,"url":"https://researchworld.com/articles/3-dangerous-behavioural-science-myths-and-what-to-do-about-them","abruf":"2026-10-12"},{"typ":"url","kurz":"Fletcher, W. (2003): Sigmund fells trendy straw men (Rezension zu Zaltman, How Customers Think). Times Higher Education","oeffentlich":true,"url":"https://www.timeshighereducation.com/books/sigmund-fells-trendy-straw-men/177940.article","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Zaltman, G. (2003): How Customers Think. Boston: Harvard Business School Press","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"29cc36c63b2db3d7"}},{"id":"qx-e-005","clusterId":"E","werkstueckRef":"E.1.2","stufe":1,"question":"Welche Erklärung beschreibt den Kern ihres Verhaltens am sparsamsten?","options":["Sie gibt dem Druck ihrer Umgebung nach und schließt sich der Mehrheitsmeinung an, weil sie nicht als Außenseiterin dastehen will.","Sie unterliegt dem Rückschaufehler: Sie hält ihre Wahl im Nachhinein für vorhersehbar richtig und meint, sie habe es immer gewusst.","Der Zweifel an der eigenen Entscheidung ist unangenehm, und sie rückt ihre Überzeugung zurecht, statt die Entscheidung zu prüfen.","Ihr fehlt das Fachwissen über Autos, sodass sie die widersprüchlichen Tests nicht einordnen kann und sich auf ihr Gefühl verlässt."],"correctIndex":2,"explanation":"Der Widerspruch zwischen „Ich habe klug entschieden“ und „Es gibt Hinweise, dass die Wahl schlecht war“ erzeugt eine unangenehme Spannung (kognitive Dissonanz). Sie lässt sich auf mehreren Wegen verringern: das Verhalten ändern (Auto zurückgeben), die Überzeugung ändern, neue stützende Gründe suchen oder den Widerspruch herunterspielen; oft ist es am einfachsten, bestätigende Informationen zu suchen, statt die Entscheidung zu prüfen. Dazu passt eine klassische Studie von Ehrlich und Kollegen (1957) aus Festingers Umfeld: Neuwagenkäufer lasen häufiger Anzeigen für das eigene Modell (65 %) als für Modelle, die bei ihrer Wahl keine Rolle gespielt hatten (34 %). Die anderen Erklärungen nennen bekannte Mechanismen oder Gründe, passen aber nicht zu Mara. Sie widerspricht ihrer Umgebung gerade, statt sich ihr anzuschließen. Ein Rückschaufehler hieße, im Nachhinein zu behaupten, man habe es gewusst, doch sie wehrt Kritik ab. Und fehlendes Fachwissen erklärt nicht, warum sie gerade die kritischen Tests meidet und nur die lobenden liest.","coreRule":"⚡ Wenn Kritik an einer eigenen Entscheidung vor allem unangenehm ist, lohnt die Frage: Ist sie falsch, oder löse ich gerade Spannung auf, indem ich meine Geschichte zurechtrücke?","beleg":"Werkstück E.1.2 (Kernidee; Anwendung: Nach einer wichtigen Entscheidung; Anti-Denkmuster); Fn. gl-e-dissonanz (Festinger 1957, S. 3 und 13), gl-e-autokauf (Festinger 1957, S. 50–53)","status":"entwurf","scenario":"Mara hat sich für ein teures Auto entschieden. Seitdem kommen ihr Zweifel, ob die Wahl klug war: Ein Freund hat auf Mängel hingewiesen, ein Test bewertet ein anderes Modell besser. Mara liest nun nur noch Tests, die ihr Modell loben, und sagt: „Kritiker sind doch nur neidisch. Mein Auto ist die richtige Wahl, das sehe ich jeden Tag.“","kurz":"Maras Zweifel sind unangenehm, und sie baut ihre Überzeugung zurecht, statt die Entscheidung zu prüfen: Sie liest nur lobende Tests und wertet Kritik ab. Der naheliegende Fehler ist, dahinter Anpassung oder Unwissen zu sehen.","prueffrage":"Prüft Mara den Inhalt der Kritik, oder erklärt sie nur, warum die Kritiker sie äußern?","rueckmeldung":[{"option":0,"text":"Soziale Anpassung gibt es, und Druck von außen kann Entscheidungen färben. Hier gibt Mara aber nicht nach, sondern widerspricht Freund und Test gerade. Eine Mehrheit, der sie sich anschließen könnte, kommt im Szenario nicht vor."},{"option":1,"text":"Beim Rückschaufehler behauptet man im Nachhinein, ein Ergebnis vorhergesehen zu haben. Mara sagt aber nicht „Das wusste ich schon immer“, sondern wehrt aktuelle Kritik ab. Dass die Wahl falsch war, steht zudem gar nicht fest."},{"option":3,"text":"Fehlendes Fachwissen kann das Einordnen widersprüchlicher Tests erschweren. Es erklärt aber nicht, warum Mara gerade die kritischen Tests meidet und nur die lobenden liest. Diese Auswahl spricht für ein Motiv, nicht für bloße Unkenntnis."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Tueanrat, Y.; Alamanos, E. (2026): Cognitive Dissonance Theory: A review. In: Papagiannidis, S. (Hg.): TheoryHub Book, Newcastle University","oeffentlich":true,"url":"https://open.ncl.ac.uk/theories/7/pdf/cognitive-dissonance-theory","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Festinger, L. (1957): A Theory of Cognitive Dissonance. Stanford: Stanford University Press","oeffentlich":false,"doi":"10.1515/9781503620766"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"750cc631ba994798"}},{"id":"qx-e-006","clusterId":"E","werkstueckRef":"E.1.2","stufe":2,"question":"Was tut Jonas mit seiner Antwort, und was ändert sich dadurch an seiner Lage?","scenario":"Dein Freund Jonas hat vor drei Wochen für 280 Euro eine Designerjacke gekauft und sie seitdem nie getragen. Als du ihn darauf ansprichst, sagt er: „Ach, das war doch nicht so viel Geld, das merke ich gar nicht.“","options":["Er spielt den Widerspruch herunter, damit lässt das unangenehme Gefühl nach, die ungenutzte Jacke bleibt aber, wie sie ist.","Er wägt Kosten und Nutzen nüchtern ab, dabei zeigt sich, dass der niedrige Preis den Kauf ohnehin gerechtfertigt hat.","Er nennt einen neuen Grund für den Kauf, damit erscheint die Jacke im Nachhinein als kluge Anschaffung für ihn.","Er korrigiert sein Verhalten, weil er sieht, dass er das Teil nicht braucht, damit endet der innere Konflikt für ihn."],"correctIndex":0,"explanation":"Jonas spielt die Wichtigkeit des Widerspruchs herunter. Zwischen „Ich habe viel Geld ausgegeben“ und „Ich brauche das Teil gar nicht“ besteht eine Spannung, die sich unangenehm anfühlt. Wenn das Geld plötzlich „nicht so viel“ war, schrumpft der Widerspruch, und das Gefühl lässt nach. An der Lage ändert sich dadurch nichts: Die Jacke hängt weiter ungenutzt im Schrank, und aus dem Kauf wird nichts gelernt. Bei kleinen Enttäuschungen ist solche Dissonanzreduktion meist harmlos. Gefährlich wird sie erst, wenn sie uns daran hindert, aus gravierenden Fehlern zu lernen. Zur Unterscheidung der Wege, übertragen auf die Jacke: Wer sie zurückgibt, ändert sein Verhalten. Wer sagt „Das ist ein Klassiker, der kommt wieder“, ändert seine Überzeugung. Wer sagt „Aber es war ein Schnäppchen“, fügt einen neuen Grund hinzu. Wer den Widerspruch für unwichtig erklärt, spielt das Problem herunter.","coreRule":"⚡ Dissonanz lässt sich auf vier Wegen mindern: Verhalten ändern, Überzeugung ändern, neue Gründe hinzufügen oder die Wichtigkeit des Widerspruchs herunterspielen.","beleg":"Werkstück E.1.2 (Kontext & Tiefe, vier Strategien; Werkbank-Frage); Fn. gl-e-dissonanz-wege (Festinger 1957, S. 6 und 18–22)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Jonas macht den Widerspruch klein: Wenn 280 Euro „nicht viel“ sind, drückt der Kauf weniger, und das unangenehme Gefühl lässt nach. Die Jacke hängt aber weiter ungenutzt im Schrank, die Lage bleibt dieselbe, gelernt wird nichts.","prueffrage":"Worauf bezieht sich Jonas' Satz genau, und hat er die Jacke seitdem getragen oder zurückgegeben?","rueckmeldung":[{"option":1,"text":"Eine Abwägung würde etwas gegeneinander halten, doch Jonas sagt nur, der Betrag sei klein. Dass die Jacke dadurch gerechtfertigt wäre, folgt daraus nicht, denn ungenutzt bringt sie auch zu einem kleinen Preis keinen Nutzen."},{"option":2,"text":"Ein neuer Grund für den Kauf wäre etwa „Es war ein Schnäppchen“, und der Ausgang fühlt sich ähnlich an. Jonas nennt aber keinen Grund für den Kauf, sondern macht den Betrag selbst unwichtig, und das ist ein anderer Weg."},{"option":3,"text":"Der Konflikt lässt bei Jonas tatsächlich nach, nur nicht durch eine Korrektur. Er gibt die Jacke nicht zurück und trägt sie nicht, das Gefühl beruhigt sich allein dadurch, dass er den Betrag kleinredet."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Tueanrat, Y.; Alamanos, E. (2026): Cognitive Dissonance Theory: A review. In: Papagiannidis, S. (Hg.): TheoryHub Book, Newcastle University","oeffentlich":true,"url":"https://open.ncl.ac.uk/theories/7/pdf/cognitive-dissonance-theory","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Festinger, L. (1957): A Theory of Cognitive Dissonance. Stanford: Stanford University Press","oeffentlich":false,"doi":"10.1515/9781503620766"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"18213a835813cd6d"}},{"id":"qx-e-007","clusterId":"E","werkstueckRef":"E.1.2","stufe":3,"question":"Was erklärt den Unterschied zwischen beiden Beobachtungen am sparsamsten?","options":["Die Gruppe im zweiten Versuch war vermutlich von vornherein weniger interessant als die Gruppe im ersten, sodass der Aufwand sie nicht mehr aufwerten konnte.","Die Stromstöße dauerten im zweiten Versuch wahrscheinlich zu lange, sodass die Erschöpfung die Aufwertung in Abwertung umschlagen ließ.","Im zweiten Versuch wussten die Teilnehmenden vermutlich, dass Aufwand und Wert nichts miteinander zu tun haben, und entzogen sich so dem Effekt.","Im ersten Fall war der Aufwand der Preis für die Aufnahme, im zweiten galten die Stöße nur als Teil des Versuchs."],"correctIndex":3,"explanation":"Mühe wertet ein Ziel nur auf, wenn sie als Preis für dieses Ziel erlebt wird. Wer sich für eine Aufnahme gequält hat, muss den Aufwand vor sich selbst rechtfertigen und findet die Gruppe deshalb besser, als sie ist. Gilt die Strapaze dagegen als bloßer Teil eines Versuchs, entfällt der Anlass zur Aufwertung; die Gruppe wurde nach starken Stößen tendenziell sogar schlechter bewertet als nach schwachen. Die drei anderen Erklärungen führen zusätzliche, nicht belegte Annahmen ein (eine von vornherein schlechtere Gruppe, eine kritische Dauer, ein Wissen der Teilnehmenden), obwohl der Unterschied in der Rahmung des Aufwands schon ausreicht. Im Sinn der Dissonanztheorie ist das die sparsamste Erklärung. Wichtig bleibt eine Einschränkung: Eine konkurrierende Deutung sieht im ersten Effekt nur einen Kontrast zum unangenehmen Vorlauf, die Rechtfertigungs-Erklärung ist also nicht die einzig mögliche.","coreRule":"⚡ Aufwand wertet nur auf, was als Ziel des Aufwands erlebt wird – sonst fehlt der Anlass zur Rechtfertigung.","beleg":"Werkstück E.1.2 (Anwendung & Relevanz); Fn. gl-e-aufwand (Harmon-Jones & Mills 2019, S. 6–7; Harmon-Jones u. a. 2024, S. 1–2 und 12); Aronson, E. (1969): The theory of cognitive dissonance: A current perspective. Advances in Experimental Social Psychology 4, 1–34, hier S. 9–11 (zu Gerard & Mathewson 1966, J. Exp. Soc. Psychol. 2, 278–287): „No Initiation“-Bedingung (starke Stöße ohne Aufnahmebezug) bewertete die aufgezeichnete Diskussion tendenziell schlechter als die Bedingung mit schwachen Stößen; Bedingung „Initiation“ (starke Stöße für die Aufnahme) bewertete sie besser. Von Sturm als Scan geliefert, am 12.10.2026 per OCR gelesen. Konkurrierende Deutung (Chapanis & Chapanis 1964: Erfolgsgefühl) dort ebenfalls dargestellt.","status":"entwurf","scenario":"Zwei Beobachtungen zur Frage, ob Mühe das Ergebnis aufwertet: (1) Menschen, die für die Aufnahme in eine Gruppe eine peinliche Prüfung ablegen mussten, fanden die Gruppe danach anziehender als Menschen mit einer kaum peinlichen Aufnahme, obwohl sich die Gruppe als ziemlich langweilig erwies. (2) In einem anderen Versuch bekamen Teilnehmende schmerzhafte oder schwache Stromstöße, die keine Bedingung für die Aufnahme in die Gruppe waren. Sie bewerteten die Gruppe danach nach den starken Stößen tendenziell schlechter als nach den schwachen.","kurz":"Mühe wertet ein Ziel nur auf, wenn sie als Preis dafür erlebt wird und gerechtfertigt werden muss. Gelten die Stöße als bloßer Teil des Versuchs, entfällt dieser Anlass. Zusätzliche Annahmen über Gruppe, Dauer oder Wissen braucht es dafür nicht.","prueffrage":"Worin unterscheiden sich die beiden Fälle außer in der Art der Strapaze?","rueckmeldung":[{"option":0,"text":"Eine von vornherein langweiligere Gruppe wäre denkbar, beschrieben ist sie aber nirgends. Zudem wurde im zweiten Versuch dieselbe Gruppe nach starken und schwachen Stößen bewertet; ihr Reiz erklärt also nicht, warum starke Stöße sie eher abwerteten."},{"option":1,"text":"Zu lange Stöße und Erschöpfung klingen plausibel, beschrieben ist davon aber nichts. Die Annahme kommt ohne Beleg hinzu und erklärt nicht, warum die ebenfalls unangenehme Prüfung im ersten Fall aufwertet."},{"option":2,"text":"Von einem solchen Wissen der Teilnehmenden ist nirgends die Rede, die Annahme ist also unbelegt. Nötig ist sie auch nicht: Es genügt, dass die Stöße nicht als Preis für die Aufnahme erlebt wurden."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Harmon-Jones, E.; Matis, S.; Angus, D. J.; Harmon-Jones, C. (2024): Does Effort Increase or Decrease Reward Valuation? Considerations from Cognitive Dissonance Theory. Psychophysiology 61(6), e14536","oeffentlich":true,"doi":"10.1111/psyp.14536","url":"https://osf.io/r7c82","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harmon-Jones, E.; Mills, J. (2019): An Introduction to Cognitive Dissonance Theory and an Overview of Current Perspectives on the Theory. In: Harmon-Jones, E. (Hg.): Cognitive Dissonance. 2. Aufl. Washington, DC: APA, S. 3–24","oeffentlich":false,"doi":"10.1037/0000135-001"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"26b371b03947bc09"}},{"id":"qx-e-008","clusterId":"E","werkstueckRef":"E.1.2","stufe":4,"question":"Was ist an diesem Schluss fehlerhaft?","options":["Er unterstellt, dass eine eindeutige Widerlegung den Glauben immer beendet. Wer viel investiert hat und von anderen gestützt wird, kann sie umdeuten und den Glauben verstärken.","Er verallgemeinert vorschnell: Vom Verhalten einiger eifriger Mitglieder schließt er auf die ganze Gruppe, obwohl sich andere Mitglieder ganz anders verhalten können.","Er unterliegt dem Rückschaufehler: Nachdem der Tag ohne Flut vorüber ist, hält er das Scheitern für von Anfang an offensichtlich und beurteilt die Gruppe danach.","Er sucht nur Hinweise, die seine Deutung stützen, und blendet Gegenhinweise aus; so entsteht ein Bestätigungsfehler, der sein ganzes Urteil über die Gruppe prägt."],"correctIndex":0,"explanation":"Der Schluss behandelt „Widerlegung“ wie einen Schalter, der Glauben automatisch ausschaltet. Wer viel investiert hat (Arbeit, Besitz), erlebt die Widerlegung als schwer erträglichen Widerspruch; leichter, als den eigenen Irrtum einzugestehen, ist es oft, die Widerlegung umzudeuten und am Glauben festzuhalten, besonders mit Rückhalt durch andere Gläubige. Festinger, Riecken und Schachter beschrieben 1956 eine Gruppe, die für den 21. Dezember eine Flut vorhergesagt hatte: Wer nach dem Ausbleiben mit anderen zusammen war, warb eifriger als zuvor, wer allein war, gab den Glauben meist auf. Spätere Studien bestätigen vor allem das Festhalten durch Umdeuten; das verstärkte Werben gilt als schwächster Punkt der Untersuchung, und dass Gegenbeweise einen Glauben sogar verstärken, ist eher die Ausnahme. Der Fehler des Zuschauers liegt darin, das für ausgeschlossen zu halten und aus dem Festhalten auf mangelnde Überzeugung zu schließen. Die anderen Fehler gibt es zwar, der Zuschauer begeht sie aber nicht. Er urteilt über die eifrig werbenden Mitglieder und nicht über die ganze Gruppe, und im Nachhinein behauptet er auch nicht, alles sei vorhersehbar gewesen. Dass er Gegenhinweise ausblendet, lässt sich dem Szenario nicht entnehmen, sein Fehler liegt in der Grundannahme.","coreRule":"⚡ Wer viel investiert hat und Rückhalt in einer Gruppe findet, kann eine Widerlegung umdeuten, statt sie anzunehmen. Daraus, dass jemand an einem widerlegten Glauben festhält, folgt nicht, dass er nicht wirklich überzeugt ist.","beleg":"Werkstück E.1.2 (Anwendung & Relevanz: Bei Kulten & Verschwörungsmythen); Fn. gl-e-prophezeiung (Festinger, Riecken, Schachter 1956, S. 3–4, 227–229); Fn. gl-e-luecke (Lewandowsky u. a. 2020, PDF-S. 9)","status":"entwurf","scenario":"Eine kleine Gruppe hat öffentlich vorhergesagt, an einem bestimmten Tag werde eine Flut die Welt verwüsten. Mehrere Mitglieder haben dafür ihre Arbeit aufgegeben und ihren Besitz verschenkt. Der Tag vergeht, nichts geschieht. Wenig später wirbt ein Teil der Mitglieder eifriger um neue Anhänger als zuvor. Ein Zuschauer folgert: „Wer so reagiert, glaubt gar nicht richtig. Wer wirklich überzeugt wäre, würde angesichts der Widerlegung sofort aufgeben.“","quote":"","quoteLabel":"","kurz":"Der Zuschauer behandelt Widerlegung wie einen Schalter, der Glauben ausschaltet. Wer aber viel investiert hat und Rückhalt in der Gruppe findet, deutet sie oft um und hält fest, statt den eigenen Irrtum einzugestehen.","prueffrage":"Folgt aus dem eifrigeren Werben wirklich, dass die Mitglieder zweifeln, oder lässt sich ihr Verhalten auch anders lesen?","rueckmeldung":[{"option":1,"text":"Eine Verallgemeinerung wäre ein Fehler, der Zuschauer begeht sie aber nicht: Er urteilt über die eifrig werbenden Mitglieder, nicht über alle. Sein Fehler liegt tiefer, in der Annahme darüber, was eine Widerlegung auslöst."},{"option":2,"text":"Den Rückschaufehler gibt es, hier liegt er aber nicht vor. Der Zuschauer behauptet nicht, das Scheitern sei vorhersehbar gewesen, sondern deutet die Reaktion danach falsch."},{"option":3,"text":"Selektive Suche nach bestätigenden Hinweisen ist ein verbreiteter Fehler. Dem Szenario lässt sich aber nicht entnehmen, dass der Zuschauer Gegenhinweise ausblendet. Er zieht aus einem beobachteten Verhalten einen Schluss, und dessen Grundannahme trägt nicht."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020","oeffentlich":true,"doi":"10.17910/b7.1182","url":"https://skepticalscience.com/docs/DebunkingHandbook2020.pdf","seite":"PDF-S. 9","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Festinger, L.; Riecken, H. W.; Schachter, S. (1956): When Prophecy Fails. Minneapolis: University of Minnesota Press","oeffentlich":false},{"typ":"literatur","kurz":"Stone, J. R. (2014): Prophecy. In: Chryssides, G. D.; Zeller, B. E. (Hg.): The Bloomsbury Companion to New Religious Movements. London: Bloomsbury Academic","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"6929ddf32579ffd4"}},{"id":"qx-e-009","clusterId":"E","werkstueckRef":"E.2.1","stufe":1,"question":"Eine Teamleiterin fragt reihum, ob ein Entwurf freigegeben werden soll. Drei Kollegen sagen nacheinander „Ja“, dann bist du an der Reihe. Du kennst die Gruppe seit Jahren und weißt, dass Widerspruch dort selten gut ankommt. Welche der folgenden Reaktionen wäre ein Fall von Konformität in dem Sinn, dass du dein Urteil dem Gruppendruck unterordnest?","options":["Du sagst „Ja“, obwohl du einen Fehler im Entwurf siehst, weil du als Einziger mit „Nein“ auffallen würdest.","Du sagst „Ja“, weil du deinen anfänglichen Fehlerverdacht noch einmal geprüft hast und er sich nicht bestätigt hat.","Du sagst „Nein“ und begründest, welchen Fehler du siehst, obwohl du dich damit gegen die Gruppe stellst.","Du sagst „Ja“, weil du dein Urteil vorab schriftlich festgehalten hattest und dein Ergebnis auch nach den Antworten der anderen unverändert „Ja“ lautet."],"correctIndex":0,"explanation":"Konformität heißt, Verhalten oder Überzeugung an die Gruppe anzupassen, obwohl das eigene Urteil in eine andere Richtung zeigt, ausgelöst durch realen oder bloß eingebildeten Druck. Hier liegt das bei der ersten Reaktion vor: Du erkennst den Fehler und stimmst trotzdem zu, um nicht aus der Reihe zu fallen und nicht ausgegrenzt zu werden. Das ist normativer Einfluss: Du willst gemocht und akzeptiert werden, auch wenn du es besser weißt. Wer nach erneuter Prüfung zu dem Schluss kommt, dass der Entwurf in Ordnung ist, urteilt selbst; dass die Gruppe zufällig dasselbe sagt, macht das nicht zur Anpassung. Dasselbe gilt, wenn du dein Urteil schon vor den Antworten der anderen festgelegt hattest und dabei bleibst: Dein „Ja“ kommt dann aus deinem eigenen Urteil, nicht aus dem Druck der Gruppe. Wer widerspricht, tut das Gegenteil von Anpassung. Das Kennzeichen von Konformität ist also nicht, dass viele dasselbe sagen, sondern dass der Druck der Gruppe das eigene Urteil ersetzt.","coreRule":"Konformität ist die Anpassung des eigenen Verhaltens und der Überzeugungen an die Normen oder das Verhalten einer Gruppe, oft aus realem oder eingebildetem Druck. Prüfstein: Hättest du genauso entschieden, wenn du allein und ohne Blick der anderen geurteilt hättest?","beleg":"Werkstück E.2.1 (Kernidee)","status":"entwurf","scenario":"","kurz":"Konformität liegt vor, wenn der Gruppendruck dein eigenes Urteil ersetzt: Du siehst den Fehler und stimmst trotzdem zu, um nicht aufzufallen. Dass alle dasselbe sagen, macht ein Ja dagegen noch nicht zur Anpassung.","prueffrage":"Was hat sich jeweils zwischen deiner eigenen Prüfung des Entwurfs und deiner lauten Antwort verändert, und wodurch?","rueckmeldung":[{"option":1,"text":"Das Ja wirkt wie Anpassung, weil es mit dem der anderen übereinstimmt. Es entsteht hier aber aus einer eigenen erneuten Prüfung, nicht aus Druck; Übereinstimmung allein macht noch keine Konformität."},{"option":2,"text":"Der Widerspruch gegen die Gruppe kostet Überwindung, deshalb denkt man hier schnell an Gruppendruck. Doch wer seinem Urteil folgt und widerspricht, tut das Gegenteil von Anpassung."},{"option":3,"text":"Hier stimmst du mit allen anderen überein, und das lässt an Anpassung denken. Dein Urteil stand aber schon vor den Antworten der anderen fest und blieb bestehen, es kommt also von dir und nicht vom Gruppendruck."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Open Social Psychology, Kap. 7: Conformity. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter21.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Asch, S. E. (1955): Opinions and Social Pressure. Scientific American 193(5) (Sonderdruck auf einer Lehrseite der University of Vermont, inoffizielle Kopie)","oeffentlich":true,"url":"https://pdodds.w3.uvm.edu/teaching/courses/2009-08UVM-300/docs/others/everything/asch1955a.pdf","seite":"PDF-S. 4","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3a9cbc581dfca3a6"}},{"id":"qx-e-010","clusterId":"E","werkstueckRef":"E.2.1","stufe":2,"question":"Was erklärt dein Schweigen am sparsamsten, und wie lässt sich der Einfluss prüfen?","scenario":"Du bist neu im Team. In der Sitzung loben alle eine Idee, die du für fehlerhaft hältst. Du hast dir deine Einwände sogar schon zurechtgelegt, schweigst aber trotzdem, weil du fürchtest, als Einziger zu widersprechen und dafür schief angesehen zu werden. Später gibst du einer Kollegin gegenüber zu: „Ich hielt den Plan für falsch, wollte aber nicht auffallen.“","options":["Du willst dazugehören und Ablehnung vermeiden. Prüfen lässt sich das, indem du dein Urteil vorab schriftlich festhältst und fragst, ob du alleine im Raum genauso entscheiden würdest.","Du hältst die Gruppe für besser informiert. Prüfen lässt sich das, indem du fragst, welche Belege die anderen für ihr Lob haben und ob sie etwas wissen, was dir fehlt.","Du rechnest damit, dass ein anderer widerspricht, weil sich Verantwortung verteilt. Prüfen lässt sich das, indem du fragst, ob du auch geschwiegen hättest, wenn du allein zuständig wärst.","Du suchst vor allem Bestätigung für das, was du ohnehin denkst. Prüfen lässt sich das, indem du gezielt nach Belegen suchst, die für die Idee der anderen sprechen."],"correctIndex":0,"explanation":"Die Sachlage spricht klar für einen normativen Einfluss: Du weißt es besser und hast deine Einwände schon formuliert, schweigst aber aus Furcht vor den Reaktionen der Gruppe. Dein Zugeständnis („wollte nicht auffallen“) zeigt dieselbe Triebfeder wie bei Aschs Linien-Versuchen, wo gerade die Angst, als Einziger aus der Reihe zu fallen, der am häufigsten genannte Grund fürs Nachgeben war. Informativer Einfluss würde bedeuten, dass du dem Urteil der Gruppe mehr traust als deinem eigenen. Das passt nicht, denn du hältst die Idee ja weiterhin für fehlerhaft. Verantwortungsdiffusion würde voraussetzen, dass du darauf baust, ein anderer werde für dich widersprechen; du schweigst aber, weil du selbst Ablehnung fürchtest. Eine Neigung zur Bestätigung des eigenen Bildes erklärt nicht, warum du deine Einwände zwar hast, sie aber nicht äußerst. Auch bei eindeutiger Antwort gaben in Aschs Versuchen rund drei Viertel mindestens einmal der falschen Mehrheit nach. In einer Abwandlung des Asch-Versuchs gaben Versuchspersonen, die ihr Urteil vorher schriftlich festgehalten hatten, der falschen Mehrheit weit seltener nach. Die Kontrollfrage „Würde ich alleine genauso entscheiden?“ trennt das eigene Urteil vom Gruppendruck.","coreRule":"⚡ Wenn du es besser weißt und trotzdem schweigst, wirkt Angst vor Ausgrenzung, nicht Unsicherheit. Leg dein Urteil fest, bevor du die anderen hörst.","beleg":"Werkstück E.2.1 (Kontext & Tiefe, zwei Hauptgründe; Anti-Denkmuster); Fn. gl-e-einfluss (Deutsch & Gerard 1955, S. 629–633), gl-e-asch-gruende (Asch 1956, S. 32, 70), gl-e-selbstbindung (Deutsch & Gerard 1955, S. 632–634), gl-e-asch (Asch 1956, S. 10–11)","status":"entwurf","kurz":"Du hältst den Plan für falsch und schweigst trotzdem, weil du Ablehnung fürchtest. Das spricht für Anpassung aus Angst vor der Gruppe, nicht für Vertrauen in ihr Urteil. Prüfen lässt es sich, indem du vorab festhältst, wie du allein entscheiden würdest.","prueffrage":"Was sagst du später der Kollegin über den Grund deines Schweigens, und was hältst du da vom Plan?","rueckmeldung":[{"option":1,"text":"Dass andere mehr wissen können, ist ein vernünftiger Gedanke. Hier hältst du den Plan aber weiterhin für falsch und hast deine Einwände schon, du vertraust also deinem eigenen Urteil. Dein Schweigen kommt aus der Furcht vor Reaktionen, nicht aus Zweifel am eigenen Wissen."},{"option":2,"text":"Wenn sich viele zuständig fühlen, hofft oft jeder auf die anderen. Dein Satz „wollte nicht auffallen“ zeigt aber, dass du nicht auf fremden Widerspruch setzt, sondern selbst Ablehnung fürchtest. Das ist eine andere Triebfeder als verteilte Verantwortung."},{"option":3,"text":"Man sucht tatsächlich gern Bestätigung für die eigene Sicht. Das erklärt aber nur, warum du an deinem Urteil festhältst, nicht, warum du deine fertigen Einwände nicht äußerst. Und gezielt nach Belegen für die andere Seite zu suchen, würde nicht klären, ob Gruppendruck dein Schweigen bestimmt."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Asch, S. E. (1955): Opinions and Social Pressure. Scientific American 193(5) (Sonderdruck auf einer Lehrseite der University of Vermont, inoffizielle Kopie)","oeffentlich":true,"url":"https://pdodds.w3.uvm.edu/teaching/courses/2009-08UVM-300/docs/others/everything/asch1955a.pdf","seite":"PDF-S. 4–5","abruf":"2026-10-12"},{"typ":"url","kurz":"Open Social Psychology, Kap. 7: Conformity. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter21.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Deutsch, M.; Gerard, H. B. (1955): A Study of Normative and Informational Social Influences upon Individual Judgment. Journal of Abnormal and Social Psychology 51(3), S. 629–636","oeffentlich":false,"doi":"10.1037/h0046408"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ae9008aa3687722e"}},{"id":"qx-e-011","clusterId":"E","werkstueckRef":"E.2.1","stufe":3,"question":"Du leitest diese Runde. Welche Maßnahme senkt den Konformitätsdruck am ehesten – und wie sicher darfst du dir ihrer Wirkung sein?","options":["Die erfahrenste Person äußert sich zuerst, damit sich die Runde an gesichertem Wissen ausrichtet. Sicher ist die Wirkung nur, solange die Erfahrene recht hat.","Alle stimmen offen per Handzeichen ab, damit ein öffentliches Bekenntnis Verantwortung schafft. Sicher ist die Wirkung nur, solange die Runde klein bleibt.","Die Runde diskutiert, bis alle einstimmig zustimmen, damit nur echter Konsens übrig bleibt. Sicher ist die Wirkung nur, solange lange genug diskutiert wird.","Alle halten ihr Urteil schriftlich fest, bevor die anderen sprechen, damit sie sich festlegen, ehe sie zuhören. Sicher ist die Wirkung nur begrenzt, weil sie hier aus einem frühen Versuch mit kleinen Gruppen stammt."],"correctIndex":3,"explanation":"Konformitätsdruck entsteht vor allem, wenn man unter den Augen der Gruppe antworten muss und nicht auffallen will. Wer sein Urteil festlegt, bevor er die anderen hört, nimmt dem Druck den Angriffspunkt. In einer Abwandlung des Asch-Versuchs (Deutsch & Gerard, 1955) gaben Personen, die ihre Einschätzung vorher auf einem Zettel festgehalten hatten, der falschen Mehrheit weit seltener nach. Der Befund stammt aber aus einem frühen Versuch mit nur 11 bis 15 Studierenden je Bedingung (101 insgesamt), und wer seine Notiz wieder löschte, profitierte deutlich weniger. Die Maßnahme ist also plausibel und gut begründet, ihre Stärke ist aber nicht gesichert. Offene Abstimmung und das Streben nach Einstimmigkeit verschärfen den Druck eher, weil Abweichen dann sichtbar und sozial riskant wird. Die erfahrenste Person zuerst sprechen zu lassen, liefert den anderen nur einen Anker, an dem sie sich orientieren.","coreRule":"⚡ Erst festlegen, dann zuhören: Ein schriftliches Urteil vor der Runde entzieht dem Gruppendruck den Angriffspunkt. Wie stark der Effekt ist, zeigen aber nur wenige kleine Versuche.","beleg":"Werkstück E.2.1 (Anti-Denkmuster: Die Taktik); Fn. gl-e-selbstbindung (Deutsch & Gerard 1955, S. 632–634). Gelesen 12.10.2026 im Volltext: Deutsch, M.; Gerard, H. B. (1955): A study of normative and informational social influences upon individual judgment. Journal of Abnormal and Social Psychology 51(3), 629–636, 101 Studierende der New York University, Bedingungen mit N = 11 bis 15 (Tab. 1–3); Zettel nach der Serie weggeworfen (Self-commitment) bzw. mit „Magic Pad“ gelöscht.","status":"zurueckgezogen","scenario":"Bei Entscheidungen in deiner Runde nennt zuerst jemand mit Nachdruck seine Meinung, und fast alle schließen sich an. Später räumen einzelne ein, sie hätten es eigentlich anders gesehen.","kurz":"Wer sein Urteil festhält, bevor er die anderen hört, nimmt dem Druck den Angriffspunkt. Sicher ist das aber nicht: Der Befund stammt aus einem frühen Versuch mit kleinen Gruppen, die Maßnahme ist plausibel, ihre Stärke offen.","prueffrage":"Was hält die Einzelnen in der Sitzung davon ab, ihre abweichende Sicht zu äußern, die sie später doch einräumen?","rueckmeldung":[{"option":0,"text":"Eine erfahrene Einschätzung ist oft hilfreich und kann wirklich richtig sein. Spricht sie aber zuerst, wird sie zum Anker, an dem sich alle ausrichten. Der Druck, sich anzuschließen, sinkt dadurch nicht, er bekommt nur eine Richtung."},{"option":1,"text":"Ein offenes Bekenntnis wirkt verbindlich. Wer abweicht, tut es dabei aber vor aller Augen und riskiert sozial etwas. Das verschärft den Druck eher, statt ihn zu senken, auch in einer kleinen Runde."},{"option":2,"text":"Wirklicher Konsens klingt nach dem Ziel jeder Runde. Verlangt man aber Einstimmigkeit, wird Abweichen riskant, und Zustimmung kann bloße Anpassung sein. Das verstärkt den Druck eher, auch wenn lange diskutiert wird."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"literatur","kurz":"Deutsch, M.; Gerard, H. B. (1955): A Study of Normative and Informational Social Influences upon Individual Judgment. Journal of Abnormal and Social Psychology 51(3), S. 629–636","oeffentlich":false,"doi":"10.1037/h0046408"},{"typ":"literatur","kurz":"Asch, S. E. (1956): Studies of Independence and Conformity: I. A Minority of One Against a Unanimous Majority. Psychological Monographs 70(9), Whole No. 416","oeffentlich":false,"doi":"10.1037/h0093718"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e1ba651b87cbfa82"}},{"id":"qx-e-012","clusterId":"E","werkstueckRef":"E.2.1","stufe":4,"question":"Ein Blogbeitrag schreibt: „Drei Viertel aller Menschen folgen bei jeder Gelegenheit der Mehrheit, selbst gegen ihre eigenen Augen.“ Als Beleg dient das berühmte Linien-Experiment von Solomon Asch, in dem 75 % der Versuchspersonen nachgaben. Was bedeutet diese Zahl, und was folgt daraus für die Behauptung des Blogbeitrags?","options":["Drei Viertel aller Antworten in den kritischen Durchgängen waren falsch; die Mehrheit der Versuchspersonen gab also durchgehend nach.","Die Zahl galt nur für Studierende im Jahr 1956; spätere Wiederholungen in anderen Ländern fanden durchweg praktisch keine Konformität mehr.","Rund drei Viertel gaben in mindestens einem von zwölf kritischen Durchgängen nach; im Mittel waren nur 36,8 % der Antworten konform.","Die Zahl ist ein Erinnerungsfehler späterer Lehrbücher; Asch selbst berichtete, dass fast alle Teilnehmer der richtigen Linie treu blieben."],"correctIndex":2,"explanation":"Die 75 % messen „mindestens einmal nachgegeben“ (genau 76 %; 94 von 123 Personen), nicht „bei jeder Gelegenheit“. Wer eine Prozentzahl liest, muss fragen, was gezählt wurde: Personen mit mindestens einem Nachgeben oder Antworten insgesamt. Im Mittel waren nur gut ein Drittel der Antworten konform (36,8 %), und 24 % der Versuchspersonen widerstanden durchgehend. Der Blogbeitrag macht aus „mindestens einmal“ ein „immer“. Eine Replikation an der Universität Bern (Franzen & Mader 2023) fand mit 33 % falschen Antworten fast denselben Wert, die Zahl ist also kein Artefakt von 1956. Der Sog ist real, aber deutlich schwächer, als die Schlagzeile behauptet; er schwankt außerdem mit Zeit und Kultur, und schon eine einzige abweichende Stimme schwächt ihn deutlich.","coreRule":"„Mindestens einmal nachgegeben“ ist etwas anderes als „immer nachgegeben“ – prüfe, was eine Prozentzahl tatsächlich misst.","beleg":"Werkstück E.2.1 (Abschnitt „Der Test mit den Linien“); Fn. gl-e-asch (Asch 1956, S. 10–11; Franzen & Mader 2023, S. 1 und 6–8). Franzen, A.; Mader, S. (2023): The power of social influence: A replication and extension of the Asch experiment. PLOS ONE 18(11), e0294325, https://doi.org/10.1371/journal.pone.0294325 (33 % falsche Antworten ohne Anreiz, 25 % mit Anreiz; Asch 1955: 36,8 %); gelesen 12.10.2026.","status":"entwurf","scenario":"","kurz":"Die 75 % zählen Personen, die mindestens einmal nachgaben, nicht Antworten: Im Mittel war nur gut ein Drittel der Antworten konform. Der Blog macht aus „mindestens einmal“ ein „immer“; der Sog ist real, aber viel schwächer.","prueffrage":"Was müsste man über eine Versuchsperson wissen, um sagen zu können, dass sie „bei jeder Gelegenheit“ nachgegeben hat?","rueckmeldung":[{"option":0,"text":"Dass die Mehrheit nachgab, stimmt, aber nur mindestens einmal. Gezählt wurden Personen, nicht Antworten: Im Mittel war gut ein Drittel der Antworten konform, und knapp ein Viertel widerstand durchgehend."},{"option":1,"text":"Einzelne Wiederholungen fanden tatsächlich kaum Konformität. „Durchweg“ stimmt aber nicht: Viele spätere Studien in verschiedenen Ländern fanden den Effekt wieder. Er schwankt mit Zeit und Kultur, verschwindet aber nicht."},{"option":3,"text":"Die Zahl stammt tatsächlich aus Aschs Daten, nur wird sie oft zu „immer“ verkürzt. Dass fast alle standhaft blieben, stimmt aber auch nicht: Etwa drei Viertel gaben mindestens einmal nach, nur 24 % nie."}],"familie":"zahl-zur-quelle","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Franzen, A.; Mader, S. (2023): The power of social influence: A replication and extension of the Asch experiment. PLOS ONE 18(11), e0294325","oeffentlich":true,"doi":"10.1371/journal.pone.0294325","abruf":"2026-10-12"},{"typ":"url","kurz":"Open Social Psychology, Kap. 7: Conformity. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter21.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Asch, S. E. (1956): Studies of Independence and Conformity: I. A Minority of One Against a Unanimous Majority. Psychological Monographs 70(9), Whole No. 416","oeffentlich":false,"doi":"10.1037/h0093718"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"0eb8a0115b3f4c9c"}},{"id":"qx-e-013","clusterId":"E","werkstueckRef":"E.2.2","stufe":1,"question":"Welche Rückfrage prüft am besten, ob Marlene Brandt hier zu Recht als Autorität auftritt?","options":["Welche anderen Ursachen könnten erklären, dass Nutzer seltener erkranken, und lassen sie sich ausschließen?","Welche Daten und Methoden stützen genau diese Aussage, und könnten Dritte sie nachprüfen oder widerlegen?","Wird der Podcast redaktionell betreut, und prüft die Redaktion die Aussagen der Gäste vor der Sendung?","Hat das Mittel bekannte Nebenwirkungen, und sollten Hörer vor der Einnahme ärztlichen Rat einholen?"],"correctIndex":1,"explanation":"Echte Autorität beruht auf nachprüfbarer Kompetenz: Sie ist auf ein Fachgebiet beschränkt, ist provisorisch und offen für Kritik und lädt zur Überprüfung ein („Hier sind meine Daten, prüf sie nach.“). Marlene Brandt dagegen verlangt Vertrauen in ihre Person und weicht der Beleg-Frage aus. Die Frage nach Daten und Methoden zur konkreten Behauptung trennt beides: Sind sie vorhanden und prüfbar, ist Vertrauen ein sinnvoller Zeitgewinn; fehlen sie, bleibt nur Ausstrahlung. Die Suche nach anderen Ursachen für seltenere Erkältungen setzt voraus, dass es überhaupt Daten gibt, die sich deuten lassen, und genau die nennt sie nicht. Die redaktionelle Betreuung des Podcasts sagt etwas über den Sender, nicht darüber, ob Brandt für ihre Aussage Belege hat. Und die Frage nach Nebenwirkungen ist für Hörer wichtig, klärt aber nicht, ob Brandt hier zu Recht als Autorität auftritt.","coreRule":"⚡ Echte Expertise ist spezifisch, vorläufig und prüfbar – Autorität ohne diese drei Eigenschaften ist verdächtig.","beleg":"Werkstück E.2.2 (Kontext & Tiefe: Die zwei Gesichter der Autorität, Typ 1)","status":"entwurf","scenario":"In einem Podcast erklärt die Ernährungsberaterin Marlene Brandt mit großer Überzeugung, dass ein bestimmtes Nahrungsergänzungsmittel Erkältungen verhindert. Als die Moderatorin nach Belegen fragt, antwortet sie: „Ich arbeite seit 20 Jahren in dem Feld. Wer mir nicht vertraut, versteht nichts davon.“ Die Hörerin Jana überlegt, wie sie die Aussage einordnen soll.","kurz":"Echte Autorität lädt zur Prüfung ein: Sie nennt Daten und Methoden zur konkreten Aussage, die andere nachprüfen können. Brandt verlangt dagegen Vertrauen in ihre Person und weicht der Beleg-Frage aus. Dann bleibt nur Ausstrahlung.","prueffrage":"Was antwortet Marlene Brandt genau auf die Frage nach Belegen, und was davon betrifft das Mittel selbst?","rueckmeldung":[{"option":0,"text":"Nach anderen Erklärungen für seltenere Erkältungen zu suchen, ist methodisch gut. Es setzt aber voraus, dass es Daten gibt, die sich deuten lassen, und genau die nennt Brandt nicht. Zuerst muss also geklärt sein, worauf ihre Aussage überhaupt beruht."},{"option":2,"text":"Eine redaktionell betreute Sendung wirkt seriöser, und das ist nicht ganz unwichtig. Es sagt aber etwas über den Sender, nicht darüber, ob Brandt für ihre Aussage Belege hat. Diese Lücke bleibt unabhängig davon bestehen."},{"option":3,"text":"Nebenwirkungen und ärztlicher Rat sind vor jeder Einnahme eine berechtigte Frage. Sie klärt aber nur, ob das Mittel sicher ist, nicht, ob Brandt hier zu Recht als Autorität auftritt. Dafür braucht es die Frage nach ihrer Beleglage."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"The Royal Society: History of the Royal Society („Nullius in verba“)","oeffentlich":true,"url":"https://royalsociety.org/about-us/who-we-are/history/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kim, S. H.: Max Weber. Stanford Encyclopedia of Philosophy, Abschnitt 6.1 „Domination and Legitimacy“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/weber/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"01493743e766176b"}},{"id":"qx-e-014","clusterId":"E","werkstueckRef":"E.2.2","stufe":2,"question":"Woran lässt sich bei diesem Auftreten am besten erkennen, dass sich die Autorität des Kanal-Betreibers nicht auf Evidenz stützt?","scenario":"Ein Kanal-Betreiber erklärt in jedem Video Politik, Medizin und Ernährung mit absoluter Gewissheit. Wer Zweifel äußert, sei „vom System gekauft“, und die Zuschauer sollen „ihm vertrauen, nicht den Fakten“.","options":["Er wählt nur Studien aus, die seine Aussagen stützen, und blendet Gegenbefunde aus.","Er verallgemeinert Einzelfälle aus seinem Umfeld zu Aussagen über alle Menschen.","Er verlangt Vertrauen in seine Person und behandelt Zweifel an ihm als Verrat.","Er benutzt Fachbegriffe, ohne sie zu erklären, und beeindruckt so ein Laienpublikum."],"correctIndex":2,"explanation":"Evidenzbasierte Autorität ist spezifisch, vorläufig und lädt zur Überprüfung ein („Hier sind meine Daten, prüf sie nach“). Der Kanal-Betreiber zeigt das Gegenteil: Er verlangt Vertrauen in seine Person statt in nachprüfbare Methoden und Daten und behandelt Zweifel als Verrat. Das einseitige Auswählen von Studien ist ein verbreiteter Fehler, aber der Betreiber beruft sich auf keine Studien, sondern fordert ausdrücklich, ihm statt den Fakten zu vertrauen. Verallgemeinerte Einzelfälle sind im beschriebenen Auftreten ebenfalls nicht zu erkennen. Und unerklärte Fachbegriffe kommen im Szenario nicht vor; entscheidend ist der Anspruch auf blindes Vertrauen.","coreRule":"⚡ Wer überall Bescheid weiß und Zweifel als Verrat behandelt, beruft sich auf Position oder Ausstrahlung, nicht auf Evidenz.","beleg":"Werkstück E.2.2 (Kontext & Tiefe: Typ 2; Red Flags)","status":"entwurf","kurz":"Wer Vertrauen in seine Person statt in prüfbare Daten verlangt und Zweifel als Verrat wertet, stützt sich nicht auf Evidenz. Naheliegend ist, nach einzelnen Argumentationsfehlern zu suchen, doch entscheidend ist der Anspruch, nicht überprüft zu werden.","prueffrage":"Was bietet der Betreiber seinen Zuschauern an, damit sie eine seiner Aussagen selbst überprüfen können?","rueckmeldung":[{"option":0,"text":"Einseitige Studienauswahl ist ein verbreiteter Fehler und passt zu viel Meinungsmache. Im Szenario beruft sich der Betreiber aber auf keine Studien, sondern verlangt ausdrücklich Vertrauen statt Fakten."},{"option":1,"text":"Aus Einzelfällen im eigenen Umfeld auf alle zu schließen, ist ein typischer Fehler. Im beschriebenen Auftreten ist davon aber nichts zu erkennen; geschildert wird kein Beispiel, sondern ein Anspruch auf Gewissheit und Vertrauen."},{"option":3,"text":"Unverständliche Fachsprache kann Eindruck schinden und echte Argumente ersetzen. Im Szenario kommen solche Begriffe jedoch gar nicht vor; auffällig ist der Anspruch, man solle ihm glauben, statt zu prüfen."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Kim, S. H.: Max Weber. Stanford Encyclopedia of Philosophy, Abschnitt 6.1 „Domination and Legitimacy“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/weber/","abruf":"2026-10-12"},{"typ":"url","kurz":"The Royal Society: History of the Royal Society („Nullius in verba“)","oeffentlich":true,"url":"https://royalsociety.org/about-us/who-we-are/history/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2e8e7d727281ffad"}},{"id":"qx-e-015","clusterId":"E","werkstueckRef":"E.2.2","stufe":3,"question":"Ein Vorgesetzter sagt einem Mitarbeiter, der Bedenken gegen eine Anweisung äußert: „Ich übernehme die volle Verantwortung. Du führst nur aus.“ Wie wirkt dieser Satz auf das Verhalten des Mitarbeiters, und warum?","options":["Er macht eher weiter, weil er sich nun als bloßes Werkzeug der Anweisung statt als moralisch Handelnder sieht.","Er macht eher weiter, weil er sich dem Verhalten seiner Kollegen anpasst, die solche Anweisungen ebenfalls befolgen.","Er macht eher weiter, weil er die ersten Schritte schon getan hat und nicht widersprüchlich handeln will.","Er macht eher weiter, weil er sich vom Chef eine Belohnung verspricht, wenn er die Anweisung ohne Nachfrage erfüllt."],"correctIndex":0,"explanation":"Der Satz lässt die Verantwortung scheinbar bei einer anderen Person. Genau das erlaubt es dem Mitarbeiter, sich nicht mehr als moralisch Handelnden, sondern als bloßes Werkzeug der Anweisung zu sehen. In Milgrams Experimenten war diese Verantwortungsübernahme einer der Faktoren, die das extreme Verhalten förderten. Die vollständige Abgabe der Verantwortung ist zudem der Kipppunkt zum gefährlichen Gehorsam. Anpassung an Kollegen ist ein echter Mechanismus, im Szenario kommen aber keine Kollegen vor. Die Bindung an frühere Schritte würde greifen, wenn er schon angefangen hätte, doch er zögert noch vor dem ersten. Und von einer Belohnung ist keine Rede, der Satz ändert nur, wer sich zuständig fühlt.","coreRule":"⚡ Wer Verantwortung vollständig an eine Autorität abgibt, wird vom Handelnden zum Werkzeug.","beleg":"Werkstück E.2.2 (Die situativen Faktoren des Gehorsams; Der Kipppunkt)","status":"entwurf","scenario":"Ein Mitarbeiter soll auf Anweisung seines Chefs Kundendaten ändern, was ihm nicht geheuer ist. Er zögert und sagt, er wolle dafür nicht geradestehen. Der Chef antwortet: „Ich übernehme die volle Verantwortung. Du führst nur aus.“","kurz":"Der Satz verschiebt die Verantwortung scheinbar zum Chef, und so kann sich der Mitarbeiter als bloßes Werkzeug statt als moralisch Handelnden sehen. Der Denkfehler liegt darin, nach anderen Mechanismen zu suchen, obwohl der Satz nur ändert, wer sich zuständig fühlt.","prueffrage":"Wogegen richtete sich das Zögern des Mitarbeiters, und auf welchen Teil davon antwortet der Chef?","rueckmeldung":[{"option":1,"text":"Anpassung an Kollegen gibt es tatsächlich, etwa im Gruppendruck. Im Szenario tauchen aber keine Kollegen auf, und der Satz des Chefs betrifft allein die Frage, wer für die Handlung geradesteht."},{"option":2,"text":"Wer einmal angefangen hat, will oft folgerichtig weitermachen. Hier zögert der Mitarbeiter aber noch vor dem ersten Schritt, es gibt also noch nichts, woran er sich gebunden fühlen könnte."},{"option":3,"text":"Eine Belohnung ist als Motiv denkbar, im Szenario aber nirgends angedeutet. Der Chef verspricht nichts, er nimmt dem Mitarbeiter nur das Gefühl, selbst zuständig zu sein."}],"familie":"verantwortung-benennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Uzelac, E.; Yang, Y.-F. (2026): Obedience to Authority. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter4.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Milgram, S. (1974): Obedience to Authority: An Experimental View. New York: Harper & Row","oeffentlich":false},{"typ":"url","kurz":"Milgram, S. (1963): Behavioral Study of Obedience. Journal of Abnormal and Social Psychology 67(4), S. 371–378 (Kopie auf einer Seite der University of Miami)","oeffentlich":true,"url":"https://www.psy.miami.edu/_assets/pdf/rpo-articles/milgram-1963.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"2a92bc8af8c5c9f7"}},{"id":"qx-e-016","clusterId":"E","werkstueckRef":"E.2.2","stufe":4,"question":"Ein Podcast sagt: „Milgram bewies: Zwei Drittel aller Menschen gehorchen immer, bis es tödlich wird.“ Was ist an dieser Aussage vor allem problematisch?","options":["Sie macht aus dem Ergebnis einer einzelnen Versuchsanordnung ein Gesetz, das angeblich in jeder Situation gilt.","Sie schließt aus der zeitlichen Abfolge zweier Ereignisse auf eine Ursache und übersieht mögliche Drittfaktoren.","Sie greift den Forscher persönlich an, statt sich mit seiner Methode und seinen Ergebnissen zu befassen.","Sie erklärt das Verhalten zirkulär: Menschen gehorchen, weil sie gehorsam sind, und das gilt dann als Beweis."],"correctIndex":0,"explanation":"Die Zahl selbst ist belegt: In der Basisanordnung von 1963 gingen 26 von 40 Teilnehmern (65 %) bis zum 450-Volt-Schalter. Aber Milgram testete rund zwanzig Variationen, und dort schwankte die Quote zwischen null und über neunzig Prozent; die Situation (Legitimität der Autorität, Übernahme der Verantwortung, schrittweise Eskalation, Distanz zum Opfer) verschiebt sie erheblich. „Immer“ ist deshalb der Fehler: Aus einem Ergebnis unter bestimmten Bedingungen wird eine Naturkonstante gemacht, und das Gegenteil davon ist nicht „nie“, sondern „je nach Lage“. Mit der Frage „Unter welchen Bedingungen wurde das gemessen?“ lässt sich jede berühmte Zahl prüfen. Von einem Ursachenschluss aus einer bloßen Abfolge von Ereignissen ist in der Aussage keine Rede, sie nennt eine gemessene Quote. Ein persönlicher Angriff auf den Forscher liegt nicht vor, die Aussage beruft sich im Gegenteil auf ihn. Und einen Zirkelschluss enthält sie ebenfalls nicht, denn sie erklärt nichts, sondern erhebt ein Ergebnis zur Regel.","coreRule":"⚡ Eine berühmte Zahl gehört zu einer bestimmten Anordnung – ändere die Anordnung, und sie ändert sich.","beleg":"Werkstück E.2.2 (Einstieg; Situative Faktoren); Fn. gl-e-milgram (Milgram 1963, S. 371–378; Burger 2009, S. 1 f.); Fn. gl-e-milgram-varianten (Milgram 1974; Haslam & Reicher 2012)","status":"entwurf","scenario":"","kurz":"Die 65 % sind für die Basisanordnung belegt, in rund zwanzig Variationen schwankte die Quote aber zwischen null und über neunzig Prozent. Der Fehler liegt im „immer“: Ein Ergebnis unter bestimmten Bedingungen wird zum Gesetz erklärt.","prueffrage":"Wo und mit wem wurde die Zahl ermittelt, und für wen soll sie laut Podcast gelten?","rueckmeldung":[{"option":1,"text":"Bei Verhaltensstudien liegt die Frage nach Ursachen nahe. Die Aussage schließt hier aber gar nicht aus einer Abfolge auf eine Ursache, sie nennt eine gemessene Quote und verallgemeinert sie. Das Problem liegt im „immer“."},{"option":2,"text":"Bei einem so umstrittenen Experiment denkt man schnell an Kritik an der Person. Die Aussage greift Milgram aber nicht an, sie beruft sich im Gegenteil auf ihn. Der Fehler liegt im Umgang mit seinem Ergebnis, nicht in einer Abwertung des Forschers."},{"option":3,"text":"„Gehorchen“ und „gehorsam“ klingen verwandt, doch die Aussage erklärt gar nichts: Sie nennt eine Quote und erhebt sie zur Regel. Ein Zirkelschluss braucht eine Erklärung, die sich selbst voraussetzt, und die fehlt hier."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Milgram, S. (1963): Behavioral Study of Obedience. Journal of Abnormal and Social Psychology 67(4), S. 371–378 (Kopie auf einer Seite der University of Miami)","oeffentlich":true,"url":"https://www.psy.miami.edu/_assets/pdf/rpo-articles/milgram-1963.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Uzelac, E.; Yang, Y.-F. (2026): Obedience to Authority. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter4.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Haslam, S. A.; Reicher, S. D. (2012): Contesting the ‚Nature‘ of Conformity: What Milgram and Zimbardo’s Studies Really Show. PLOS Biology 10(11), e1001426","oeffentlich":true,"doi":"10.1371/journal.pbio.1001426","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"092861d1bf24b1fd"}},{"id":"qx-e-017","clusterId":"E","werkstueckRef":"E.2.3","stufe":1,"question":"Welcher Denkmechanismus erklärt das Verhalten der Passantin am besten, und was wäre die wirksamste Gegenmaßnahme?","scenario":"Auf einem vollen Bahnsteig sackt jemand zusammen. Zwanzig Menschen stehen herum, alle sehen hin, keiner bewegt sich. Eine Passantin sagt hinterher: „Ich dachte die ganze Zeit, das ist schlimm. Aber ich habe gar nicht erst gerufen, denn bei so vielen Leuten hat bestimmt schon jemand den Notruf gewählt.“","options":["Sie hält die Lage für harmlos, weil alle anderen ruhig bleiben. Gegenmaßnahme: Selbst genau hinsehen, ob es wirklich ein Notfall ist.","Sie scheut die Blamage, falls es doch kein Notfall ist. Gegenmaßnahme: Sich klarmachen, dass Fehlalarme selten bestraft werden.","Sie sieht ihre Verantwortung auf alle Anwesenden verteilt. Gegenmaßnahme: Selbst handeln oder eine Person direkt ansprechen.","Sie wartet auf eine zuständige Person, die das Kommando übernimmt. Gegenmaßnahme: Sich dieser Person ausdrücklich unterordnen."],"correctIndex":2,"explanation":"Die Passantin hält die Lage ja für schlimm, sie schätzt sie also nicht als harmlos ein. Ihr Gedanke „bestimmt hat schon jemand angerufen“ zeigt, dass sie die Verantwortung auf die anderen Anwesenden abgibt: Je mehr Menschen dabei sind, desto kleiner fühlt sich der eigene Anteil an. Das nennt man Diffusion der Verantwortung. Dass alle ruhig bleiben und deshalb nichts Schlimmes sein kann, wäre pluralistische Ignoranz; die Angst vor der Blamage wäre Bewertungsangst. Beides passt nicht zu dem, was die Passantin sagt. Das Warten auf eine zuständige Person wäre eine Abgabe der Verantwortung an eine Autorität, nicht ihr Verschwinden in der Menge. Wirksam gegen die Diffusion ist, die Verantwortung wieder zu personalisieren: selbst anpacken oder eine konkrete Person direkt ansprechen, etwa „Sie da, rufen Sie bitte den Notruf!“. Eine allgemeine Bitte um Hilfe lässt die Verantwortung dagegen weiter in der Menge verschwinden.","coreRule":"⚡ „Wird schon jemand anders tun“ – so verschwindet die eigene Verantwortung in der Menge. Gegenmittel: selbst handeln oder gezielt eine Person ansprechen.","beleg":"Werkstück E.2.3 (Kernidee; Kontext & Tiefe, drei Hauptgründe; Verbindungen)","status":"entwurf","kurz":"Die Passantin findet die Lage schlimm und glaubt, andere hätten längst gerufen: Mit vielen Zuschauern verschwindet der eigene Anteil an der Verantwortung. Dagegen hilft nur, sie wieder an eine Person zu binden, an dich selbst oder an jemanden, den du direkt ansprichst.","prueffrage":"Was sagt die Passantin selbst darüber, wie sie die Lage einschätzt, und worauf stützt sie ihre Entscheidung, nicht zu rufen?","rueckmeldung":[{"option":0,"text":"Dass alle ruhig bleiben, kann tatsächlich den Eindruck erwecken, es sei nichts Ernstes. Die Passantin sagt aber ausdrücklich, sie habe es schlimm gefunden, ihr Zögern hat also einen anderen Grund."},{"option":1,"text":"Die Sorge, sich zu blamieren, hält manche Menschen vom Helfen ab. In ihrer Aussage kommt sie aber nicht vor: Sie nennt keine Angst vor einem Fehlalarm, sondern verlässt sich darauf, dass bestimmt schon jemand angerufen hat."},{"option":3,"text":"Auch das Warten auf jemanden, der das Kommando übernimmt, bedeutet, Verantwortung abzugeben. Im Szenario tritt aber keine zuständige Person auf; die Passantin vertraut auf irgendjemanden aus der Menge. Ein Unterordnen unter eine Autorität träfe deshalb nicht den Kern."}],"familie":"verantwortung-benennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Barleben, L.; O’Mahony, A. (2026): Bystander Effect. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter13.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Bundeskriminalamt Österreich (2024): Mehr Zivilcourage – 6 Tipps für den Ernstfall. Wien","oeffentlich":true,"url":"https://www.bundeskriminalamt.at/212/service/files/200_2024_broschuere_zivilcourage_a5_v20240624_ansicht.pdf","seite":"S. 7","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Fischer, P.; Krueger, J. I.; Greitemeyer, T. u. a. (2011): The bystander-effect: A meta-analytic review on bystander intervention in dangerous and non-dangerous emergencies. Psychological Bulletin 137(4), S. 517–537","oeffentlich":false,"doi":"10.1037/a0023304"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5d2e5371c3f49481"}},{"id":"qx-e-018","clusterId":"E","werkstueckRef":"E.2.3","stufe":2,"question":"Was ist an diesem Vorgehen das Hauptproblem – und was wäre die wirksamere Alternative?","options":["Der Ruf richtet sich an niemanden Bestimmten, daher fühlt sich jeder nur zum Teil zuständig. Wirksamer wäre es, eine einzelne Person direkt mit einer konkreten Bitte anzusprechen.","Der Ruf geht im Lärm der Fußgängerzone unter, daher bemerkt ihn kaum jemand. Wirksamer wäre es, mit einem lauten Pfiff oder Signalton Aufmerksamkeit zu erzeugen.","Passanten fürchten, bei einem Fremden etwas falsch zu machen und dafür belangt zu werden. Wirksamer wäre es, ausdrücklich zu versichern, dass niemand für Hilfe haftet.","Passanten halten den Mann für selbst schuld an seinem Sturz und fühlen sich nicht zuständig. Wirksamer wäre es, klarzustellen, dass er unverschuldet gestürzt ist."],"correctIndex":0,"explanation":"Wer „Kann mir jemand helfen?“ ruft, macht niemanden persönlich zuständig: Jeder kann denken, ein anderer werde schon helfen, und die gefühlte Verantwortung verteilt sich auf alle Anwesenden. Dass alle ruhig bleiben, wirkt zudem wie ein Signal, dass nichts Schlimmes passiert ist. Wer eine einzelne Person direkt anspricht und ihr eine konkrete Bitte nennt, personalisiert die Verantwortung und macht Hilfe wahrscheinlicher. Das Prinzip gilt auch für Zeugen: die Führung übernehmen und Aufgaben verteilen („Ich kümmere mich um den Verletzten, können Sie bitte den Notruf wählen?“). Dass der Ruf im Lärm untergeht, passt nicht dazu, dass einige Passanten kurz hinschauen, er wurde also gehört. Die Angst, etwas falsch zu machen, ist ein bekanntes Hindernis, im Szenario gibt es dafür aber keinen Hinweis. Und dass Passanten dem Mann die Schuld geben, wird ebenso wenig angedeutet; er bittet ja ausdrücklich um Hilfe.","coreRule":"⚡ Aus „Kann mir jemand helfen?“ wird „Sie da, rufen Sie bitte den Notarzt“ – Verantwortung braucht einen Namen.","beleg":"Werkstück E.2.3 (Das Anti-Denkmuster: Wenn du Hilfe brauchst; Wenn du Zeuge bist)","status":"entwurf","scenario":"Ein Mann stürzt in einer belebten Fußgängerzone und kann sich nicht mehr aufrichten. Vor Schmerzen ruft er laut in die Menge: „Kann mir bitte jemand helfen?“ Dutzende Menschen gehen vorbei, einige schauen kurz hin, niemand bleibt stehen. Alle wirken ruhig.","kurz":"Wer „Kann mir jemand helfen?“ ruft, macht niemanden persönlich zuständig: Jeder darf hoffen, dass ein anderer hilft, und die ruhigen Umstehenden wirken wie Entwarnung. Erst eine direkt angesprochene Person mit konkreter Bitte trägt die Verantwortung.","prueffrage":"Wie viele Menschen hören den Ruf, woran ist zu erkennen, dass sie ihn bemerkt haben, und was tun sie dann?","rueckmeldung":[{"option":1,"text":"Dass der Ruf untergeht, klingt in einer lauten Fußgängerzone plausibel. Im Szenario schauen aber einige kurz hin, er wurde also gehört. Ein Pfiff würde nur noch mehr Blicke bringen, die Zuständigkeit bliebe unklar."},{"option":2,"text":"Die Sorge, bei Fremden etwas falsch zu machen, ist als Hilfehindernis bekannt. Das Szenario gibt dafür aber keinen Anhaltspunkt, und eine Haftungszusicherung würde nichts daran ändern, dass sich niemand persönlich angesprochen fühlt."},{"option":3,"text":"Schuldzuweisung kann Hilfsbereitschaft tatsächlich dämpfen. Im Szenario deutet aber nichts darauf hin: Der Mann bittet ausdrücklich um Hilfe, und niemand äußert Vorwürfe. Klarzustellen, dass er unverschuldet stürzte, löst also kein Problem, das hier besteht."}],"familie":"verantwortung-benennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bundeskriminalamt Österreich (2024): Mehr Zivilcourage – 6 Tipps für den Ernstfall. Wien","oeffentlich":true,"url":"https://www.bundeskriminalamt.at/212/service/files/200_2024_broschuere_zivilcourage_a5_v20240624_ansicht.pdf","seite":"S. 7","abruf":"2026-10-12"},{"typ":"url","kurz":"Barleben, L.; O’Mahony, A. (2026): Bystander Effect. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter13.html","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"b50ef5dab3a76c3b"}},{"id":"qx-e-019","clusterId":"E","werkstueckRef":"E.2.3","stufe":3,"question":"Wie solltest du mit dieser Behauptung umgehen und warum?","options":["Die Geschichte ist als erledigt zu betrachten, denn die Prüfung der Gerichtsakten hat die Kernpunkte widerlegt; ihre weite Verbreitung sagt nichts über ihre Richtigkeit.","Die Geschichte bleibt im Kern bestehen, denn dass sich die Zahl 38 nicht belegen lässt, betrifft nur ein Detail, nicht die Aussage, dass viele zusahen und niemand half.","Die Geschichte bleibt vorerst gültig, denn die Beweislast liegt bei dem, der eine lange gelehrte Aussage bestreitet, und eine einzelne Aktenprüfung reicht dafür nicht.","Die Geschichte bleibt gültig, solange Fachleute sie nicht offiziell zurückgenommen haben, denn Lehrbuchinhalte gelten als durch den Fachkonsens geprüft."],"correctIndex":0,"explanation":"Eine Behauptung wird nicht dadurch wahr, dass sie oft wiederholt wird. Entscheidend ist, ob sie einer Prüfung an den Quellen standhält. Die Auswertung der Gerichtsakten zeigte: Kaum jemand konnte den Angriff als Ganzes sehen, mindestens zwei Anwohner riefen die Polizei, eine Nachbarin lief hinunter und hielt die Sterbende im Arm, bis der Rettungswagen kam, und die Zahl 38 stammt aus keiner belegbaren Zählung. Die Erzählung ist damit in ihren Kernpunkten falsch. Dass sie trotzdem zur Gründungsgeschichte der Forschung darüber wurde, wann Zuschauer eingreifen, zeigt nur, wie zählebig eine eingängige Geschichte ist. Ob Menschen in Gruppen seltener helfen, muss man an anderen Belegen prüfen, etwa an kontrollierten Experimenten, nicht an dieser Erzählung. Dass nur die Zahl 38 wackelt, stimmt nicht: Auch das Wegsehen aller und das Ausbleiben von Hilfe sind durch die Akten widerlegt. Die Beweislast bei dem zu sehen, der eine alte Aussage bestreitet, hilft nicht weiter, denn die Akten sind genau dieser Beleg. Und Lehrbücher sind Sekundärquellen, die nicht über den Originalakten stehen, aus denen sie sich speisen.","coreRule":"⚡ Eine eingängige Geschichte ist kein Beleg – auch ein oft wiederholter Klassiker kann ein Mythos sein; prüfe die Quelle, nicht die Verbreitung.","beleg":"Werkstück E.2.3 (Einstieg); Fn. gl-e-genovese (Manning, Levine, Collins 2007, S. 555–562; Gansberg 1964, NYT)","status":"entwurf","scenario":"In einem Seminar sagt jemand: „Es ist bewiesen, dass 38 Menschen in New York einen Mord beobachtet und alle weggesehen haben. Das zeigt, wie herzlos Großstädter sind.“ Er beruft sich darauf, dass diese Geschichte in vielen Lehrbüchern steht und seit Jahrzehnten erzählt wird. Eine Nachprüfung der Gerichtsakten ergab später: Kaum jemand konnte den Angriff als Ganzes sehen, mindestens zwei Anwohner riefen die Polizei, und eine Nachbarin hielt die Sterbende im Arm, bis der Rettungswagen kam. Die Zahl 38 stammt aus keiner belegbaren Zählung.","quote":"","quoteLabel":"","kurz":"Wie oft und wie lange eine Geschichte erzählt wird, sagt nichts über ihre Richtigkeit. Die Gerichtsakten widerlegen ihre Kernpunkte: Kaum jemand sah alles, Hilfe wurde geholt, die Zahl 38 ist unbelegt.","prueffrage":"Welche Teile der Geschichte bleiben stehen, wenn man nur gelten lässt, was sich an den Akten belegen lässt?","rueckmeldung":[{"option":1,"text":"Die Zahl 38 ist tatsächlich unbelegt, aber das ist nicht das Einzige. Nach den Akten sah kaum jemand den ganzen Angriff, zwei riefen die Polizei, eine Nachbarin half: Auch das Wegsehen aller ist widerlegt."},{"option":2,"text":"Wer eine etablierte Aussage bestreitet, muss tatsächlich Belege liefern. Hier sind die Gerichtsakten aber genau dieser Beleg, und sie widerlegen die Kernpunkte der Geschichte. Es geht nicht um eine bloße Gegenmeinung."},{"option":3,"text":"Lehrbücher sind oft verlässlich, aber sie fassen Quellen zusammen und stehen nicht über ihnen. Die Originalakten zeigen, dass die Erzählung nicht stimmt, ob eine offizielle Rücknahme vorliegt oder nicht."}],"familie":"lehrgeschichte-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Clark, R. P. (2016): Misremembering Kitty Genovese. Poynter Institute","oeffentlich":true,"url":"https://www.poynter.org/reporting-editing/2016/misremembering-kitty-genovese/","abruf":"2026-10-12"},{"typ":"url","kurz":"Barleben, L.; O’Mahony, A. (2026): Bystander Effect. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter13.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Manning, R.; Levine, M.; Collins, A. (2007): The Kitty Genovese Murder and the Social Psychology of Helping: The Parable of the 38 Witnesses. American Psychologist 62(6), S. 555–562","oeffentlich":false,"doi":"10.1037/0003-066X.62.6.555"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"14b4942916c7414a"}},{"id":"qx-e-020","clusterId":"E","werkstueckRef":"E.2.3","stufe":4,"question":"Ein Kollege sagt zur Klimakrise: „Es gibt so viele andere, was kann ich als Einzelner schon tun?“ Welcher psychologische Mechanismus steckt am ehesten hinter diesem Gedanken?","options":["Pluralistische Ignoranz: Jeder hält das Problem insgeheim für harmlos, weil alle anderen nach außen ruhig bleiben.","Eine besonders starke Wirkung des Zuschauereffekts: Je mehr Menschen anwesend sind, desto weniger greift in einem Notfall überhaupt noch jemand ein.","Eine realistische Einschätzung: Diffusion der Verantwortung tritt nur bei Notfällen mit direkter Lebensgefahr auf und passt hier nicht.","Diffusion der Verantwortung: Bei einem riesigen Problem mit vielen Beteiligten verteilt sich das Verantwortungsgefühl, die eigene Rolle wirkt winzig."],"correctIndex":3,"explanation":"Der Satz zeigt das Muster der verteilten Verantwortung: Wenn ein Problem riesig ist und sehr viele andere ebenfalls betroffen sind, fühlt sich der Einzelne nur noch für einen winzigen Anteil zuständig und denkt, jemand anderes werde schon etwas tun. Das ist die gleiche Logik wie bei einem Unfall mit vielen Umstehenden. Die Annahme der Pluralistischen Ignoranz passt nicht, denn der Kollege hält das Problem nicht für harmlos, sondern seinen eigenen Beitrag für bedeutungslos. Auch die Behauptung, in großen Gruppen greife meist niemand mehr ein, trägt nicht: Der Zuschauereffekt beschreibt nur, dass die Wahrscheinlichkeit sinkt, dass eine einzelne Person hilft. In gefilmten Konflikten im öffentlichen Raum (219 Fälle in drei Ländern, Philpot u. a. 2020) griff in gut neun von zehn Fällen mindestens ein Umstehender ein. Und dass der Mechanismus nur bei Notfällen mit direkter Lebensgefahr auftrete, widerspricht dem Buch: Es nennt „Was kann ich als Einzelner schon tun?“ ausdrücklich als klassischen Gedanken der diffundierten Verantwortung bei großen gesellschaftlichen Problemen.","coreRule":"⚡ „Was kann ich als Einzelner schon tun?“ ist der Satz, mit dem Verantwortung verteilt wird und verschwindet.","beleg":"Werkstück E.2.3 (Anwendung & Relevanz: Bei großen gesellschaftlichen Problemen); Fn. gl-e-philpot (Philpot u. a. 2020, American Psychologist 75(1), S. 66–75)","status":"entwurf","scenario":"In einer Gesprächsrunde wird über die Klimakrise gesprochen. Ein Kollege winkt ab: „Es gibt so viele andere, was kann ich als Einzelner schon tun?“","quote":"","quoteLabel":"","kurz":"Wenn ein Problem riesig ist und viele betroffen sind, schrumpft das eigene Zuständigkeitsgefühl auf einen winzigen Anteil, und man denkt, andere werden es schon richten. Der Kollege hält die Krise nicht für harmlos, er hält nur seinen Beitrag für bedeutungslos.","prueffrage":"Ist in dem Satz von einem akuten Notfall die Rede, und was sagt der Kollege über die Gefahr selbst?","rueckmeldung":[{"option":0,"text":"Dass andere ruhig bleiben, kann tatsächlich dazu verleiten, eine Lage für harmlos zu halten. Der Kollege nennt die Krise aber nicht harmlos; er bezweifelt nur, dass sein eigener Beitrag etwas ausrichtet."},{"option":1,"text":"Hier steckt ein wahrer Kern: Mit der Zahl der Anwesenden sinkt die Chance, dass eine einzelne Person hilft. Daraus folgt aber nicht, dass überhaupt niemand mehr eingreift. In Studien zu realen Konflikten griff meist mindestens ein Umstehender ein."},{"option":2,"text":"Die klassischen Experimente dazu stellten tatsächlich Notfälle nach. Verteilte Verantwortung kann aber überall wirken, wo viele beteiligt sind und jeder denkt, die anderen kümmern sich, auch bei großen gesellschaftlichen Problemen wie dem Klima."}],"familie":"verantwortung-benennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Philpot, R.; Liebst, L. S.; Levine, M.; Bernasco, W.; Lindegaard, M. R. (2020): Would I Be Helped? Cross-National CCTV Footage Shows That Intervention Is the Norm in Public Conflicts. American Psychologist 75(1), S. 66–75 (Manuskriptfassung, Lancaster University)","oeffentlich":true,"doi":"10.1037/amp0000469","url":"https://eprints.lancs.ac.uk/id/eprint/134891/1/Would_I_be_Helped_Cross_National_CCTV_Footage_Shows_That_Intervention_Is_the_Norm_in_Public_Conflicts_Postprint.pdf","seite":"PDF-S. 2","abruf":"2026-10-12"},{"typ":"url","kurz":"Barleben, L.; O’Mahony, A. (2026): Bystander Effect. In: Rahal, R.-M. (Hg.): Open Social Psychology. Open Press Tilburg University (CC BY 4.0)","oeffentlich":true,"url":"https://forrt.org/open-social-psychology/chapter13.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9e113021368ce587"}},{"id":"qx-e-021","clusterId":"E","werkstueckRef":"E.2.4","stufe":2,"question":"Mit welcher Planung sorgst du am ehesten dafür, dass die Aufmerksamkeit der Gruppe zur Tragweite der Themen passt?","scenario":"Du leitest die Budgetrunde deines Vereins. Auf der Tagesordnung stehen der Kauf eines neuen Vereinsheims für 400.000 Euro und die Farbe des Kaffeeautomaten für 300 Euro. Aus früheren Sitzungen weißt du: Über die Farbe des Automaten wird erfahrungsgemäß lange und hitzig gestritten, beim Vereinsheim herrscht meist Schweigen, und der Kauf wird nach wenigen Minuten abgenickt.","options":["Du begrenzt die Redezeit jeder Wortmeldung auf wenige Minuten, damit kein einzelnes Mitglied die Aussprache dominiert.","Du beginnst mit dem kleinsten Punkt, damit die Gruppe mit einem schnellen Erfolg warm wird und Vertrauen aufbaut.","Du legst vorab für jeden Punkt ein festes Zeit-Budget fest, das sich an Kosten und Folgen des Themas orientiert.","Du gibst allen Tagesordnungspunkten gleich viel Zeit, damit sich kein Mitglied mit seinem Anliegen übergangen fühlt."],"correctIndex":2,"explanation":"Das Muster beschrieb C. Northcote Parkinson 1957 als „Gesetz der Trivialität“, heute ist es auch als „Bikeshedding“ bekannt: Die Zeit, die eine Gruppe auf einen Punkt verwendet, verhält sich umgekehrt zur Summe, um die es geht. Ein Teil der Erklärung liegt bei den Menschen: Beim Kaffeeautomaten kann jeder mitreden und sich risikofrei einbringen, beim 400.000-Euro-Kauf schweigt man lieber, um sich nicht mit einer „dummen“ Frage zu blamieren. Ein vorab festgelegtes Zeit-Budget nach Kosten und Folgen lenkt die Aufmerksamkeit dorthin, wo viel auf dem Spiel steht. Eine Redezeitbegrenzung bremst einzelne Vielredner, verteilt die Zeit aber nicht nach Tragweite, denn der Kaffeeautomat bliebe mit vielen kurzen Beiträgen weiter ein Dauerthema. Mit dem kleinsten Punkt zu beginnen wärmt nur auf, wenn er kurz bleibt; hier ist er aber genau der Punkt, an dem sich die Runde festbeißt. Gleiche Zeit für alle Punkte klingt gerecht, ignoriert aber, dass 300 Euro und 400.000 Euro nicht gleich viel Aufmerksamkeit verdienen.","coreRule":"⚡ Die Redezeit gehört dorthin, wo die Folgen liegen, nicht dorthin, wo jeder mitreden kann.","beleg":"Werkstück E.2.4 (Das Härten im Feuer: Aktivierungs-Frage und Schmiede-Übung)","status":"entwurf","kurz":"Ein vorab festgelegtes Zeit-Budget nach Kosten und Folgen lenkt die Aufmerksamkeit dorthin, wo viel auf dem Spiel steht. Der naheliegende Fehler: Gesprächszeit folgt oft der Mitredbarkeit eines Themas statt seiner Tragweite.","prueffrage":"Wie verteilte sich die Redezeit in früheren Sitzungen auf Automat und Vereinsheim, und ergab sich das von selbst oder nach Plan?","rueckmeldung":[{"option":0,"text":"Eine Redezeitgrenze bremst einzelne Vielredner. Sie verteilt die Zeit aber nicht nach Tragweite: Beim Kaffeeautomaten gäbe es einfach viele kurze Beiträge, und beim Vereinsheim bliebe das Schweigen."},{"option":1,"text":"Ein schneller Einstieg wärmt nur auf, wenn er kurz bleibt. Der kleinste Punkt ist hier aber genau der, an dem sich die Runde erfahrungsgemäß festbeißt, und so rutscht der große Kauf nach hinten."},{"option":3,"text":"Das Anliegen, niemanden zu übergehen, ist berechtigt. Gleiche Zeit für alle Punkte würde aber 300 Euro und 400.000 Euro gleich behandeln, sodass der kleine Punkt zu viel und der Kauf zu wenig Aufmerksamkeit bekäme."}],"familie":"aufmerksamkeit-nach-folgen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Wikipedia: Law of triviality (Sekundärquelle)","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Law_of_triviality","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Parkinson, C. N. (1957): Parkinson's Law, and Other Studies in Administration. Boston: Houghton Mifflin, Kap. „High Finance, or The Point of Vanishing Interest“","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e2d4a7c4fdeb0f12"}},{"id":"qx-e-022","clusterId":"E","werkstueckRef":"E.2.4","stufe":3,"question":"Du leitest ein Team, das sich zwei Stunden lang über die Gestaltung des Firmenlogos auf den Kaffeetassen gestritten hat. Die Frage, ob ein Lieferant für 1,2 Millionen Euro beauftragt wird, hat die Runde dagegen in drei Minuten ohne Rückfragen durchgewunken. Gegen solche Detaildebatten ist an sich nichts einzuwenden. Woran erkennst du, dass die Diskussion hier ein echtes Problem geworden ist?","options":["Daran, dass einzelne Wortführer die Logo-Debatte bestimmt haben, denn dominante Stimmen verzerren jede Gruppenentscheidung und verdrängen andere Meinungen.","Daran, dass bei der Lieferantenfrage ein Vorgesetzter den Ton angab, denn Mitarbeiter stellen dann keine kritischen Fragen mehr und stimmen einfach zu.","Daran, dass zum Logo mehrere Gegenvorschläge kamen, denn viele Alternativen zeigen, dass die Gruppe das Ziel nicht klar festgelegt hatte.","Daran, dass die Aufmerksamkeit unproportional zur Bedeutung verteilt ist, denn das Triviale bindet die Denkkraft der Gruppe, während das teure Risiko ungeprüft bleibt."],"correctIndex":3,"explanation":"Eine kurze Detaildebatte kann nützlich sein: Ein lösbares kleines Problem gibt der Gruppe ein schnelles Erfolgserlebnis, schafft Vertrauen und wärmt für schwierigere Themen auf. Schädlich wird es erst, wenn die Zeit nicht mehr im Verhältnis zur Tragweite der Themen steht. Dann ist die gemeinsame Denkkraft an Belangloses gebunden, während Entscheidungen mit hohen Kosten und möglichen Folgeschäden unbesehen durchgehen. Das Warnsignal ist also nicht, dass Details besprochen werden, sondern ein Missverhältnis: am hitzigsten bei den einfachen Themen, am ruhigsten bei den komplexen. Dominante Wortführer wären ein eigenes Problem, im beschriebenen Fall wird davon aber nichts berichtet. Ein Vorgesetzter, der den Ton angibt, ist ebenfalls nicht erwähnt. Und mehrere Logo-Vorschläge würden allenfalls auf unklare Ziele deuten, sagen aber nichts über das Missverhältnis zum teuren Vertrag.","coreRule":"⚡ Aufwärmen ist erlaubt – ein Problem wird es, wenn die Gruppe nie darüber hinauskommt.","beleg":"Werkstück E.2.4 (Das Adaptive Talent; Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Warnzeichen ist das Missverhältnis zwischen Zeitaufwand und Tragweite: Zwei Stunden für ein Logo, drei Minuten für 1,2 Millionen Euro. So bleibt Denkkraft am Belanglosen hängen, während das teure Risiko ungeprüft durchgeht.","prueffrage":"Was stünde auf dem Spiel, wenn das Tassenlogo misslingt, und was, wenn der falsche Lieferant den Auftrag bekommt?","rueckmeldung":[{"option":0,"text":"Wortführer können Gruppen tatsächlich verzerren. Im beschriebenen Fall wird davon aber nichts berichtet, und auch bei ausgeglichenen Beiträgen bliebe das Problem: Es liegt in der Verteilung der Zeit, nicht darin, wer spricht."},{"option":1,"text":"Ein dominanter Vorgesetzter kann kritische Fragen ersticken und wäre ein eigenes Problem. Im Szenario steht davon jedoch nichts, nur dass die Runde zustimmte. Was der Fall zeigt, ist das Missverhältnis zwischen Aufwand und Tragweite."},{"option":2,"text":"Viele Gegenvorschläge können auf unklare Ziele hindeuten, müssen es aber nicht, bei Gestaltungsfragen sind sie ohnehin üblich. Vor allem sagen sie nichts darüber, warum der teure Vertrag in drei Minuten durchging."}],"familie":"aufmerksamkeit-nach-folgen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Wikipedia: Law of triviality (Sekundärquelle)","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Law_of_triviality","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Parkinson, C. N. (1957): Parkinson's Law, and Other Studies in Administration. Boston: Houghton Mifflin, Kap. „High Finance, or The Point of Vanishing Interest“","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"7ab056205f42fa34"}},{"id":"qx-e-023","clusterId":"E","werkstueckRef":"E.2.4","stufe":4,"question":"Du liest in einem Forum: Seit Tagen füllen Mitglieder Seite um Seite mit der Frage, ob ein gefilmter Lichtpunkt einen Bogen von 12 oder 15 Grad beschreibt. Ob die Theorie überhaupt mit der Physik vereinbar ist, fragt niemand. Welche Einordnung passt am besten zu dem, was du siehst?","options":["Die Gruppe verhandelt ausgiebig ein kleines, für alle greifbares Detail und umgeht damit die schwierige Frage, an der die ganze Theorie hängt.","Die Gruppe hat die physikalischen Widersprüche längst gründlich geprüft und gemeinsam als widerlegt verworfen, sodass nur noch Details offen sind.","Alle Mitglieder halten die Theorie privat für falsch, glauben aber, alle anderen glaubten sie, und schweigen deshalb zu den Widersprüchen.","Die Mitglieder gehen davon aus, dass andere die physikalischen Fragen schon geklärt haben, und vertrauen deshalb auf die Theorie."],"correctIndex":0,"explanation":"Hier verteilt sich die Aufmerksamkeit umgekehrt zur Bedeutung der Themen: Über das Detail kann jeder mitreden, es ist konkret, ungefährlich und bietet eine Bühne. Die physikalische Gesamtfrage ist anstrengend und riskant, denn wer sie stellt, könnte die eigene Unwissenheit preisgeben. Deshalb wird dort geschwiegen, wo es zählt. Die zweite Deutung scheitert, weil eine gründliche Prüfung irgendwo sichtbar sein müsste, im Beispiel aber gerade fehlt. Die dritte unterstellt, alle zweifelten privat; im Beispiel steht davon nichts, und das Verhalten wird durch die einfache Verteilung der Aufmerksamkeit besser erklärt. Die vierte unterstellt, andere hätten die Frage beantwortet, obwohl nirgends davon die Rede ist. Als nächsten Schritt kannst du fragen: Wie viel Diskussionszeit entfällt auf das Detail, und wie viel auf die Frage, ob das Ganze überhaupt stimmen kann?","coreRule":"⚡ Wer nur über Details streitet, die jeder versteht, umgeht oft gerade die Frage, an der alles hängt.","beleg":"Werkstück E.2.4 (Anwendung & Relevanz: In Verschwörungsgemeinschaften; Verbindungen)","status":"entwurf","scenario":"","kurz":"Über das Detail kann jeder mitreden, es ist konkret und ungefährlich. Die Frage, ob die Theorie überhaupt zur Physik passt, ist anstrengend und riskant, und genau dort, wo es zählt, wird geschwiegen. Aufmerksamkeit folgt hier der Bequemlichkeit, nicht der Bedeutung.","prueffrage":"Was müsste im Forum zu finden sein, wenn die physikalische Frage längst geklärt wäre, und findet es sich dort?","rueckmeldung":[{"option":1,"text":"Dass nur noch Details diskutiert werden, könnte nach abgeschlossener Prüfung aussehen. Eine solche Prüfung ist im Forum aber nirgends sichtbar, die Frage nach der Vereinbarkeit mit der Physik wird schlicht nicht gestellt."},{"option":2,"text":"Schweigen kann tatsächlich aus unausgesprochenem Zweifel entstehen. Für private Zweifel gibt es hier aber keinen Hinweis, und das Verhalten lässt sich schon dadurch erklären, dass das greifbare Detail leichter zu diskutieren ist."},{"option":3,"text":"Dass jemand glaubt, andere hätten die Sache längst geklärt, kommt in Gruppen vor. Hier ist es eine Zusatzannahme: Nichts deutet darauf hin, dass die Mitglieder so etwas annehmen oder dass jemand die physikalischen Fragen je beantwortet hätte."}],"familie":"aufmerksamkeit-nach-folgen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Wikipedia: Law of triviality (Sekundärquelle)","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Law_of_triviality","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Parkinson, C. N. (1957): Parkinson's Law, and Other Studies in Administration. Boston: Houghton Mifflin, Kap. „High Finance, or The Point of Vanishing Interest“","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"76123cc35accecad"}},{"id":"qx-e-024","clusterId":"E","werkstueckRef":"E.2.5","stufe":1,"question":"In einer Abteilung gilt seit Jahren die Regel, Entscheidungen erst nach drei Abstimmungsrunden zu treffen. Bei einer anonymen Umfrage stellt sich heraus: Fast alle halten die Regel privat für überflüssig, jeder dachte aber, die anderen fänden sie sinnvoll. Was beschreibt diese Lage am besten?","options":["Eine Mehrheit folgt öffentlich einer Norm, die sie privat ablehnt, weil sie fälschlich annimmt, die anderen stünden dahinter.","Eine Minderheit passt sich öffentlich einer offen geäußerten Mehrheitsmeinung an, obwohl sie privat anders denkt.","Die Mitarbeiter befolgen die Regel aus Gehorsam gegenüber einer Anweisung der Leitung, obwohl sie sie privat ablehnen.","Die Abteilung bevorzugt aus Gewohnheit den Status quo, weil Veränderungen riskanter erscheinen als eine überflüssige Regel."],"correctIndex":0,"explanation":"Typisch für diese Lage ist die Lücke zwischen privater Überzeugung und öffentlichem Verhalten. Jeder sieht nur das konforme Verhalten der anderen und deutet es fälschlich als deren echte Meinung. Das eigene Mitmachen wird dann von den anderen wiederum als Beleg gelesen, dass „alle“ die Regel stützen, und die Illusion verstärkt sich selbst. Anders als bei gewöhnlicher Konformität, wo sich eine Minderheit an eine tatsächliche Mehrheitsmeinung anpasst, passt sich hier eine Mehrheit an eine nur eingebildete Mehrheitsmeinung an. Die anonyme Umfrage ist das passende Prüfwerkzeug: Sie macht die privaten Überzeugungen sichtbar, die das öffentliche Schweigen verdeckt. Eine offen geäußerte Mehrheitsmeinung gibt es hier gerade nicht, denn niemand hat die Regel je kritisiert oder verteidigt. Von einer Anweisung der Leitung ist keine Rede. Und Gewohnheit könnte das Festhalten erklären, nicht aber die falsche Annahme über die anderen, die hier den Kern bildet.","coreRule":"⚡ Wenn alle schweigen oder mitmachen, weißt du noch nicht, was sie denken. Prüfe die private Überzeugung, nicht nur das sichtbare Verhalten.","beleg":"Werkstück E.2.5 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"Eine Abteilung hält an einer umständlichen Abstimmungsregel fest. Niemand hat sie je offen kritisiert. Erst die anonyme Umfrage zeigt, dass fast alle sie ablehnen.","kurz":"Fast alle lehnen die Regel privat ab, glauben aber, die anderen stünden dahinter, weil sie nur deren Mitmachen sehen. Gewöhnliche Konformität setzt eine echte Mehrheitsmeinung voraus; hier folgt eine Mehrheit einer nur eingebildeten.","prueffrage":"Was wissen die Beteiligten über die tatsächliche Meinung der anderen, und woran würdest du das erkennen?","rueckmeldung":[{"option":1,"text":"Öffentliches Mitmachen trotz anderer privater Haltung stimmt. Aber hier passt sich keine Minderheit an eine geäußerte Mehrheitsmeinung an: Fast alle denken privat gleich, und niemand hat die Regel je offen verteidigt oder kritisiert."},{"option":2,"text":"Dass die Regel privat abgelehnt und doch befolgt wird, trifft zu. Von einer Anweisung der Leitung steht im Szenario aber nichts; die Lage erklärt sich daraus, dass jeder die anderen für Befürworter hält."},{"option":3,"text":"Gewohnheit kann erklären, warum an der Regel festgehalten wird. Sie erklärt aber nicht, warum jeder glaubt, die anderen fänden die Regel sinnvoll, und genau diese falsche Annahme bildet hier den Kern."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Schroeder, C. M.; Prentice, D. A. (1998): Exposing Pluralistic Ignorance to Reduce Alcohol Use Among College Students. Journal of Applied Social Psychology 28(23), S. 2150–2180 (Kopie Stanford SPARQ)","oeffentlich":true,"url":"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/schroeder_prentice_1998_-_exposing_pluralistic_ignorance.pdf","seite":"S. 2151–2153","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Prentice, D. A.; Miller, D. T. (1993): Pluralistic ignorance and alcohol use on campus. Journal of Personality and Social Psychology 64(2), S. 243–256","oeffentlich":false,"doi":"10.1037/0022-3514.64.2.243"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"688dbef00330e83b"}},{"id":"qx-e-025","clusterId":"E","werkstueckRef":"E.2.5","stufe":3,"question":"Eine Studie unter Studierenden eines Campus ergibt: Die meisten geben an, die dort üblichen Trinkgewohnheiten seien ihnen selbst eher unangenehm, vermuten das aber beim durchschnittlichen Kommilitonen nicht. Im Lauf eines Semesters nähern sich die befragten Männer in ihrer Haltung der vermuteten Norm an, die befragten Frauen nicht. Der Geschlechterunterschied war nicht vorhergesagt, die Auswertung beruht auf nur 50 telefonisch Befragten, und der Effekt ist statistisch knapp. Was ist die vernünftigste Schlussfolgerung?","options":["Der Befund spricht dafür, dass die Gruppe sich über die Haltung der anderen irrt; der Geschlechterunterschied ist dagegen nur vorläufig und braucht größere Stichproben.","Der Befund beweist, dass Männer grundsätzlich stärker unter Gruppendruck stehen als Frauen, denn der Unterschied zeigte sich im Lauf eines Semesters.","Der Befund ist wertlos, weil Studien mit 50 Personen nichts über Gruppenverhalten sagen und beide Teilergebnisse damit entfallen.","Der Befund zeigt, dass die Studierenden sich über ihre Gewohnheiten selbst belogen haben, denn Selbstauskünfte sind nie verlässlich."],"correctIndex":0,"explanation":"Zwei Teilbefunde tragen unterschiedlich viel. Dass Menschen die Haltung der anderen falsch einschätzen, zeigte sich in vier Studien derselben Arbeit: Die eigenen Werte streuten breit, die vermuteten Werte der anderen lagen dicht beieinander. Auch an einer anderen Universität fanden Suls und Green im Grundmuster dasselbe. Der Geschlechterunterschied im Semesterverlauf dagegen stammt aus einer kleinen Stichprobe, war nicht vorhergesagt und lag statistisch knapp an der Signifikanzgrenze. So etwas kann Zufall sein und braucht Bestätigung, bevor man daraus ein Gesetz über Männer und Frauen macht. Alles zu verwerfen, was eine kleine Studie zeigt, wäre ebenso voreilig wie zu verallgemeinern: Eine kleine Stichprobe schwächt die Sicherheit, sie macht den Befund nicht wertlos. Und Selbstauskünfte sind fehleranfällig, aber kein Beweis für Lüge; gerade dass Suls und Green das Grundmuster auch an einer anderen Universität fanden, stützt den Kernbefund.","coreRule":"⚡ Trenne gut gestützte Befunde von vorläufigen: Eine kleine Stichprobe und ein nicht vorhergesagter, knapper Unterschied verlangen Vorsicht, aber keine Verwerfung.","beleg":"Werkstück E.2.5 (Anwendung & Relevanz: Bei sozialen Normen); Fn. gl-e-prentice (Prentice & Miller 1993, S. 243–249; Vorbehalt S. 248 f.); Anmerkung anm-gl-e-prentice (Studie 1; Suls & Green 2003)","status":"entwurf","scenario":"","kurz":"Der Kernbefund, dass man die Haltung der anderen falsch einschätzt, ist breit gestützt. Der Geschlechterunterschied stammt aus einer kleinen Stichprobe, war nicht vorhergesagt und ist knapp: Das kann Zufall sein und braucht Bestätigung.","prueffrage":"Welche Schwächen nennt die Beschreibung der Studie, und betreffen sie jede ihrer Aussagen gleich stark?","rueckmeldung":[{"option":1,"text":"Dass sich der Unterschied erst im Semesterverlauf zeigte, wirkt wie eine echte Dynamik. Ein Beweis ist das nicht: Der Effekt ist knapp, beruht auf nur 50 Befragten und war nicht vorhergesagt; ein Gesetz über Männer und Frauen folgt daraus nicht."},{"option":2,"text":"Eine kleine Stichprobe macht Ergebnisse unsicherer, das stimmt. Sie macht sie aber nicht wertlos: Der Kernbefund stammt aus vier Studien und fand sich an einer anderen Universität im Grundmuster wieder. Verworfen wird hier zu viel."},{"option":3,"text":"Selbstauskünfte sind tatsächlich fehleranfällig, doch daraus folgt keine Lüge, und „nie verlässlich“ ist zu absolut. Es geht auch nicht um die eigene Haltung, sondern um die falsche Einschätzung der anderen, und die bestätigte sich auch anderswo."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Schroeder, C. M.; Prentice, D. A. (1998): Exposing Pluralistic Ignorance to Reduce Alcohol Use Among College Students. Journal of Applied Social Psychology 28(23), S. 2150–2180 (Kopie Stanford SPARQ)","oeffentlich":true,"url":"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/schroeder_prentice_1998_-_exposing_pluralistic_ignorance.pdf","seite":"S. 2152–2153","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Prentice, D. A.; Miller, D. T. (1993): Pluralistic ignorance and alcohol use on campus. Journal of Personality and Social Psychology 64(2), S. 243–256","oeffentlich":false,"doi":"10.1037/0022-3514.64.2.243"},{"typ":"literatur","kurz":"Suls, J.; Green, P. (2003): Pluralistic Ignorance and College Student Perceptions of Gender-Specific Alcohol Norms. Health Psychology 22(5), S. 479–486","oeffentlich":false,"doi":"10.1037/0278-6133.22.5.479"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9dbbc1d4fbdae1d1"}},{"id":"qx-e-026","clusterId":"E","werkstueckRef":"E.2.5","stufe":2,"question":"Welches Vorgehen ist hier am sinnvollsten, um herauszufinden, ob wirklich alle anderen den Plan gut finden, ohne dich selbst zu sehr zu exponieren?","scenario":"Im Projektmeeting stellt dein Chef einen Plan vor, der deiner Ansicht nach ein klares Problem hat. Alle nicken, niemand sagt etwas. Du hältst dich für den Einzigen, der zweifelt und überlegst, was du tun sollst.","options":["Den Plan in Ruhe gegen das Projektziel prüfen und das erkannte Problem dabei genauer fassen.","Eine Liste mit Vor- und Nachteilen anlegen und deinen Zweifel nüchtern dagegen abwägen.","Vom Chef die Belege für den Plan verlangen und seine Annahmen Schritt für Schritt nachprüfen.","Deinen Zweifel als offene Frage stellen und beobachten, wie die anderen im Raum darauf reagieren."],"correctIndex":3,"explanation":"Nicken und Schweigen sind nur öffentliches Verhalten, sie verraten nicht, was die anderen privat denken. Vielleicht zweifeln mehrere und schweigen aus demselben Grund wie du: Jeder hält sich für den Einzigen. Eine offene Frage ist ein günstiger Test: Das Risiko bleibt klein, dein Zweifel kommt trotzdem auf den Tisch, und oft äußern daraufhin andere ihre Bedenken. Den Plan gegen das Projektziel zu prüfen oder Vor- und Nachteile abzuwägen klärt den Plan selbst, verrät aber nichts über die Haltung der anderen. Belege vom Chef zu verlangen kann sinnvoll sein, zeigt aber ebenfalls nicht, was die Kollegen denken, und stellt dich stärker bloß als eine Frage.","coreRule":"⚡ Schweigen ist kein Beweis für Zustimmung: Eine offene Frage prüft, was die anderen denken, ohne dass du gleich angreifen musst.","beleg":"Werkstück E.2.5 (Das Härten im Feuer: Der mutige Test; Aktivierungs-Frage)","status":"entwurf","kurz":"Nicken und Schweigen sind nur Verhalten und verraten nicht, was die anderen denken; womöglich zweifeln mehrere und halten sich jeweils für den Einzigen. Eine offene Frage testet das günstig: Sie bringt deinen Zweifel auf den Tisch und lässt die Reaktionen sichtbar werden.","prueffrage":"Was zeigt dir das Verhalten der anderen im Raum tatsächlich, und was kannst du daraus nicht ablesen?","rueckmeldung":[{"option":0,"text":"Den Plan gegen das Projektziel zu prüfen klärt, wie belastbar dein Einwand ist. Über die anderen erfährst du dabei aber nichts, und genau danach fragt die Aufgabe: Auch bei einem klar gefassten Problem bleibt offen, wer sonst zweifelt."},{"option":1,"text":"Eine nüchterne Abwägung ordnet deine Gedanken und kann den Zweifel schärfen. Sie bleibt aber eine Rechnung in deinem Kopf: Ob andere ähnlich zweifeln, zeigt sie nicht, und dein Einwand wird dadurch auch nicht sichtbar."},{"option":2,"text":"Belege und Annahmen nachzuprüfen kann durchaus sinnvoll sein, um den Plan zu beurteilen. Über die Haltung der Kollegen sagt es aber ebenso wenig, und du stellst dich damit stärker bloß als mit einer einfachen Frage."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Schroeder, C. M.; Prentice, D. A. (1998): Exposing Pluralistic Ignorance to Reduce Alcohol Use Among College Students. Journal of Applied Social Psychology 28(23), S. 2150–2180 (Kopie Stanford SPARQ)","oeffentlich":true,"url":"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/schroeder_prentice_1998_-_exposing_pluralistic_ignorance.pdf","seite":"S. 2151–2153","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Prentice, D. A.; Miller, D. T. (1993): Pluralistic ignorance and alcohol use on campus. Journal of Personality and Social Psychology 64(2), S. 243–256","oeffentlich":false,"doi":"10.1037/0022-3514.64.2.243"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"05b755d1adcb79c4"}},{"id":"qx-e-027","clusterId":"E","werkstueckRef":"E.2.6","stufe":1,"question":"Ein Kind spielt gern mit einem Wellensittich. Eines Tages erschrickt es heftig, als genau dann ein Glas laut zerspringt. Nach mehreren ähnlichen Vorfällen weint das Kind schon beim bloßen Anblick des Vogels, noch bevor irgendein Geräusch zu hören ist. Wie lässt sich die Rolle des zerspringenden Glases am besten beschreiben?","options":["Es ist der Reiz, der von selbst Schreck auslöst, ohne dass das Kind etwas lernen musste; durch die Kopplung bekam der Vogel die Wirkung.","Es ist der anfangs neutrale Reiz, der erst durch die Kopplung mit dem Vogel seine Wirkung auf das Kind erhält.","Es ist der Reiz, auf den das Kind nach einigen Wiederholungen mit Angst reagiert, auch wenn nur der Vogel zu sehen ist.","Es ist die Belohnung dafür, dass das Kind den Vogel anfasst, und verstärkt dieses Verhalten bei Wiederholung."],"correctIndex":0,"explanation":"Ein Glas, das laut zerspringt, erschreckt von Natur aus; dafür muss das Kind nichts lernen. Der Vogel war zunächst neutral: Das Kind spielte gern mit ihm. Weil beides mehrfach zusammen auftrat, wurde der Vogel zum Auslöser der Angst, auch ohne Knall. Der Schreckreiz ist also der Auslöser, der von selbst wirkt, der Vogel dagegen der gelernte Auslöser. Eine Belohnung ist der Knall nicht: Er macht das Anfassen nicht wahrscheinlicher, er verknüpft den Vogel mit Angst. Wichtig für die Einschätzung: Ein einzelner Fall zeigt den Mechanismus, sagt aber nicht, ob die Angst dauerhaft bleibt oder sich wieder abschwächt.","coreRule":"⚡ Wenn ein neutraler Reiz oft genug mit einem Reiz gekoppelt wird, der von selbst eine Reaktion auslöst, löst der neutrale Reiz irgendwann allein diese Reaktion aus. Prüfe immer: Welcher Reiz wirkt von Anfang an, und welcher hat die Wirkung erst gelernt?","beleg":"Werkstück E.2.6 (Einstieg; Kernidee); Fn. gl-e-little-albert (Watson & Rayner 1920, S. 2–12). Szenario als Transfer des Albert-Experiments auf neue Situation (Kind, Vogel, Glas) gebaut; keine neuen Studien oder Zahlen.","status":"entwurf","scenario":"Ein Kind spielt gern mit einem Wellensittich. Wiederholt zerspringt im selben Moment ein Glas, das Kind erschrickt heftig. Nach einigen solchen Vorfällen weint es schon beim Anblick des Vogels, noch bevor irgendein Geräusch zu hören ist.","kurz":"Das Glas schreckt von selbst, ohne dass das Kind etwas lernen musste. Der Vogel war anfangs neutral und wurde erst durch das gemeinsame Auftreten zum Auslöser der Angst. Man verwechselt leicht, welcher Reiz von Anfang an wirkt und welcher erst gelernt wird.","prueffrage":"Wie reagierte das Kind auf den Vogel, bevor das erste Glas zersprang, und wie nach mehreren Vorfällen?","rueckmeldung":[{"option":1,"text":"Die Beschreibung passt zu einem Lernvorgang, trifft aber den Vogel: Er war anfangs neutral und gewann seine Wirkung erst durch die Kopplung. Das Glas dagegen erschreckt von Natur aus, dafür braucht es keine Verbindung."},{"option":2,"text":"Dass das Kind schon beim Anblick weint, stimmt und ist der Kern des Falls. Diese gelernte Reaktion hängt aber am Vogel, nicht am Glas: Der Knall erschreckt von Anfang an, auch ohne dass irgendetwas gelernt wurde."},{"option":3,"text":"Der Knall belohnt nichts, denn er macht das Anfassen nicht wahrscheinlicher. Er erschreckt das Kind und verknüpft dadurch den Vogel mit Angst; eine Verstärkung von Verhalten steht hier gar nicht im Mittelpunkt."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Watson, J. B.; Rayner, R. (1920): Conditioned Emotional Reactions. Journal of Experimental Psychology 3(1), 1–14 (Volltext in Classics in the History of Psychology, York University)","oeffentlich":true,"doi":"10.1037/h0069608","url":"https://psychclassics.yorku.ca/Watson/emotion.htm","abruf":"2026-10-12"},{"typ":"url","kurz":"OpenStax (Rice University): Psychology 2e, Kap. 6.2 Classical Conditioning","oeffentlich":true,"url":"https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"8a2839fd9b9d2241"}},{"id":"qx-e-028","clusterId":"E","werkstueckRef":"E.2.6","stufe":2,"question":"Welcher Mechanismus erklärt am besten, warum diese Werbung auch ohne ein einziges Sachargument wirken kann?","scenario":"In einem Spot sitzen lachende Freunde am Strand, ein Kind rennt jubelnd durch die Wellen, dazwischen taucht immer wieder dieselbe Limonadenflasche auf. Der Spot läuft wochenlang jeden Abend. Eine Kollegin sagt: „Dass mir die Limo sympathisch ist, liegt an ihrem Geschmack. Ich habe den Spot kaum beachtet.“","options":["Das Produkt wird wiederholt mit Reizen gekoppelt, die von selbst Freude auslösen, und löst irgendwann allein ein Wohlgefühl aus.","Zuschauer übernehmen das Urteil einer fachkundigen Person, die das Produkt im Spot empfiehlt, und bewerten es dadurch besser.","Der Spot erweckt den Eindruck, das Produkt sei bald knapp, und Zuschauer bewerten es höher, weil sie fürchten, es zu verpassen.","Der Spot baut eine frühere negative Verknüpfung mit dem Produkt Schritt für Schritt ab, bis das Produkt wieder neutral wirkt."],"correctIndex":0,"explanation":"Der Spot enthält kein Argument über die Limonade selbst. Er zeigt sie immer wieder zusammen mit Dingen, die von sich aus Freude auslösen: lachende Menschen, Sonne, ein jubelndes Kind. Nach genug Wiederholungen kann schon das Produkt allein ein angenehmes Gefühl auslösen, oft ohne dass man es bemerkt. Dieselbe Technik funktioniert auch umgekehrt: Wer eine Person oder Gruppe wiederholt mit bedrohlicher Musik oder Angstbildern koppelt, kann Abneigung erzeugen. Eine fachkundige Person, deren Urteil man übernehmen könnte, kommt im Spot nicht vor. Von Knappheit ist keine Rede, der Spot läuft ja wochenlang jeden Abend. Und eine ältere negative Verknüpfung, die abgebaut würde, gibt es hier nicht.","coreRule":"⚡ Frag bei Werbung: Welcher Reiz soll hier welches Gefühl auf welches Produkt übertragen, und was wird dabei gar nicht argumentiert?","beleg":"Werkstück E.2.6 (Anwendung & Relevanz: In der Propaganda und Werbung; Schmiede-Übung)","status":"entwurf","kurz":"Der Spot bringt kein Sachargument, sondern koppelt die Flasche wiederholt mit Dingen, die von selbst Freude auslösen. So kann schon das Produkt allein ein gutes Gefühl wecken, oft unbemerkt. Wer ihn „kaum beachtet“, ist deshalb nicht immun.","prueffrage":"Was wüsstest du über diese Limonade, wenn du den Spot nur zusammenfasst, und was zeigt er stattdessen?","rueckmeldung":[{"option":1,"text":"Dass Urteile von Fachleuten Einstellungen verschieben können, stimmt. Im Spot empfiehlt aber niemand die Limonade: Es gibt nur Freunde, ein Kind und die Flasche. Ein Urteil zum Übernehmen fehlt."},{"option":2,"text":"Verknappung kann Begehrlichkeit tatsächlich steigern. Hier gibt es dafür keinen Anhaltspunkt: Der Spot läuft wochenlang jeden Abend und deutet nirgends an, dass die Limonade bald fehlen könnte."},{"option":3,"text":"Wiederholte Kopplung ist hier richtig erkannt. Es fehlt aber ein Anlass für die Annahme, die Limonade sei vorher negativ besetzt gewesen. Es wird also nichts abgebaut, sondern ein gutes Gefühl neu aufgebaut."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"OpenStax (Rice University): Psychology 2e, Kap. 6.2 Classical Conditioning (Abschnitt zu Werbung)","oeffentlich":true,"url":"https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning","abruf":"2026-10-12"},{"typ":"url","kurz":"Hofmann, W.; De Houwer, J.; Perugini, M.; Baeyens, F.; Crombez, G. (2010): Evaluative conditioning in humans: a meta-analysis. Psychological Bulletin 136(3), 390–421 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1037/a0018916","url":"https://pubmed.ncbi.nlm.nih.gov/20438144/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f577de5c34d3f839"}},{"id":"qx-e-029","clusterId":"E","werkstueckRef":"E.2.6","stufe":3,"question":"Welche Erklärung beschreibt seinen Lernprozess am sparsamsten?","options":["Sein Verhalten verändert sich, weil es Folgen hatte: Belohntes wird häufiger gezeigt, Bestraftes seltener.","Ein zuvor neutraler Reiz wurde wiederholt mit einem Reiz gekoppelt, der von sich aus eine Reaktion auslöst.","Eine zuvor erlernte Angst wurde durch wiederholte positive Erlebnisse im Forum schrittweise überschrieben.","Eine einmal erlernte Angst hat sich auf viele ähnliche Situationen im Forum ausgebreitet."],"correctIndex":0,"explanation":"Der Nutzer lernt aus den Konsequenzen seines eigenen Verhaltens: Anpassung bringt Zuspruch und Ränge (Belohnung), Abweichung bringt Ignorieren oder Tadel (Bestrafung). Das Muster heißt operante Konditionierung (Skinner). Bei der klassischen Konditionierung wird dagegen ein Reiz mit einem anderen gekoppelt, ohne dass das eigene Verhalten Folgen hätte, wie bei der Ratte und dem Lärm im Fall des „kleinen Albert“; hier gibt es weder einen solchen Auslöser noch eine Angst, die überschrieben wird oder sich ausbreitet. Entscheidend ist die Frage, ob das Verhalten selbst belohnt oder bestraft wird. Gruppen, die Abweichung bestrafen und Anpassung stark belohnen, können ihre Mitglieder so Schritt für Schritt auf Linie bringen, besonders wenn sie Zustimmung wie in einem Spiel mit Punkten und Rängen belohnen.","coreRule":"⚡ Klassisch lernt man Verknüpfungen von Reizen, operant lernt man aus den Folgen des eigenen Tuns.","beleg":"Werkstück E.2.6 (Kontext & Tiefe: Operante Konditionierung; Red Flags)","status":"entwurf","scenario":"Ein Forum vergibt Zuspruch und Ränge für Beiträge auf Gruppenlinie; abweichende Beiträge werden ignoriert oder getadelt. Ein Nutzer postet zweimal eine Meinung, die von der Linie abweicht, und wird beide Male ignoriert oder getadelt. Danach schreibt er nur noch Beiträge, die der Linie folgen und ihm Zuspruch und Ränge bringen.","quote":"","quoteLabel":"","kurz":"Der Nutzer lernt aus den Folgen seines eigenen Verhaltens: Anpassung bringt Zuspruch und Ränge, Abweichung bringt Ignorieren oder Tadel. Bei einer bloßen Reizkopplung hätte sein Handeln dagegen keine Folgen, hier entscheidet es über Belohnung und Strafe.","prueffrage":"Zeigt der Nutzer irgendwo Angst oder Rückzug, und was genau hat sich an seinen Beiträgen verändert?","rueckmeldung":[{"option":1,"text":"Zuspruch und Tadel kommen hier nicht von selbst, sondern erst nachdem er etwas geschrieben hat. Eine Kopplung zweier Reize, bei der das eigene Verhalten folgenlos bleibt, beschreibt das nicht: Sein Posten wird belohnt oder bestraft."},{"option":2,"text":"Positive Erlebnisse spielen tatsächlich eine Rolle, denn Zuspruch und Ränge belohnen sein Verhalten. Von einer früher erlernten Angst, die dabei überschrieben würde, ist aber nichts zu erkennen; es geht um die Folgen seines Postens."},{"option":3,"text":"Eine Angst, die sich auf ähnliche Situationen ausbreitet, würde eher zu Rückzug aus dem Forum führen. Der Nutzer schreibt aber gezielt angepasst weiter, und Anzeichen von Angst werden nirgends beschrieben."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"OpenStax (Rice University): Psychology 2e, Kap. 6.3 Operant Conditioning","oeffentlich":true,"url":"https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning","abruf":"2026-10-12"},{"typ":"url","kurz":"Watson, J. B.; Rayner, R. (1920): Conditioned Emotional Reactions. Journal of Experimental Psychology 3(1), 1–14 (Volltext in Classics in the History of Psychology)","oeffentlich":true,"doi":"10.1037/h0069608","url":"https://psychclassics.yorku.ca/Watson/emotion.htm","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3cf93af47b96bf45"}},{"id":"qx-e-030","clusterId":"E","werkstueckRef":"E.2.6","stufe":4,"question":"Welche Erklärung für die Rückkehr der Angst ist die sparsamste?","options":["Die alte Angstverbindung wurde nie gelöscht, sondern nur von einer neuen, hemmenden Erfahrung überlagert; unter neuen Umständen und nach einem Schreck kann die Angst wieder durchbrechen.","Die Angst wurde neu durch Beobachtung gelernt: In der neuen Stadt hat die Frau gesehen, wie andere Menschen auf Spinnen mit Panik reagieren, und diese Reaktion übernommen.","Die Angst blieb durch Vermeidung am Leben: Wer Auslösern ausweicht, erlebt Erleichterung, und diese Erleichterung hält die Angst über viele Jahre unverändert aufrecht.","Die Angst hat sich durch Reizgeneralisierung ausgeweitet: Nun löst schon Panik aus, was Spinnen bloß ähnelt, und nicht mehr allein die Spinne, die sie ursprünglich fürchtete."],"correctIndex":0,"explanation":"Die Rückkehr der Angst an einem neuen Ort und nach einem Schreck passt dazu, dass Löschung eine Reaktion eher unterdrückt als beseitigt: Neben die ursprüngliche Verknüpfung tritt eine zweite, hemmende, und die erste bleibt im Hintergrund erhalten. Dass Angst nach einer Pause, bei einem Ortswechsel oder nach einem Schreck zurückkehren kann, ist gut beobachtet und stützt genau das. Das beschreibt einen Mechanismus und ist keine Behandlungsempfehlung für den Einzelfall. Beobachtungslernen ist ein echter Weg zu Ängsten, setzt hier aber voraus, dass die Frau andere panisch reagieren sah, wovon nichts berichtet wird. Aufrechterhaltung durch Vermeidung gibt es, sie passt aber nicht zu jahrelanger Symptomfreiheit nach erfolgreicher Konfrontation. Und Generalisierung erklärt Panik vor ähnlichen Auslösern, nicht aber die Rückkehr der Angst vor dem ursprünglichen Auslöser, einer echten Spinne.","coreRule":"⚡ Verlernen heißt meist Überlagern: Das alte Gelernte bleibt im Hintergrund erhalten. Wiederkehr nach Jahren ist deshalb kein Beweis für ein Scheitern.","beleg":"Werkstück E.2.6 (Die entscheidende Waffe: Gegenkonditionierung & Desensibilisierung); Fn. gl-e-exposition (Craske u. a. 2014, S. 10–23; Myers 2014, S. 296)","status":"entwurf","scenario":"Eine Frau hat ihre Spinnenphobie mit schrittweiser Konfrontation erfolgreich überwunden und blieb jahrelang symptomfrei. Nach einem Umzug in eine andere Stadt erschreckt sie eine Spinne im Treppenhaus, und die alte Panik ist plötzlich wieder da. Ihre Freundin meint: „Dann hat die Therapie damals eben nicht richtig gewirkt.“","quote":"","quoteLabel":"","kurz":"Löschung unterdrückt eine Angstreaktion eher, als sie zu beseitigen: Eine hemmende Verknüpfung tritt neben die alte, die im Hintergrund bleibt. Wie eine nie gewirkte Therapie wirkt das nur, wenn man übersieht, dass neuer Ort und Schreck die Angst wieder durchbrechen lassen können.","prueffrage":"Was ist über die Therapie und die Jahre danach tatsächlich bekannt, und was wird nur vermutet?","rueckmeldung":[{"option":1,"text":"Beobachtungslernen ist ein echter Weg zu Ängsten. Hier setzt die Erklärung aber voraus, dass die Frau andere panisch reagieren sah, wovon nichts berichtet wird. So wird eine Tatsache ergänzt, statt das Gegebene zu erklären."},{"option":2,"text":"Vermeidung hält Ängste tatsächlich oft aufrecht, weil Ausweichen Erleichterung bringt. Hier bleibt die Angst aber nicht bestehen: Sie war nach der Konfrontation jahrelang verschwunden und kehrt erst später plötzlich zurück."},{"option":3,"text":"Generalisierung gibt es, sie erklärt aber Panik vor Reizen, die dem Auslöser nur ähneln. Die Frau erschrickt hier vor einer echten Spinne, also vor dem ursprünglichen Auslöser, und genau dessen Rückkehr bleibt damit offen."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Craske, M. G.; Treanor, M.; Conway, C. C.; Zbozinek, T.; Vervliet, B. (2014): Maximizing exposure therapy: An inhibitory learning approach. Behaviour Research and Therapy 58, 10–23 (PMC-Volltext)","oeffentlich":true,"doi":"10.1016/j.brat.2014.04.006","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4114726/","abruf":"2026-10-12"},{"typ":"url","kurz":"OpenStax (Rice University): Psychology 2e, Kap. 6.2 Classical Conditioning (Extinction, Spontaneous Recovery)","oeffentlich":true,"url":"https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ca3397029b1a5c81"}},{"id":"qx-e-031","clusterId":"E","werkstueckRef":"E.2.7","stufe":1,"question":"Welche Deutung seines Verhaltens ist am besten begründet?","options":["Sein früheres Zuhören kann ein Ausreißer gewesen sein, sodass das heutige Verhalten nur die Rückkehr zum Durchschnitt zeigt.","Das Team kann ihn seit der Beförderung kritischer beobachten, sodass sein Verhalten schlechter bewertet wird, obwohl es gleich geblieben ist.","Die neue Position kann sein Verhalten mitverändert haben, sodass die Situation neben dem Charakter als Erklärung zählt.","Eine vorübergehende Stimmungslage kann sein Verhalten erklären, sodass es nach wenigen Wochen von selbst wieder verschwindet."],"correctIndex":2,"explanation":"Wer ein Verhalten sofort dem „wahren Charakter“ zuschreibt, übersieht leicht, was die Situation bewirkt (fundamentaler Attributionsfehler). Frank war früher zugänglich, und die Veränderung setzte nach der Beförderung ein; das macht die neue Rolle als Mitursache plausibel, beweist sie aber nicht. In Experimenten schnitten Menschen, die man sich mächtig fühlen ließ, bei der Perspektivübernahme schlechter ab, doch eines dieser Experimente (zur Einschätzung, was andere wissen) ließ sich in einer großen Wiederholung mit fast 3.000 Teilnehmenden nicht bestätigen. Am besten begründet ist deshalb die vorsichtige Annahme, dass die Situation das Verhalten begünstigen kann, die man mit weiteren Beobachtungen prüfen würde. Ein früherer Ausreißer erklärt nicht, warum Frank lange als zugänglich galt. Dass nur der Blick des Teams strenger wurde, passt nicht dazu, dass er früher anders auftrat. Und eine kurze Laune hält sich nicht sechs Monate.","coreRule":"⚡ Bevor du Mächtige zum „bösen Charakter“ erklärst, frag, was die Situation aus ihnen macht, und bleib bei der Stärke der Belege vorsichtig.","beleg":"Werkstück E.2.7 (Kernidee; Kontext & Tiefe „Der Empathie-Kollaps“; Anti-Denkmuster); Fn. gl-e-macht-droge (Keltner 2016), gl-e-galinsky (Galinsky u. a. 2006; Ebersole u. a. 2016)","status":"entwurf","scenario":"Frank galt im Team lange als zugänglich und hörte anderen gut zu. Sechs Monate nach seiner Beförderung zum Abteilungsleiter fällt auf: Er unterbricht andere in Meetings, hört kaum noch zu und geht davon aus, dass seine Ideen die besten sind. Im Team heißt es: „Er hat sein wahres Gesicht gezeigt.“","kurz":"Frank wurde vor der Beförderung als zugänglich erlebt, danach nicht mehr. Das macht die neue Rolle als Mitursache plausibel, auch wenn es sie nicht beweist. Aus dem Verhalten sofort auf den „wahren Charakter“ zu schließen, übersieht, was die Situation bewirken kann.","prueffrage":"Welche Beobachtungen über Frank stützen die Rede vom „wahren Gesicht“, und welche sprechen dagegen?","rueckmeldung":[{"option":0,"text":"Schwankungen um einen Durchschnitt gibt es wirklich, und ein Ausschlag nach oben fällt später als Absturz auf. Frank galt aber lange als zugänglich, das ist ein Muster und kein einzelner Ausreißer. Auch der Zeitpunkt nach der Beförderung bleibt dabei unerklärt."},{"option":1,"text":"Ein kritischerer Blick auf Vorgesetzte ist gut möglich und kann die Bewertung mitprägen. Das Szenario nennt aber konkrete Veränderungen: Er unterbricht und hört kaum noch zu, während er früher anders auftrat. Der Blick des Teams allein erklärt das nicht."},{"option":3,"text":"Stimmungen können Verhalten durchaus beeinflussen, meist aber nur für kurze Zeit. Hier hält das Verhalten seit sechs Monaten an. Eine Laune erklärt außerdem nicht, warum die Veränderung ausgerechnet mit der Beförderung begann."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"FORRT FLoRA Replication Atlas: Galinsky u. a. (2006), Power and Perspectives Not Taken – Replikation Many Labs 3 (Ebersole u. a. 2016), Ergebnis „failed“","oeffentlich":true,"url":"https://forrt.org/flora-replication-atlas/doi/10.1111/j.1467-9280.2006.01824.x/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Galinsky, A. D.; Magee, J. C.; Inesi, M. E.; Gruenfeld, D. H. (2006): Power and Perspectives Not Taken. Psychological Science 17(12), 1068–1074","oeffentlich":false,"doi":"10.1111/j.1467-9280.2006.01824.x"},{"typ":"url","kurz":"Pronin, E.; Gilovich, T.; Ross, L. (2004): Objectivity in the eye of the beholder: divergent perceptions of bias in self versus others. Psychological Review 111(3), 781–799 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1037/0033-295X.111.3.781","url":"https://pubmed.ncbi.nlm.nih.gov/15250784/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"dabc9a07d980f4f2"}},{"id":"qx-e-032","clusterId":"E","werkstueckRef":"E.2.7","stufe":3,"question":"Du liest in einem Artikel: „Studien beweisen, dass Macht Menschen rücksichtslos macht.“ Als Beleg wird eine Feldstudie genannt, in der Fahrer teurer Autos an Kreuzungen häufiger andere Fahrzeuge schnitten und Fußgängern häufiger die Vorfahrt nahmen als Fahrer günstiger Wagen. Was ist an diesem Beleg zu beachten?","options":["Gemessen wurde der Preis des Autos, also ein Anzeichen für soziale Schicht und nicht für Macht; zudem stützen direkte Wiederholungen den Befund nicht.","Es fehlt eine Vergleichsgruppe, denn ohne Fahrer günstiger Wagen als Kontrast lässt sich das Verhalten der Fahrer teurer Autos nicht einordnen.","Die Daten stammen aus Selbstauskünften der Fahrer, die ihr Verhalten beschönigen, sodass soziale Erwünschtheit den Befund verzerrt.","Die Beobachtungen stammen aus einem Laborversuch, dessen künstliche Lage sich nicht auf echtes Verhalten im Straßenverkehr übertragen lässt."],"correctIndex":0,"explanation":"Ein Beleg trägt eine Aussage nur, wenn er das misst, wovon die Aussage spricht. Das Auto ist hier ein Stellvertreter für soziale Schicht, und die Studie untersuchte nicht Macht, sondern soziale Schicht. Der Schluss von „Autopreis“ auf „Macht“ ist also ein Sprung. Dazu kommt: Die Feldstudie aus der Arbeitsgruppe um Dacher Keltner (Piff u. a., 2012) wurde 2023 in zwei direkten Wiederholungen nicht bestätigt. Ein Befund, der sich bei der Wiederholung nicht zeigt, ist ein wackliger Beleg. Zwei Fragen schützen vor solchen Fehlschlüssen: Was wurde tatsächlich gemessen, und hat sich das Ergebnis bei Wiederholung gezeigt?","coreRule":"⚡ Frag bei einer Studie: Was wurde wirklich gemessen, und wurde der Befund wiederholt?","beleg":"Werkstück E.2.7 (Kontext & Tiefe: Der Empathie-Kollaps); Fn. gl-e-keltner (Keltner 2016, S. 108 und 121–126; Piff u. a. 2012, PNAS 109(11), S. 4086–4091)","status":"entwurf","scenario":"Der Artikel zieht aus der Beobachtung den Schluss: „Wer Macht hat, verliert die Rücksicht auf andere.“","kurz":"Der Beleg trägt nur, wenn er misst, wovon die Aussage spricht. Gemessen wurde aber der Autopreis, ein Anzeichen für soziale Schicht und nicht für Macht, und der Befund zeigte sich in direkten Wiederholungen nicht.","prueffrage":"Was genau haben die Forschenden an Autos und Fahrern festgehalten, und wurde die Beobachtung später noch einmal gemacht?","rueckmeldung":[{"option":1,"text":"Ein Vergleich ist wichtig, denn Verhalten lässt sich nur im Kontrast einordnen. Hier ist er aber schon da: Fahrer günstiger Wagen dienen als Gegenstück. Fraglich ist, was der Unterschied zwischen beiden Gruppen überhaupt misst."},{"option":2,"text":"Soziale Erwünschtheit verzerrt tatsächlich oft Selbstauskünfte. Hier aber wurde niemand befragt, sondern das Verhalten an Kreuzungen beobachtet. Die Schwäche liegt woanders: im Gemessenen und in der ausbleibenden Bestätigung."},{"option":3,"text":"Laborlagen sind oft zu künstlich, deshalb ist der Einwand verbreitet. Genannt wird hier aber eine Feldstudie im echten Straßenverkehr, also keine künstliche Lage. Der Haken steckt darin, was dort als Maß für Macht herhalten muss."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Piff, P. K.; Stancato, D. M.; Côté, S.; Mendoza-Denton, R.; Keltner, D. (2012): Higher social class predicts increased unethical behavior. PNAS 109(11), 4086–4091 (PMC-Volltext)","oeffentlich":true,"doi":"10.1073/pnas.1118373109","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3306667/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Jung, M. H. u. a. (2023): Social status and unethical behavior: Two replications of the field studies in Piff et al. (2012). Journal of Experimental Psychology: General 152(5), 1368–1378","oeffentlich":false,"doi":"10.1037/xge0001333"},{"typ":"daten","kurz":"Universiteit van Amsterdam: Datensatz „Social status and unethical behavior: Two replications of the field studies in Piff et al. (2012)“ (mit Abstract)","oeffentlich":true,"doi":"10.21942/uva.24894654.v1","url":"https://dare.uva.nl/id/34307082-e88d-44ba-ad4d-340a45489827","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2dadde159a8673f8"}},{"id":"qx-e-033","clusterId":"E","werkstueckRef":"E.2.7","stufe":4,"question":"Ein Ratgeber behauptet: „Macht wirkt im Gehirn wie Kokain – das ist gemessen.“ Als Beleg zitiert er einen Psychologen, der Macht „a dopamine high“ nennt. Wie beurteilst du die Behauptung?","options":["Wer einen Psychologen als Fachmann zitiert, hat damit einen Beleg genannt, solange kein anderer Fachmann ausdrücklich widerspricht.","Das Zitat zeigt nur, dass jemand den Vergleich formuliert hat; dass Dopamin bei Machtgefühl tatsächlich gemessen wurde, zeigt es nicht.","Das Zitat nennt keine Messung, also ist die Behauptung falsch; was in einem Zitat nicht belegt wird, kann auch nicht stimmen.","Die Behauptung ist als Bild gemeint und deshalb weder belegt noch unbelegt; bildhafte Rede lässt sich nicht prüfen und braucht keinen Beleg."],"correctIndex":1,"explanation":"Ein Zitat, in dem ein Fachmann einen bildhaften Vergleich zieht („a dopamine high“), ist keine Messung. Der zitierte Psychologe (Dacher Keltner, 2016) nennt in seinem Buch „The Power Paradox“ keine Studie, die Dopamin bei Machtgefühl gemessen hätte; der Satz „das ist gemessen“ ist deshalb unbelegt. Unbelegt heißt aber nicht widerlegt, und zwischen beidem liegt ein großer Unterschied. Richtig ist die vorsichtige Lesart: eine griffige These mit dünner Datenbasis. Dass der Psychologe ein Fachmann ist, ersetzt keine Messung. Und wer „das ist gemessen“ schreibt, meint keine Metapher, sondern behauptet einen Befund, der sich prüfen lässt.","coreRule":"⚡ Ein griffiger Vergleich ist noch kein Messergebnis.","beleg":"Werkstück E.2.7 (Kernidee); Fn. gl-e-macht-droge (Keltner 2016, Einleitung S. 7, Kap. 1 S. 40, Kap. 4 S. 117)","status":"entwurf","scenario":"","kurz":"Ein bildhafter Vergleich eines Fachmanns ist keine Messung. Aus „klingt plausibel und stammt von einem Psychologen“ wird so schnell „ist gemessen“. Die Behauptung ist unbelegt, aber nicht widerlegt: eine griffige These mit dünner Datenbasis.","prueffrage":"Welche Angaben zu Versuchspersonen, Messverfahren oder Messwerten enthält der Beleg des Ratgebers?","rueckmeldung":[{"option":0,"text":"Ein Fachmann ist ein Hinweis, aber noch keine Messung. Hier ist das Zitat ein bildhafter Vergleich, und dass niemand widerspricht, macht daraus keinen Befund. Dass es keinen Beleg gibt, bleibt davon unberührt."},{"option":2,"text":"Dass im Zitat keine Messung genannt wird, stimmt. Daraus folgt aber nur, dass die Behauptung unbelegt ist, nicht dass sie falsch ist. Unbelegt und widerlegt liegen weit auseinander."},{"option":3,"text":"Der Psychologe spricht tatsächlich bildhaft. Der Ratgeber aber schreibt „das ist gemessen“ und behauptet damit keinen Vergleich, sondern einen Befund, der sich prüfen lässt und einen Beleg braucht."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"literatur","kurz":"Keltner, D. (2016): The Power Paradox: How We Gain and Lose Influence. New York: Penguin Press","oeffentlich":false,"seite":"7"},{"typ":"url","kurz":"FORRT FLoRA Replication Atlas: Galinsky u. a. (2006), Power and Perspectives Not Taken – Replikation Many Labs 3, Ergebnis „failed“","oeffentlich":true,"url":"https://forrt.org/flora-replication-atlas/doi/10.1111/j.1467-9280.2006.01824.x/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"dea83d1df7106a91"}},{"id":"qx-e-034","clusterId":"E","werkstueckRef":"E.2.7","stufe":2,"question":"In einer Zeitung steht: „Neurowissenschaftler haben bewiesen: Macht schaltet die Spiegelneuronen aus, Mächtige können das Leid anderer nicht mehr nachempfinden.“ Die zugrunde liegende Studie hat mit Magnetstimulation am Kopf gemessen, wie stark Muskeln beim Betrachten fremder Handbewegungen unwillkürlich „mitschwingen“. Wer sich mächtig fühlen sollte, zeigte eine schwächere Reaktion. Welche Übertreibung der Schlagzeile betrifft die Messebene selbst?","options":["Sie macht aus einem indirekten Muskelmaß den Beweis für abgeschaltete Nervenzellen, obwohl keine einzelne Nervenzelle untersucht wurde.","Sie macht aus einem Laborbefund eine Aussage über alle Mächtigen im Alltag, obwohl nur kurz mächtig gestimmte Teilnehmer untersucht wurden.","Sie macht aus einer einzelnen Studie einen Beweis, obwohl ein einzelner Befund erst durch Wiederholungen belastbar wird.","Sie macht aus einem Gruppenunterschied eine Wirkung der Macht, obwohl ganz andere Faktoren den Unterschied erklären könnten."],"correctIndex":0,"explanation":"Gemessen wurden Muskelantworten als indirektes Maß für das menschliche Spiegelsystem, keine einzelnen Nervenzellen. Daraus lässt sich allenfalls ein Hinweis auf geringere automatische Anteilnahme ableiten, kein Nachweis „abgeschalteter Spiegelneuronen“; einzelne Nervenzellen mit Spiegeleigenschaften wurden beim Menschen nur in einer anderen Studie mit implantierten Elektroden abgeleitet. Die übrigen Einwände treffen andere Schwächen: Die Übertragung vom Labor auf alle Mächtigen im Alltag betrifft die Verallgemeinerung, dass eine einzelne Studie noch kein Beweis ist, betrifft die Belegstärke, und der Einwand mit den „ganz anderen Faktoren“ betrifft die Ursache des Unterschieds; zudem wurde das Machtgefühl im Versuch gezielt erzeugt. Bei der Messebene selbst verspricht die Schlagzeile also etwas, das die Messung nicht hergibt: abgeschaltete Nervenzellen.","coreRule":"⚡ Ein indirektes Maß ist ein Hinweis, kein Beweis – und eine Schlagzeile darf nicht weiter reichen als das, was gemessen wurde.","beleg":"Werkstück E.2.7 (Kontext & Tiefe: Verringerte neuronale Resonanz); Fn. gl-e-hogeveen (Hogeveen u. a. 2014, S. 755–762; Mukamel u. a. 2010)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Gemessen wurde nur, wie stark Muskeln mitschwingen, also ein indirektes Maß, keine einzelne Nervenzelle. Daraus folgt allenfalls ein Hinweis auf geringere automatische Anteilnahme, nicht der Beweis „abgeschalteter Spiegelneuronen“.","prueffrage":"Wer wurde in der Studie untersucht, und wie wurde die Reaktion der Teilnehmenden erfasst?","rueckmeldung":[{"option":1,"text":"Der Einwand trifft eine echte Schwäche: Kurz mächtig gestimmte Teilnehmer sind kein Querschnitt aller Mächtigen. Diese Schwäche betrifft aber die Verallgemeinerung vom Labor auf den Alltag, nicht das, was die Messung selbst hergibt."},{"option":2,"text":"Dass eine einzelne Studie noch kein Beweis ist, stimmt, und „bewiesen“ ist tatsächlich zu stark. Das betrifft aber die Belegstärke, nicht die Messebene: Dort wird aus einem indirekten Muskelmaß ein Befund über abgeschaltete Nervenzellen."},{"option":3,"text":"Bei Gruppenvergleichen ist der Gedanke an andere Faktoren oft berechtigt. Hier wurde das Machtgefühl aber gezielt im Versuch erzeugt. Vor allem betrifft der Einwand die Ursache des Unterschieds, nicht das, was die Messung selbst hergibt."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Hogeveen, J.; Inzlicht, M.; Obhi, S. S. (2014): Power changes how the brain responds to others. Journal of Experimental Psychology: General 143(2), 755–762 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1037/a0033477","url":"https://pubmed.ncbi.nlm.nih.gov/23815455/","abruf":"2026-10-12"},{"typ":"url","kurz":"Mukamel, R.; Ekstrom, A. D.; Kaplan, J.; Iacoboni, M.; Fried, I. (2010): Single-neuron responses in humans during execution and observation of actions. Current Biology 20(8), 750–756 (PMC-Volltext)","oeffentlich":true,"doi":"10.1016/j.cub.2010.02.045","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2904852/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"45a31c0954a94a15"}},{"id":"qx-e-035","clusterId":"E","werkstueckRef":"E.3.1","stufe":1,"question":"Was unterscheidet die Aussage des Politikers von der Zeitungsmeldung?","options":["Der Politiker ordnet das Ereignis in eine Geschichte mit Opfern, Gegnern und Retter ein und gibt ihm so eine Bedeutung, die die Fakten allein nicht liefern.","Der Politiker nennt eine andere Zahl an Entlassungen als die Zeitung und verändert so die berichtete Tatsache, sodass beide von verschiedenen Ereignissen sprechen.","Der Politiker lenkt mit einem ganz anderen Thema von den Entlassungen ab und spricht über das berichtete Ereignis selbst gar nicht mehr, sondern nur über Fremdes.","Der Politiker beruft sich auf eine Fachperson, die den Vorgang einordnet, und gibt seiner Aussage dadurch das Gewicht einer fachlichen Autorität."],"correctIndex":0,"explanation":"Die Meldung nennt ein Ereignis: 300 Entlassungen. Der Politiker fügt eine Deutung hinzu, mit Tätern („skrupellose Manager“), Opfern („die einfachen Leute“) und einem Retter („nur wir“). Das ist ein Narrativ: eine Geschichte, die Ereignisse in einen Ursache-Wirkungs-Zusammenhang mit Helden, Gegnern und Moral bringt, ihnen so Bedeutung verleiht und oft gleich eine Handlungsanweisung mitliefert. Die Entlassungen sind real, die Rollenverteilung ist eine Zutat der Geschichte. Deshalb lohnt die Frage, welche anderen Geschichten dieselben Fakten erklären könnten und welche Fakten diese Geschichte auslässt. Der Politiker nennt keine andere Zahl, die Entlassungen selbst bleiben unangetastet. Er bleibt auch beim Ereignis und wechselt das Thema nicht. Und von einer Fachperson, auf die er sich stützt, ist in seiner Aussage keine Rede.","coreRule":"⚡ Fakten sagen, was geschah; ein Narrativ sagt, was es bedeutet. Prüfe deshalb immer, welche Deutung zu den Fakten hinzugefügt wurde und welche anderen möglich wären.","beleg":"Werkstück E.3.1 (Kernidee: Definition Narrativ; Kontext & Tiefe: Beispiel Fakt vs. Narrativ)","status":"entwurf","scenario":"Eine Tageszeitung meldet: „Ein Konzern entlässt 300 Beschäftigte.“ Ein Politiker sagt dazu im Wahlkampf: „Wieder opfern skrupellose Manager die einfachen Leute für ihren Profit, und nur wir stellen uns schützend vor sie.“","quote":"","quoteLabel":"","kurz":"Die Meldung nennt nur das Ereignis: 300 Entlassungen. Der Politiker macht daraus eine Geschichte mit Tätern, Opfern und einem Retter. Die Entlassungen sind real, die Rollenverteilung ist eine Zutat, die die Fakten allein nicht hergeben.","prueffrage":"Welcher Teil der Reaktion lässt sich in der Meldung wiederfinden, und welcher kommt erst von dem, der spricht?","rueckmeldung":[{"option":1,"text":"Bei abweichenden Darstellungen liegt der Verdacht auf verschobene Fakten nahe. Hier nennt der Politiker aber gar keine Zahl, die 300 Entlassungen bleiben, wie sie sind. Hinzu kommt allein die Deutung."},{"option":2,"text":"Ein Themenwechsel würde den Unterschied erklären, doch der Politiker bleibt beim Ereignis. Er spricht über genau diese Entlassungen und deutet sie, statt von ihnen abzulenken."},{"option":3,"text":"Eine Fachautorität würde dem Satz tatsächlich Gewicht geben. Nur kommt in seiner Aussage niemand vor, auf den er sich beruft. Seine Wirkung entsteht aus der Geschichte mit Gut und Böse."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dahlstrom, M. F. (2014): Using narratives and storytelling to communicate science with nonexpert audiences. PNAS 111(Suppl. 4) (PMC-Volltext)","oeffentlich":true,"doi":"10.1073/pnas.1320645111","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4183170/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"a463097e22d39da9"}},{"id":"qx-e-036","clusterId":"E","werkstueckRef":"E.3.1","stufe":2,"question":"Ein Kollege wendet ein: „Das ist doch Verschwendung. Wer Schuhe verkaufen will, sollte zeigen, was die Schuhe können.“ Wie lässt sich die Strategie der Marke am besten erklären?","scenario":"Du siehst einen Spot nach dem anderen für eine Sportmarke: Läufer im Morgengrauen, ein Mädchen, das nicht aufgibt, am Ende ein Logo. Von den Schuhen erfährst du fast nichts.","options":["Die Marke verkauft eine Geschichte vom Menschen, der über sich hinauswächst. Wer die Schuhe kauft, kann sich als Teil dieser Geschichte fühlen.","Die Marke wirbt mit bekannten Persönlichkeiten, deren Ansehen auf das Produkt abfärbt. Wer die Schuhe kauft, übernimmt ein Stück dieses Ansehens.","Die Marke informiert sachlich über Material und Preis der Schuhe. Wer die Schuhe kauft, entscheidet vor allem nach rationalen Kriterien.","Die Marke erzeugt künstliche Knappheit und lässt die Schuhe bald vergriffen wirken. Wer die Schuhe kauft, will vor allem nichts verpassen."],"correctIndex":0,"explanation":"Der Spot erzählt, was die Marke bedeuten soll: Held, Hindernis, Überwindung. Das ist ein Narrativ, und Narrative sind weit einprägsamer und motivierender als abstrakte Sachinformationen. Käufer erwerben dann nicht nur ein Produkt, sondern die Zugehörigkeit zu einer Geschichte. Dass kaum Schuhe zu sehen sind, ist deshalb kein Fehler, sondern Absicht. Ein Test für solche Fälle: Frag, welche Geschichte ein Produkt mitverkauft und wer darin der Held ist. Bekannte Persönlichkeiten treten im Spot nicht auf, es laufen Läufer, und ein Mädchen gibt nicht auf. Material und Preis kommen nicht vor, also setzt die Marke nicht auf Sachinformation. Und von knappen Stückzahlen oder Eile ist ebenfalls nichts zu sehen.","coreRule":"⚡ Wer fragt, welche Geschichte ein Produkt mitverkauft, durchschaut die Werbung besser.","beleg":"Werkstück E.3.1 (Anwendung & Relevanz: Im Marketing)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Der Spot erzählt, was die Marke bedeuten soll: Held, Hindernis, Überwindung. Wer kaufen soll, erwirbt so die Zugehörigkeit zu einer Geschichte, die sich besser einprägt als Sachinfos. Dass kaum Schuhe zu sehen sind, ist also Absicht.","prueffrage":"Was genau bekommst du in diesen Spots zu sehen und zu hören, und was davon ließe sich in einer Produktbeschreibung wiederfinden?","rueckmeldung":[{"option":1,"text":"Dass Ansehen von Personen aufs Produkt abfärben kann, ist ein echter Werbemechanismus. In diesen Spots tritt aber keine bekannte Persönlichkeit auf: Es laufen Läufer, und ein Mädchen gibt nicht auf."},{"option":2,"text":"Der Einwand des Kollegen setzt genau das voraus: Wer Schuhe verkauft, müsse Eigenschaften zeigen. Im Spot kommen Material und Preis aber nicht vor. Die Marke setzt also gerade nicht auf Sachinformation."},{"option":3,"text":"Künstliche Verknappung ist als Verkaufstaktik denkbar, hier lässt sie sich aber nicht erkennen. Von knappen Stückzahlen oder Eile ist in den Spots nichts zu sehen, sie zeigen eine Geschichte."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mar, R. A.; Li, J.; Nguyen, A. T. P.; Ta, C. P. (2021): Memory and comprehension of narrative versus expository texts: A meta-analysis. Psychonomic Bulletin & Review 28(3), 732–749 (PMC-Volltext)","oeffentlich":true,"doi":"10.3758/s13423-020-01853-1","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8219577/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dahlstrom, M. F. (2014): Using narratives and storytelling to communicate science with nonexpert audiences. PNAS 111(Suppl. 4) (PMC-Volltext)","oeffentlich":true,"doi":"10.1073/pnas.1320645111","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4183170/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"50912ef0eee8e3bf"}},{"id":"qx-e-037","clusterId":"E","werkstueckRef":"E.3.1","stufe":3,"question":"Welche Beobachtung zeigt am deutlichsten, dass eine Geschichte nicht mehr der Deutung der Wirklichkeit dient, sondern sie ersetzt?","options":["Die Geschichte kennt Helden und Gegner, denn jede Erzählung mit klarem Gut und Böse ist schon für sich eine Manipulation.","Belegte Gegenbeispiele werden nicht geprüft, sondern als Angriff abgetan, denn die Treue zur Geschichte zählt dort mehr als die Treue zu den Tatsachen.","Die Geschichte erreicht nur eine Gruppe und keine anderen Kulturen, denn dann fehlt ihr die gemeinsame Basis für Zusammenarbeit.","Die Geschichte malt ein Bild der Zukunft aus, denn jede Vision einer besseren Zukunft dient vor allem der Täuschung der Gläubigen."],"correctIndex":1,"explanation":"Eine Geschichte ist zunächst ein Werkzeug: Sie ordnet Ereignisse zu einem Zusammenhang, stiftet Sinn und ermöglicht Zusammenarbeit zwischen Menschen, die sich nicht kennen. Das ist nützlich und kein Fehler. Gefährlich wird sie, wenn sie die Wirklichkeit nicht mehr deutet, sondern ersetzt: Dann gelten Tatsachen, die nicht ins Bild passen, als feindliche Propaganda und werden nicht mehr geprüft. Das Merkmal ist also der Umgang mit widersprechenden Belegen. Klare Rollen von Held und Gegner kommen in fast jeder wirksamen Geschichte vor, auch in harmlosen, und sind höchstens ein Warnsignal, aber noch kein Beweis. Dass eine Geschichte nur eine Gruppe erreicht, sagt über ihren Wahrheitsgehalt nichts. Und eine Zukunftsvision gehört zu jeder erfolgreichen Geschichte und macht sie nicht schon zur Täuschung.","coreRule":"⚡ Eine Geschichte wird gefährlich, wenn sie die Wahrheit nicht mehr deutet, sondern ersetzt.","beleg":"Werkstück E.3.1 (Der Kipppunkt; Red Flags; Kontext & Tiefe)","status":"entwurf","scenario":"Eine Bewegung erzählt ihren Anhängern eine Geschichte von einem Kampf zwischen „dem Volk“ und „den Eliten“. Die Geschichte erklärt für die Mitglieder Vergangenheit, Gegenwart und Zukunft. Du beobachtest vier Dinge an dieser Bewegung.","kurz":"Entscheidend ist, wie eine Geschichte mit widersprechenden Belegen umgeht. Wird Unpassendes nur noch als Angriff abgetan, ersetzt sie die Wirklichkeit. Helden, Gegner und Zukunftsbilder haben dagegen fast alle wirksamen Geschichten.","prueffrage":"Welche der beobachteten Eigenschaften hätte auch ein harmloses Märchen, und welche nicht?","rueckmeldung":[{"option":0,"text":"Helden und Gegner kommen in fast jeder wirksamen Geschichte vor, auch in harmlosen, etwa in Märchen oder Sportberichten. Klare Rollen können höchstens ein Warnsignal sein, belegen aber noch keine Manipulation."},{"option":2,"text":"Eine Geschichte, die nur eine Gruppe verbindet, kann dennoch stimmen oder nicht stimmen. Die Reichweite sagt nichts darüber, ob sie die Wirklichkeit deutet oder ersetzt."},{"option":3,"text":"Zukunftsbilder gehören zu fast jeder erfolgreichen Geschichte, auch zu ehrlichen. Dass sie Hoffnung wecken, macht sie noch nicht zur Täuschung; entscheidend ist, wie die Geschichte mit Widersprüchen zur Wirklichkeit umgeht."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Smith, D. u. a. (2017): Cooperation and the evolution of hunter-gatherer storytelling. Nature Communications 8, 1853 (PMC-Volltext)","oeffentlich":true,"doi":"10.1038/s41467-017-02036-8","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5717173/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dahlstrom, M. F. (2014): Using narratives and storytelling to communicate science with nonexpert audiences. PNAS 111(Suppl. 4) (PMC-Volltext)","oeffentlich":true,"doi":"10.1073/pnas.1320645111","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4183170/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harari, Y. N. (2013): Eine kurze Geschichte der Menschheit (Sapiens). München: DVA","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"e7c49f948981d7fc"}},{"id":"qx-e-038","clusterId":"E","werkstueckRef":"E.3.1","stufe":4,"question":"Du liest in einem populären Geschichtsbuch: „Vor genau 70.000 Jahren löste eine plötzliche kognitive Revolution die Fähigkeit des Menschen aus, an gemeinsame Geschichten zu glauben, und erklärt damit alles Spätere.“ Welche Rückfrage prüft diese Aussage am besten?","options":["Gibt es Funde, die symbolisches Verhalten schon deutlich vor 70.000 Jahren zeigen und eher für eine allmähliche Entwicklung sprechen?","Hat sich das Buch besonders gut verkauft und halten deshalb viele Menschen die Aussage für richtig?","Ist die Jahreszahl 70.000 nicht exakt belegbar und spielten gemeinsame Geschichten dann keine Rolle?","Wurde das Buch für ein breites Publikum geschrieben und ist die Aussage deshalb vermutlich falsch?"],"correctIndex":0,"explanation":"Eine Behauptung mit einer genauen Zahl und einem „plötzlichen“ Wendepunkt lässt sich an Befunden prüfen. Hier gibt es Hinweise dagegen: Die Archäologinnen Sally McBrearty und Alison Brooks argumentieren für eine allmähliche Entwicklung symbolischen Verhaltens, und Funde aus der Höhle von Blombos in Südafrika werden auf 75.000 bis 100.000 Jahre datiert. Die Rückfrage nach früheren Funden prüft also genau den Punkt, an dem die Aussage angreifbar ist. Verkaufszahlen und Reichweite sagen nichts über die Richtigkeit, und dass ein Werk ein breites Publikum anspricht, macht es noch nicht falsch. Auch eine umstrittene Jahreszahl widerlegt nicht den Kerngedanken, dass gemeinsame Geschichten Kooperation unter Fremden ermöglichen; dieser hängt nicht an der genauen Zahl.","coreRule":"⚡ Prüfe bei einer eingängigen Zahl in einer großen Erzählung, ob Befunde dagegensprechen. Eine umstrittene Zahl entwertet nicht automatisch den Kerngedanken.","beleg":"Werkstück E.3.1 (Kontext & Tiefe); Fn. gl-e-harari (Harari 2011/2013; McBrearty & Brooks; Blombos)","status":"entwurf","scenario":"Ein Bekannter hält eine Aussage aus einem populären Geschichtsbuch für die Erklärung unserer ganzen Kultur. Du willst herausfinden, wie belastbar diese Aussage ist.","kurz":"Eine genaue Zahl und ein „plötzlicher“ Wendepunkt lassen sich an Funden prüfen. Findet sich symbolisches Verhalten deutlich früher, spricht das gegen den Umbruch. Beliebtheit eines Buchs dagegen sagt nichts über seine Richtigkeit.","prueffrage":"Welche Wörter machen den Satz besonders angreifbar, und womit ließe sich jedes davon überprüfen?","rueckmeldung":[{"option":1,"text":"Dass sich ein Buch gut verkauft, gibt der Aussage einen Anschein von Gewicht. Verkaufszahlen und Reichweite sagen aber nichts darüber, ob sie stimmt; viele Leserinnen und Leser können sich ebenso irren."},{"option":2,"text":"Eine genaue Jahreszahl lässt sich tatsächlich kaum belegen. Selbst eine umstrittene Zahl widerlegt aber nicht den Gedanken, dass gemeinsame Geschichten Zusammenarbeit unter Fremden ermöglichen; der hängt nicht an der Zahl."},{"option":3,"text":"Populäre Bücher vereinfachen manchmal, deshalb ist Nachprüfen sinnvoll. Ein breites Publikum macht eine Aussage aber nicht falsch; ob sie trägt, zeigt sich an den Befunden, nicht am Leserkreis."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"McBrearty, S.; Brooks, A. S. (2000): The revolution that wasn't: a new interpretation of the origin of modern human behavior. Journal of Human Evolution 39(5), 453–563 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1006/jhev.2000.0435","url":"https://pubmed.ncbi.nlm.nih.gov/11102266/","abruf":"2026-10-12"},{"typ":"url","kurz":"Henshilwood, C. S.; d'Errico, F.; Watts, I. (2009): Engraved ochres from the Middle Stone Age levels at Blombos Cave, South Africa. Journal of Human Evolution 57(1), 27–47 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1016/j.jhevol.2009.01.005","url":"https://pubmed.ncbi.nlm.nih.gov/19487016/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harari, Y. N. (2013): Eine kurze Geschichte der Menschheit (Sapiens). München: DVA","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1577bafd9ba2c4ed"}},{"id":"qx-e-039","clusterId":"E","werkstueckRef":"E.3.2","stufe":1,"question":"Welche Erwiderung auf diesen Einwand trifft zu?","options":["Der Wert ergibt sich aus der persönlichen Wertschätzung jedes Einzelnen, und wer Geld nicht schätzt, für den hat es auch keinen Wert.","Der Wert steckt im Material, aus dem Scheine und Münzen bestehen, und hängt deshalb von Papier und Metall ab, nicht vom Glauben der Menschen.","Der Wert ist keine Einbildung des Einzelnen, sondern beruht auf dem gemeinsamen Glauben vieler und zeigt sich in den Folgen, die er für alle hat.","Der Wert beruht allein auf dem Zwang des Staates, der die Annahme von Geld vorschreibt, und wirkt deshalb auch ohne den Glauben der Menschen."],"correctIndex":2,"explanation":"Der Einwand verwechselt zwei Dinge: „nur im Denken“ und „nur im Denken eines Einzelnen“. Der Wert des Geldes hängt nicht an einer einzelnen Person, sondern an der Übereinkunft von Millionen. Deshalb kann ihn niemand allein wegdenken: Wer als Einziger aufhört, an den Euro zu glauben, ist nicht erleuchtet, sondern pleite. Ein Schimpanse zeigt, wie viel am geteilten Glauben hängt: Für ihn ist der Schein nur ein Stück Papier, er tauscht ihn nicht gegen Bananen. Gleichzeitig ist der Wert nicht objektiv wie die Schwerkraft, denn er würde verschwinden, wenn eine kritische Masse von Menschen aufhört, an ihn zu glauben. Solche Dinge nennt man intersubjektiv: Sie existieren durch gemeinsamen Glauben und wirken trotzdem real. Dass jeder Güter nach persönlichem Nutzen bewertet, stimmt zwar, doch der Wert des Geldes hängt daran, was alle anderen dafür hergeben, nicht an der eigenen Meinung. Im Papier und im Metall steckt kaum Wert, den bekommen Schein und Münze erst dadurch, dass andere sie annehmen. Und staatlicher Zwang kann die Annahme absichern, ersetzt aber nicht das Vertrauen, dass andere das Geld ebenfalls annehmen.","coreRule":"⚡ Intersubjektiv real ist, was nur durch den gemeinsamen Glauben vieler existiert – und trotzdem handfeste Folgen hat. „Nur im Kopf“ heißt nicht „nur im Kopf eines Einzelnen“ und auch nicht „wirkungslos“.","beleg":"Werkstück E.3.2 (Kernidee; Kontext & Tiefe: Drei Arten von Realität)","status":"entwurf","scenario":"Im Gespräch über Geld sagt jemand: „Geld ist doch nur bedrucktes Papier und ein Stück Metall. Der Wert existiert nur in unseren Köpfen, also ist er Einbildung. Wenn ich selbst nicht daran glaube, kann es mir egal sein.“","kurz":"„Nur im Denken“ heißt nicht „nur im Denken eines Einzelnen“: Der Wert des Geldes beruht auf der Übereinkunft von Millionen. Deshalb kann ihn keiner allein wegdenken, und wer als Einziger nicht mehr glaubt, ist nicht erleuchtet, sondern pleite.","prueffrage":"Was geschieht mit jemandem, der als Einziger in seiner Stadt aufhört, Geld anzunehmen?","rueckmeldung":[{"option":0,"text":"Dass jeder Güter nach persönlichem Nutzen bewertet, stimmt. Der Wert des Geldes hängt aber daran, was andere dafür hergeben, nicht an der eigenen Wertschätzung. Wer sie nicht teilt, bekommt für seinen Schein trotzdem weiter Waren."},{"option":1,"text":"Scheine und Münzen sind real, aber im Papier und im Metall steckt kaum Wert. Den bekommen sie erst dadurch, dass andere sie annehmen. Ohne diesen geteilten Glauben bliebe der Schein ein Stück Papier, wie beim Schimpansen."},{"option":3,"text":"Staatlicher Zwang kann die Annahme von Geld absichern, mehr aber nicht. Er ersetzt nicht das Vertrauen, dass andere das Geld ebenfalls annehmen. Und das gemeinsame Vertrauen ist es, an dem der Wert hängt."}],"familie":"gemeinsamer-glaube","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Social Ontology (2018, überarbeitet 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/social-ontology/","abruf":"2026-10-12"},{"typ":"url","kurz":"Beran, M. J.; Parrish, A. E. (2021): Non-human primate token use shows possibilities but also limitations for establishing a form of currency. Philosophical Transactions of the Royal Society B 376(1819), 20190675 (PMC-Volltext)","oeffentlich":true,"doi":"10.1098/rstb.2019.0675","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7815425/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harari, Y. N. (2013): Eine kurze Geschichte der Menschheit (Sapiens). München: DVA","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"6fb5884b2cb5c331"}},{"id":"qx-e-040","clusterId":"E","werkstueckRef":"E.3.2","stufe":2,"question":"Welche Erklärung für den Wertverlust ist am stimmigsten?","options":["Der Wert des Geldes beruht auf dem gemeinsamen Vertrauen vieler Menschen; schwindet dieses Vertrauen breit, bricht der Wert zusammen, auch wenn die Scheine gleich bleiben.","Der Wert des Geldes entspricht dem Wert seines Materials; er sinkt erst, wenn Papier und Druck billiger oder schlechter werden, nicht bei unveränderten Scheinen.","Der Wert des Geldes ergibt sich aus der Wertschätzung jedes einzelnen Menschen; er ist unabhängig davon, was andere damit anfangen, und kann nur für jede Person einzeln steigen oder fallen.","Der Wert des Geldes wird allein durch das Gesetz festgelegt; solange die Annahme vorgeschrieben ist, bleibt der Wert stabil, egal wie viele Menschen ihm misstrauen."],"correctIndex":0,"explanation":"Geld hat keinen Wert, der im Papier steckt; es ist nur so viel wert, wie andere dafür hergeben, und das hängt am breiten Vertrauen, dass es weiter angenommen wird. Ausgelöst wird eine Hyperinflation meist durch massive Geldschöpfung, etwa wenn ein Staat seine Ausgaben über die Notenpresse bezahlt; schwindet dann das Vertrauen, beschleunigt das den Verfall, obwohl die Scheine physisch dieselben bleiben. Der Wert eines Materials würde nur sinken, wenn sich das Material verschlechterte, doch das Papier ist vorher und nachher dasselbe. Eine persönliche Einschätzung jedes Einzelnen erklärt keinen gemeinsamen Absturz, denn wer als Einziger nicht mehr an die Währung glaubt, ändert an ihrem Wert nichts, solange andere sie annehmen. Und das Gesetz kann die Annahme vorschreiben, hält den Wert aber nicht stabil, wenn die Menschen der Währung nicht mehr vertrauen.","coreRule":"⚡ Was nur auf gemeinsamem Glauben ruht, kann zerbrechen, wenn der Glaube bricht. Die Veränderung muss dann im Verhalten der Menschen gesucht werden, nicht im Material.","beleg":"Werkstück E.3.2 (Kontext & Tiefe: Intersubjektive Realität; Red Flags; Anwendung & Relevanz: In der Wirtschaft)","status":"entwurf","scenario":"Eine Währung verliert in einer Hyperinflation fast über Nacht ihren Wert, obwohl sich die Geldscheine physisch nicht verändern. Kollegin A sagt: „Da muss das Papier selbst schlechter geworden sein.“ Kollege B sagt: „Nein, das hat mit dem Papier nichts zu tun.“","kurz":"Geld ist nur so viel wert, wie andere dafür hergeben, und das hängt am breiten Vertrauen in seine weitere Annahme. Schwindet es, fällt der Wert, auch wenn die Scheine unverändert bleiben. Im Papier selbst steckt dieser Wert nicht.","prueffrage":"Was genau hat sich an den Geldscheinen selbst zwischen vorher und nachher verändert, und wie schnell ist der Wert gefallen?","rueckmeldung":[{"option":1,"text":"Dass sich am Papier nichts geändert hat, stimmt. Genau deshalb erklärt sein Materialwert den Absturz nicht, denn dieser Wert steckt gar nicht im Papier, sondern darin, was andere dafür hergeben."},{"option":2,"text":"Wertschätzung ist tatsächlich etwas Persönliches. Ein gemeinsamer Absturz folgt daraus aber nicht: Wer als Einziger der Währung nicht mehr traut, ändert an ihrem Wert nichts, solange andere sie weiter annehmen."},{"option":3,"text":"Das Gesetz kann die Annahme zwar vorschreiben und stützt so ein Zahlungsmittel. Den Wert hält es aber nicht stabil, sobald die Menschen der Währung nicht mehr vertrauen und ihr Handeln danach richten."}],"familie":"gemeinsamer-glaube","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Deutscher Bundestag: Hyperinflation in Deutschland 1923 (Reihe „100 Jahre Weimar“)","oeffentlich":true,"url":"https://www.bundestag.de/parlament/geschichte/100-jahre-weimar/hyperinflation-970722","abruf":"2026-10-12"},{"typ":"url","kurz":"Agur, I.; Capelle, D.; Dell'Ariccia, G.; Sandri, D. (2022): Should Monetary Finance Remain Taboo? IMF Blog, 22.02.2022","oeffentlich":true,"url":"https://www.imf.org/en/Blogs/Articles/2022/02/22/should-monetary-finance-remain-taboo","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"82679e55640e997c"}},{"id":"qx-e-041","clusterId":"E","werkstueckRef":"E.3.2","stufe":3,"question":"Welche Rückfrage prüft die Behauptung des Kollegen am besten?","options":["Was geschähe mit dem Modell, wenn alle Beteiligten morgen aufhörten, sich an seine Regeln zu halten?","Was geschähe mit dem Modell, wenn sich die Rohstoffpreise im nächsten Jahr plötzlich verdoppelten?","Was geschähe mit dem Modell, wenn sein bekanntester Fachmann es morgen öffentlich infrage stellte?","Was geschähe mit dem Modell, wenn im nächsten Jahr ein Prozent mehr Beteiligte hinzukämen?"],"correctIndex":0,"explanation":"Ein Naturgesetz gilt unabhängig davon, was wir glauben: Wer nicht mehr an die Schwerkraft glaubt, fällt trotzdem. Ein Wirtschaftsmodell dagegen besteht aus gemeinsamen Regeln, Verträgen und Erwartungen. Es wirkt nur, solange genügend Menschen mitmachen, und es kann sich ändern, wenn sie ihr Verhalten ändern. Die Rückfrage, ob es noch bestünde, wenn alle morgen aufhörten mitzumachen, trennt diese beiden Fälle. Der Fehler des Kollegen liegt darin, ein von Menschen geschaffenes Gefüge für unveränderlich zu halten. Das führt zu Dogmatismus, weil Verbesserungen gar nicht erst gesucht werden. Umgekehrt wäre es auch falsch, das Modell für beliebig änderbar zu halten: Wer allein aussteigt, ändert nichts, sondern trägt nur selbst die Folgen. Ein Rohstoffschock prüft die Robustheit gegen einen äußeren Einfluss, nicht die Abhängigkeit von der Zustimmung der Beteiligten. Das Urteil eines bekannten Fachmanns sagt höchstens etwas über sein Ansehen. Und ein Prozent mehr Beteiligte ändert nur die Größe, nicht den Grund, warum das Modell wirkt.","coreRule":"⚡ Frag bei einer „Naturgesetz“-Behauptung: Gilt sie auch, wenn alle morgen nicht mehr daran glauben?","beleg":"Werkstück E.3.2 (Der Kipppunkt; Anti-Denkmuster)","status":"entwurf","scenario":"In einer Teamsitzung über die Preisgestaltung sagt ein Kollege: „Dieses Wirtschaftsmodell ist wie ein Naturgesetz – daran kann man nichts ändern.“ Das Modell beruht auf Regeln, Verträgen und Erwartungen, auf die sich viele Menschen eingestellt haben.","quote":"","quoteLabel":"","kurz":"Ein Naturgesetz gilt auch, wenn niemand daran glaubt; ein Wirtschaftsmodell wirkt nur, solange genug Menschen mitmachen. Der Denkfehler ist, dieses von Menschen getragene Gefüge für unveränderlich zu halten.","prueffrage":"Woraus besteht das Modell im Einzelnen, und wer hat diese Regeln, Verträge und Erwartungen hervorgebracht?","rueckmeldung":[{"option":1,"text":"Ein Rohstoffschock zeigt, wie anfällig das Modell gegen einen äußeren Einfluss ist. Ob es nur durch das Mitmachen der Beteiligten besteht, wie ein Naturgesetz es nie täte, bleibt damit offen."},{"option":2,"text":"Wenn ein bekannter Fachmann das Modell infrage stellt, ändert das nur sein Ansehen. Regeln, Verträge und Erwartungen der Beteiligten bleiben gleich, und ein Naturgesetz bliebe vom Urteil eines Experten ebenfalls unberührt."},{"option":3,"text":"Ein Prozent mehr Beteiligte verändert nur die Größe des Modells, nicht den Grund, warum es wirkt. Ein so kleiner Zuwachs würde es kaum erschüttern und deshalb auch nichts darüber verraten, wovon es abhängt."}],"familie":"gemeinsamer-glaube","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Social Ontology (2018, überarbeitet 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/social-ontology/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harari, Y. N. (2013): Eine kurze Geschichte der Menschheit (Sapiens). München: DVA","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9be69e6886d2aa0b"}},{"id":"qx-e-042","clusterId":"E","werkstueckRef":"E.3.2","stufe":4,"question":"Ein Beitrag behauptet: „Schimpansen verstehen Geld. Sie tauschen Marken gegen Futter, also nutzen sie Geld genau wie wir.“ Welche Frage prüft diese Behauptung am besten?","options":["Haben die Tiere nur gelernt, was belohnt wird, oder teilen sie auch eine Vorstellung davon, dass die Marken Wert haben?","Wie oft pro Stunde tauschen die Tiere ihre Marken im Durchschnitt gegen Futter ein?","Wie schneiden Schimpansen bei Intelligenztests im Vergleich zu anderen Tierarten ab?","Schmeckt den Tieren das Futter aus dem Automaten besser als das Futter in ihrem Käfig?"],"correctIndex":0,"explanation":"Der Schluss „tauscht Marken gegen Futter, also nutzt Geld“ verwechselt gelerntes Tauschen mit Geld. Nach Beran & Parrish (2021) lernen Primaten, Marken als Platzhalter für Futter zu schätzen, nutzen sie aber nicht so, wie Menschen Währung nutzen. Beim Geld kommt etwas hinzu: Es hat Wert, weil Millionen Menschen sich gemeinsam vorstellen, dass ein Stück Papier Wert hat. Genau das prüft die Frage, ob die Tiere nur gelernt haben, was belohnt wird, oder ob sie auch eine geteilte Wertvorstellung haben. Die übrigen Fragen betreffen Häufigkeit, Intelligenz oder Geschmack und sagen nichts darüber, ob mehr als gelerntes Tauschen vorliegt. Schimpansen lernen den Markentausch übrigens schon seit den 1930er-Jahren, ohne damit Teil unseres Geldsystems zu sein.","coreRule":"⚡ Tauschen können ist noch kein Geld: Dazu gehört die geteilte Geschichte über seinen Wert.","beleg":"Werkstück E.3.2 (Einstieg: Die unmögliche Banane); Fn. gl-e-marken (Beran & Parrish 2021; Wolfe 1936)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"1f6b04564b6fa704","vermerk":"Prüfpult"},"scenario":"In einem Versuch lernen Schimpansen, Marken in einen Automaten zu stecken und dafür Futter zu bekommen. Ein Beitrag zieht daraus den Schluss, die Tiere seien Teil unseres Geldsystems.","quote":"","quoteLabel":"","kurz":"Marken gegen Futter zu tauschen ist gelerntes Verhalten und noch kein Geld. Geld gilt, weil viele gemeinsam an seinen Wert glauben, und der Fehler liegt darin, Belohnungslernen mit dieser geteilten Vorstellung gleichzusetzen.","prueffrage":"Was tun die Tiere mit den Marken, wenn gerade kein Automat in der Nähe ist oder ein anderes Tier eine Marke anbietet?","rueckmeldung":[{"option":1,"text":"Eine hohe Tauschrate wirkt wie ein Beleg für echten Gebrauch. Sie zeigt aber nur, wie gut der Tausch eingeübt ist, und sagt nichts darüber, ob mehr als gelerntes Verhalten dahintersteckt."},{"option":2,"text":"Schimpansen gelten als klug, und das scheint zu einem Geldverständnis zu passen. Ihr Abschneiden in Intelligenztests sagt aber nichts darüber, ob sie mit den Marken eine geteilte Wertvorstellung verbinden."},{"option":3,"text":"Ob das Futter besser schmeckt, betrifft nur die Belohnung selbst. Es sagt nichts darüber, ob die Marken als Wert verstanden werden oder die Tiere bloß gelernt haben, was Futter bringt."}],"familie":"gemeinsamer-glaube","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Beran, M. J.; Parrish, A. E. (2021): Non-human primate token use shows possibilities but also limitations for establishing a form of currency. Philosophical Transactions of the Royal Society B 376(1819), 20190675 (PMC-Volltext)","oeffentlich":true,"doi":"10.1098/rstb.2019.0675","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7815425/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Wolfe, J. B. (1936): Effectiveness of token-rewards for chimpanzees. Comparative Psychology Monographs 12(5) (zitiert nach Beran & Parrish)","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1f6b04564b6fa704"}},{"id":"qx-e-043","clusterId":"E","werkstueckRef":"E.3.3","stufe":1,"question":"Eine Freundin sagt: „Ich habe keine Ideologie, ich bin einfach nur objektiv und pragmatisch. Wer anderer Meinung ist, folgt eben einer Ideologie.“ Welche Antwort trifft den Denkfehler am besten?","options":["Auch wer Belege sammelt, greift gern jene heraus, die zur eigenen Sicht passen. Der Satz stützt sich nur auf ausgewählte Beispiele und lässt Gegenbeispiele unter den Tisch fallen.","Auch wer sich für rein pragmatisch hält, bringt Grundannahmen darüber mit, was gerecht ist oder was Probleme verursacht. Die Annahme, keine zu haben, macht sie nur unsichtbar.","Auch wer sich auf Fachleute beruft, ersetzt damit noch keine Begründung. Der Satz stützt sich auf das Ansehen einer Autorität statt auf Gründe und ist deshalb ein Autoritätsargument.","Auch Gefühle können Argumente ersetzen, wenn sie gezielt geweckt werden. Der Satz will Furcht oder Mitleid wecken, statt etwas zu begründen, und genau darin liegt der Denkfehler."],"correctIndex":1,"explanation":"Eine Ideologie ist ein zusammenhängendes System aus Überzeugungen und Werten, das erklärt, wie die Welt ist, und zugleich sagt, wie sie sein sollte. Solche Grundannahmen hat praktisch jeder, etwa darüber, was gerecht ist oder woher Leid kommt. Die Annahme, es gebe keine Ideologie, ist selbst Teil einer Ideologie, meist der dominanten, unsichtbaren der eigenen Kultur. Wer sich für ideologiefrei hält, übersieht also seine eigene Brille und erkennt sie nur bei anderen. Der Fehler liegt darin, die eigene Brille für das Fehlen einer Brille zu halten. Gute Gegenfrage: „Welche Annahmen über Gerechtigkeit und Ursachen stecken in meiner Position?“ Die anderen Gedanken sind als Warnungen sinnvoll, treffen hier aber nicht zu: Die Freundin wählt keine Belege aus, denn sie nennt gar keine. Sie beruft sich auch auf keine Autorität. Und sie will keine Gefühle wecken, sondern behauptet nüchtern, neutral zu sein.","coreRule":"⚡ Wer glaubt, keine Weltsicht zu haben, hat trotzdem eine, und gerade diese bleibt ihm unsichtbar.","beleg":"Werkstück E.3.3 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Praktisch jeder bringt Grundannahmen mit, etwa darüber, was gerecht ist oder woher Probleme kommen. Wer sich für ideologiefrei hält, hält die eigene Brille für das Fehlen einer Brille und erkennt sie nur bei anderen.","prueffrage":"Woran misst die Freundin, was „objektiv“ oder „pragmatisch“ ist, und würde jemand mit anderen Werten denselben Maßstab wählen?","rueckmeldung":[{"option":0,"text":"Selektive Belegauswahl ist tatsächlich eine verbreitete Falle. Die Freundin nennt aber überhaupt keine Beispiele, also kann sie auch keine herauspicken. Das Problem liegt in ihrer Selbstbeschreibung als neutral."},{"option":2,"text":"Ein Verweis auf Autorität ersetzt wirklich keine Begründung. Hier beruft sich die Freundin jedoch auf niemanden außer sich selbst. Der Fehler steckt nicht in einer geliehenen Autorität, sondern in der Behauptung eigener Neutralität."},{"option":3,"text":"Gefühle können Argumente ersetzen, wenn sie gezielt geweckt werden. Die Freundin klingt aber nüchtern und will weder Furcht noch Mitleid auslösen. Gerade die behauptete Sachlichkeit ist der Punkt, an dem der Satz nicht trägt."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"},{"typ":"url","kurz":"Scherr, K. (2007): The End of the End of Ideology. APS Observer (Bericht über J. T. Jost)","oeffentlich":true,"url":"https://www.psychologicalscience.org/observer/the-end-of-the-end-of-ideology","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"304c2f40f2bd4f6c"}},{"id":"qx-e-044","clusterId":"E","werkstueckRef":"E.3.3","stufe":2,"question":"Was ist hier die klügste nächste Gesprächsstrategie?","scenario":"Dein Onkel sieht die Welt durch eine feste politische Überzeugung. Auf jede Statistik, die du ihm zeigst, antwortet er: „Das ist doch Propaganda“ – und wechselt das Thema. Du hast ihm schon mehrere Studien und Quellen vorgelegt, ohne dass sich etwas bewegt hat.","options":["Die Zahlen als anschauliche Grafik aufbereiten, damit er die Statistik besser versteht.","Seine Einwände vor Zuhörenden sachlich widerlegen, damit diese die Belege selbst bewerten.","Fragen, woran er verlässliche Quellen erkennt und welche Belege ihn umstimmen könnten.","Die vorgelegten Studien noch einmal auf Methodenfehler prüfen, damit sie keine Angriffsfläche bieten."],"correctIndex":2,"explanation":"Wer feste Überzeugungen hat, bewertet neue Informationen durch den Rahmen, den er schon mitbringt. Passt ein Fakt nicht hinein, wird er als Propaganda, Ausnahme oder irrelevant abgetan. Mehr Fakten desselben Typs ändern daran nichts, denn der Rahmen entscheidet, was überhaupt als Beleg zählt. Deshalb lohnt es sich, zuerst über die Spielregeln zu sprechen: Was zählt für ihn als verlässliche Quelle? Was müsste passieren, damit er seine Meinung ändert? Die anderen Schritte sind in anderen Lagen sinnvoll, helfen hier aber nicht: Eine Grafik hilft, wenn Zahlen schwer lesbar sind, er lehnt sie aber grundsätzlich als Propaganda ab. Zuhörende, die überzeugt werden könnten, kommen im Szenario nicht vor, es ist ein Gespräch unter zwei Personen. Und eine erneute Prüfung der Studien auf Methodenfehler wäre sinnvoll, wenn er die Methoden kritisierte, er weist aber jede Quelle pauschal zurück, ohne auf ihren Inhalt einzugehen.","coreRule":"⚡ Wenn Fakten abprallen, sprich über den Rahmen, nicht nur über die Daten.","beleg":"Werkstück E.3.3 (Anwendung & Relevanz: In der Politik; Kontext & Tiefe: Sich selbst immunisiert)","status":"entwurf","kurz":"Wer jede Quelle als Propaganda abtut, lehnt nicht einzelne Zahlen ab, sondern wendet einen Rahmen an, der festlegt, was als Beleg zählt. Weitere Fakten ändern daran nichts. Erst wenn ihr über die Spielregeln sprecht, wird ein Gespräch möglich.","prueffrage":"Was hat dein Onkel auf deine bisherigen Quellen jeweils geantwortet, und was haben diese Antworten gemeinsam?","rueckmeldung":[{"option":0,"text":"Eine Grafik macht Zahlen leichter lesbar, wenn Lesbarkeit das Hindernis ist. Der Onkel versteht die Statistik aber gar nicht schlechter, er lehnt sie grundsätzlich als Propaganda ab, und das ändert eine schönere Darstellung nicht."},{"option":1,"text":"Eine sachliche Widerlegung kann Zuhörende erreichen, die sich noch ein Urteil bilden. Im Szenario gibt es aber nur dich und deinen Onkel, also niemanden, der die Belege abwägen könnte."},{"option":3,"text":"Saubere Methoden zählen, wenn jemand sie kritisiert. Der Onkel geht aber auf keine Studie inhaltlich ein, sondern wehrt jede pauschal ab. Eine fehlerfreiere Studie träfe daher auf denselben Rahmen."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Kahan, D. M. (2013): Ideology, motivated reasoning, and cognitive reflection. Judgment and Decision Making 8(4), 407–424","oeffentlich":true,"url":"https://dlab.sauder.ubc.ca/sjdm/journal/13/13313/jdm13313.html","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f6bbcf7e75025f06"}},{"id":"qx-e-045","clusterId":"E","werkstueckRef":"E.3.3","stufe":3,"question":"Welche Beobachtung zeigt am deutlichsten, dass ihre Weltanschauung zum starren Dogma geworden ist?","options":["Die Weltanschauung bietet eine klare Diagnose, eine Zukunftsvision und eine Strategie und bringt ihre Mitglieder dadurch zum gemeinsamen Handeln.","Die Weltanschauung gibt ihren Mitgliedern ein starkes Gefühl von Zugehörigkeit und stiftet dadurch eine gemeinsame Identität.","Die Weltanschauung wird von sehr vielen Menschen geteilt und entfaltet dadurch eine große politische Wirkung in der Gesellschaft.","Widersprechende Belege werden als Beweis für die Verblendung der Kritiker gewertet, und kein denkbares Ereignis könnte die Überzeugung erschüttern."],"correctIndex":3,"explanation":"Erklärung, Handlungsimpuls und Zusammenhalt sind normale Leistungen jeder Weltanschauung, auch einer gesunden; sie sagen nichts darüber, ob man noch aus Gegenbelegen lernen kann. Auch große Verbreitung ist kein Warnzeichen, denn viele richtige und nützliche Ideen finden breite Zustimmung. Entscheidend ist die Frage, ob die Überzeugung noch widerlegbar ist. Wenn jeder Einwand zum Beweis für die Bösartigkeit oder Verblendung des Kritikers umgedeutet wird und es kein denkbares Ereignis gibt, das etwas ändern würde, dient die Weltanschauung nicht mehr dem Verständnis der Welt. Dann zählt die Treue zur eigenen Lehre mehr als das, was die Wirklichkeit zeigt.","coreRule":"⚡ Eine Weltanschauung wird starr, wenn nichts mehr sie widerlegen darf.","beleg":"Werkstück E.3.3 (Red Flags; Der Kipppunkt; Das Adaptive Talent)","status":"entwurf","scenario":"Eine Gruppe vertritt eine Weltanschauung, die große Fragen erklärt und ihren Mitgliedern Zusammenhalt gibt. Ein Mitglied legt ihr eine Studie vor, die einer ihrer Kernannahmen widerspricht. Die Gruppe antwortet: „Solche Studien werden von unseren Gegnern bezahlt. Wer sie ernst nimmt, ist blind für die Wahrheit.“ Auf Nachfrage räumt sie ein, dass es kein denkbares Ergebnis gäbe, das ihre Überzeugung ins Wanken brächte.","kurz":"Entscheidend ist, ob die Überzeugung noch widerlegbar ist. Wird jeder Einwand zum Beweis für die Verblendung des Kritikers und könnte kein denkbares Ergebnis etwas ändern, zählt die Treue zur Lehre mehr als das, was die Wirklichkeit zeigt.","prueffrage":"Was hat die Gruppe mit der vorgelegten Studie selbst gemacht, bevor sie antwortete?","rueckmeldung":[{"option":0,"text":"Diagnose, Vision und Strategie machen eine Gruppe handlungsfähig und sind ein Merkmal jeder Weltanschauung, auch einer gesunden. Ob man noch aus Gegenbelegen lernen kann, sagt das nicht."},{"option":1,"text":"Zugehörigkeit und gemeinsame Identität sind normale Leistungen, die auch gesunde Weltanschauungen erbringen. Sie zeigen nicht, ob die Überzeugung noch durch Belege erschütterbar wäre."},{"option":2,"text":"Viele richtige und nützliche Ideen finden breite Zustimmung, große Verbreitung ist also kein Warnzeichen. Und politische Wirkung sagt nichts darüber, ob die Überzeugung noch widerlegbar ist."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ebdcc8598e23846a"}},{"id":"qx-e-046","clusterId":"E","werkstueckRef":"E.3.3","stufe":4,"question":"Eine Kollegin sagt im Team: „Ich habe keine Ideologie, ich bin rein pragmatisch.“ Welche Erwiderung nimmt ihre Aussage ernst und bleibt zugleich logisch tragfähig?","options":["„Auch wer nur auf das Funktionierende schaut, legt vorher fest, was als funktionierend zählt. Dahinter steckt eine Weltsicht, die oft unsichtbar bleibt, weil alle um uns herum sie teilen.“","„Wer sich als rein sachlich hinstellt, verfolgt häufig ein Eigeninteresse. Frag dich, was du persönlich davon hast, bevor du dich neutral nennst, denn Interessen färben jede Einschätzung.“","„Pragmatische Entscheidungen brauchen oft belastbares Fachwissen. Wir sollten zuerst klären, wer von uns die nötige Sachkenntnis hat, damit das Urteil darüber, was funktioniert, auf Wissen beruht.“","„Ob etwas funktioniert, zeigt sich erst nach der Einführung. Vorher lässt sich kaum rein pragmatisch entscheiden, denn vor der Einführung fehlt jeder Beleg dafür, was funktioniert.“"],"correctIndex":0,"explanation":"Jeder Mensch hat eine Ideologie, auch wer glaubt, rein „objektiv“ oder „pragmatisch“ zu sein. Die Annahme, es gebe gar keine, ist selbst Teil einer Ideologie, meist der dominanten, unsichtbaren Ideologie der eigenen Kultur. Das lässt sich so begründen: „Pragmatisch“ zu sein beantwortet nicht die Frage, woran man Erfolg misst, etwa an Kosten, an Gerechtigkeit, an Freiheit oder an Geschwindigkeit. Was als „funktionierend“ gilt, setzt also eine Gewichtung voraus, und die gehört zu einer Weltsicht, auch wenn sie sich nicht so anfühlt. Gerade die Weltsicht, die alle in der Umgebung teilen, fällt nicht mehr auf und wird mit „neutral“ verwechselt. Hilfreich ist die Frage, wie jemand mit einer ganz anderen Weltsicht die Lage beurteilen würde und woran er Erfolg messen würde. Die anderen Erwiderungen enthalten für sich vernünftige Gedanken, passen aber nicht zu ihrer Aussage: Von einem Eigeninteresse der Kollegin ist nichts zu sehen, sie hält sich ja heraus. Ob Fachwissen im Team vorhanden ist, betrifft die Datenlage, nicht die Frage, woran Erfolg gemessen wird. Dass sich Wirkung erst später zeigt, ändert nichts daran, dass schon die Wahl des Maßstabs eine Gewichtung enthält.","coreRule":"⚡ Die unsichtbarste Brille ist die, die alle um dich herum auch tragen.","beleg":"Werkstück E.3.3 (Kontext & Tiefe; Anti-Denkmuster): „Eine Ideologie hat jeder, auch wenn er glaubt, rein ‚objektiv‘ oder ‚pragmatisch‘ zu sein.“","status":"entwurf","scenario":"In einer Besprechung über ein neues Förderprogramm wird heftig gestritten. Die Kollegin hält sich heraus und sagt: „Ich habe keine Ideologie, ich bin rein pragmatisch. Ich schaue nur, was funktioniert.“","quote":"Eine Ideologie hat jeder, auch wenn er glaubt, rein „objektiv“ oder „pragmatisch“ zu sein.","quoteLabel":"Merksatz:","kurz":"Wer nur schaut, was funktioniert, muss vorher festlegen, woran er Erfolg misst, etwa an Kosten, Gerechtigkeit oder Tempo. Diese Gewichtung ist eine Weltsicht, und weil das Umfeld sie teilt, hält man sie leicht für neutral.","prueffrage":"Woran würde jemand mit ganz anderen Prioritäten bei diesem Programm merken, dass es „funktioniert“?","rueckmeldung":[{"option":1,"text":"Interessen können Urteile tatsächlich färben. Für diese Kollegin ist aber kein Eigeninteresse zu sehen, sie hält sich ja heraus. Die Erwiderung unterstellt ein Motiv, statt auf ihre Aussage selbst einzugehen."},{"option":2,"text":"Belastbares Fachwissen hilft oft, und Sachkenntnis ist wichtig. Sie betrifft aber die Datenlage und beantwortet nicht, woran Erfolg gemessen wird. Genau diese Gewichtung bleibt auch bei viel Wissen offen."},{"option":3,"text":"Belege über die Wirkung zeigen sich oft erst später, das stimmt. Selbst mit ihnen bleibt aber offen, woran man „funktioniert“ misst. Schon die Wahl dieses Maßstabs enthält eine Gewichtung, die nicht aus den Daten folgt."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"},{"typ":"url","kurz":"Pronin, E.; Gilovich, T.; Ross, L. (2004): Objectivity in the eye of the beholder: divergent perceptions of bias in self versus others. Psychological Review 111(3), 781–799 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1037/0033-295X.111.3.781","url":"https://pubmed.ncbi.nlm.nih.gov/15250784/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3b64a6fbd86560d0"}},{"id":"qx-e-047","clusterId":"E","werkstueckRef":"E.3.4","stufe":1,"question":"Welche Schlussfolgerung ist am besten begründet?","options":["Es handelt sich um eine Regression zur Mitte, denn Kinder mit besonders niedrigen Testwerten schneiden beim nächsten Mal meist besser ab.","Die Kinder kamen aus anregenderen Elternhäusern, denn Kinder aus solchen Familien legen im Schulalter meist schneller zu.","Die Kinder wurden durch die Teilnahme am Test motiviert, denn Menschen leisten mehr, wenn sie sich beobachtet fühlen.","Die Kinder hatten Lehrkräfte mit höheren Erwartungen, denn die Auswahl war zufällig und nur die Erwartung unterschied sich."],"correctIndex":3,"explanation":"Die Kinder wurden per Los gezogen, ihre angeblichen Testergebnisse waren erfunden. Die einzige Variable, die sich geändert hatte, war die Erwartungshaltung der Lehrkräfte. Als Wirkweg gilt das Verhalten der Lehrkräfte, das sich aus ihrer Erwartung ergeben kann: wärmerer Umgang, anspruchsvollere Aufgaben, klarere Rückmeldungen, mehr Gelegenheit zur Beteiligung. So kann eine bloße Erwartung selbst zur Ursache dessen werden, was sie vorhersagt. Vorsicht bei der Größenordnung: Im ursprünglichen Experiment von Rosenthal und Jacobson lag der Zuwachs bei rund zwölf statt acht IQ-Punkten, und der Vorsprung zeigte sich fast nur in der ersten und zweiten Klasse. Spätere Forschung findet solche Effekte meist klein und wenig dauerhaft. Die Schlussfolgerung betrifft deshalb die Ursache des Unterschieds, nicht ein großes, sicheres Ausmaß. Die anderen Gedanken sind für sich bekannte Erklärungen, passen aber nicht zu diesem Aufbau: Eine Regression zur Mitte setzt voraus, dass nach auffälligen Testwerten ausgewählt wurde, hier entschied das Los. Unterschiede im Elternhaus verteilen sich bei einer Auswahl per Los im Schnitt gleichmäßig auf beide Gruppen. Und die Teilnahme am Test betraf alle Kinder, kann also den Unterschied zwischen den Gruppen nicht erklären.","coreRule":"⚡ Wenn die Gruppen per Zufall gebildet wurden, bleibt als Ursache nur, was sich zwischen ihnen tatsächlich unterscheidet, hier die Erwartung.","beleg":"Werkstück E.3.4 (Einstieg: Die akademischen Überflieger); Fn. gl-e-rosenthal (Rosenthal & Jacobson 1966/1968)","status":"entwurf","scenario":"Ein Schulleiter lässt an einer Grundschule alle Kinder einen IQ-Test schreiben. Danach teilt er den Lehrkräften vertraulich mit, welche 20 % der Kinder laut Test im kommenden Jahr besonders stark aufblühen werden. Tatsächlich hat er die Namen per Los gezogen. Am Jahresende haben diese Kinder im Schnitt mehr dazugewonnen als ihre Mitschüler.","kurz":"Weil das Los entschied, unterschied sich die Gruppe nur durch die Erwartung der Lehrkräfte, die ihr Verhalten verändern kann. Der naheliegende Fehler ist, nach einer bekannten Erklärung zu greifen, die zum Aufbau nicht passt.","prueffrage":"Was wusste der Schulleiter über die Kinder, deren Namen er den Lehrkräften nannte?","rueckmeldung":[{"option":0,"text":"Regression zur Mitte gibt es wirklich, aber sie tritt nur auf, wenn man nach auffälligen Messwerten auswählt. Hier entschied das Los, die angeblichen Testwerte waren erfunden, es gab also keine Extremwerte, die sich zurückbilden könnten."},{"option":1,"text":"Ein anregendes Elternhaus fördert das Lernen oft tatsächlich. Bei einer Auswahl per Los verteilen sich solche Unterschiede aber im Schnitt gleichmäßig auf beide Gruppen und können den Vorsprung der Gezogenen nicht erklären."},{"option":2,"text":"Das Gefühl, beobachtet zu werden, kann die Leistung beeinflussen. Alle Kinder schrieben aber denselben Test, daher kann dieser Einfluss keinen Unterschied zwischen den Gruppen erzeugen."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2), 131–155 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0902_3","url":"https://pubmed.ncbi.nlm.nih.gov/15869379/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2) (Verlagsfassung)","oeffentlich":false,"seite":"134"},{"typ":"doi","kurz":"Rosenthal, R.; Jacobson, L. (1966): Teachers' Expectancies: Determinants of Pupils' IQ Gains. Psychological Reports 19(1), 115–118","oeffentlich":false,"doi":"10.2466/pr0.1966.19.1.115"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"57c5538e8731500e"}},{"id":"qx-e-048","clusterId":"E","werkstueckRef":"E.3.4","stufe":2,"question":"Welche Erklärung dafür, dass sich Fehler und Lustlosigkeit häufen, ist am sparsamsten und lässt sich am besten prüfen?","scenario":"Ein neuer Abteilungsleiter hält sein Team für wenig fähig. Er prüft jede Kleinigkeit nach und vergibt keine eigenständigen Aufgaben. Nach einigen Monaten häufen sich Fehler und Lustlosigkeit, und er sagt: „Ich habe es ja gewusst.“","options":["Seine Erwartung hat sein Verhalten geprägt, das Team reagierte mit Unsicherheit und Fehlern, die seine Erwartung scheinbar bestätigen.","Die Mitarbeiter überschätzen ihr Können und bemerken eigene Fehler nicht, sodass diese sich häufen (Dunning-Kruger-Effekt).","Im Team verlässt sich jeder auf die anderen und gibt weniger, sodass Fehler und Lustlosigkeit entstehen (soziales Faulenzen).","Im Team hat sich Gruppendenken breitgemacht, Zweifel werden unterdrückt, sodass Fehler unentdeckt bleiben und sich häufen."],"correctIndex":0,"explanation":"Der Manager misstraut seinem Team, kontrolliert es engmaschig und überträgt keine Verantwortung. Wer so behandelt wird, wird oft unsicher und demotiviert und macht mehr Fehler, was die ursprüngliche Erwartung scheinbar bestätigt. So kann ein sich selbst verstärkender Kreislauf aus Überzeugung, Handlung, Selbstbild und Gegenhandlung entstehen (Golem-Effekt). Seine Aussage „Ich habe es ja gewusst“ taugt nicht als Beweis, denn die Fehler können Folge seines Verhaltens sein. Prüfen ließe sich das, indem man klärt, ob die Fehler schon vor seinem Kontrollverhalten auftraten oder erst danach, oder indem er probeweise Verantwortung überträgt und beobachtet, ob sich die Leistung ändert. Wichtig bleibt: Dass Erwartungen Leistungen beeinflussen können, zeigt sich im Klassenzimmer, die Effekte sind aber meist klein und wenig dauerhaft, und oft sagen Erwartungen Leistungen nur deshalb voraus, weil sie zutreffen. Deshalb braucht es einen Vergleich, bevor man sicher urteilt. Die anderen Erklärungen nennen bekannte Mechanismen, brauchen hier aber zusätzliche Annahmen, von denen im Szenario nichts steht. Dunning-Kruger würde eine Selbstüberschätzung der Mitarbeiter voraussetzen, und soziales Faulenzen entsteht, wenn Einzelbeiträge unsichtbar bleiben, während hier jede Kleinigkeit kontrolliert wird. Gruppendenken verlangt eine gemeinsame, unwidersprochene Sicht im Team, über die nichts gesagt wird.","coreRule":"⚡ Wer von anderen wenig erwartet, bekommt oft genau das – und hält es für die Bestätigung. Prüfe darum, ob die Fehler vor oder nach dem eigenen Verhalten auftraten.","beleg":"Werkstück E.3.4 (Kontext & Tiefe: Kreislauf, Golem-Effekt; Anwendung & Relevanz: In der Führung & im Management)","status":"entwurf","kurz":"Am sparsamsten ist, was das Szenario selbst liefert: Sein Misstrauen und die Dauerkontrolle können Unsicherheit und Fehler erst hervorbringen. Dass er recht behielt, beweist nichts, denn seine Erwartung kann das Ergebnis mitverursacht haben.","prueffrage":"Waren die Fehler und die Lustlosigkeit schon da, bevor er mit der Kontrolle begann, oder erst danach?","rueckmeldung":[{"option":1,"text":"Überschätzung der eigenen Fähigkeiten ist ein bekannter Effekt, und er könnte Fehler erklären. Im Szenario steht aber nichts davon, dass das Team sich überschätzt oder Fehler übersieht, die Erklärung braucht also eine zusätzliche Annahme."},{"option":2,"text":"Soziales Faulenzen kommt vor, wenn Einzelbeiträge in der Gruppe untergehen. Hier ist es umgekehrt: Der Leiter prüft jede Kleinigkeit nach, jeder Beitrag ist sichtbar. Der Mechanismus passt deshalb schlecht zur geschilderten Lage."},{"option":3,"text":"Gruppendenken ist ein echtes Phänomen, setzt aber eine gemeinsame, unwidersprochene Sicht im Team voraus, über die nichts berichtet wird. Die Erklärung kommt ohne diese zusätzliche Annahme nicht aus, die erste dagegen schon."}],"familie":"erwartung-erfuellt-sich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2), 131–155 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0902_3","url":"https://pubmed.ncbi.nlm.nih.gov/15869379/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"cd242c582dcad02c"}},{"id":"qx-e-049","clusterId":"E","werkstueckRef":"E.3.4","stufe":3,"question":"Welche Einschätzung des Forschungsstands ist angemessen?","options":["Der Effekt ist belegt, aber meist klein und wenig dauerhaft; dass er die Intelligenz tatsächlich verändert, ist offen, und Erwartungen treffen oft einfach zu.","Der Effekt ist belegt und hält meist über Jahre an; dass er die Intelligenz tatsächlich steigert, gilt als geklärt, und Erwartungen treffen oft einfach zu.","Der Effekt ließ sich in späteren Untersuchungen kaum bestätigen; die Befunde von 1966 gelten daher als Ausreißer, und Erwartungen treffen oft einfach zu.","Der Effekt ist noch nicht beurteilbar, solange keine Wiederholung vorliegt; der Befund von 1966 bleibt offen, und Erwartungen treffen oft einfach zu."],"correctIndex":0,"explanation":"Die Behauptung „beweist, dass … allein durch Erwartungen steigern“ geht weit über die Datenlage hinaus. Spätere Forschung bestätigt, dass Lehrererwartungen Schülerleistungen beeinflussen können, findet die Effekte aber meist klein und wenig dauerhaft. Ob dadurch die Intelligenz selbst steigt, ist ungeklärt. Dazu kommt: Lehrererwartungen sagen Leistungen oft deshalb voraus, weil sie zutreffen, nicht weil sie sich erfüllen. Schon die Originalstudie spricht gegen eine große, allgemeine Wirkung: Der Vorsprung stammte fast ganz aus den ersten beiden Klassen und zeigte sich in höheren Klassen nicht. Wer sauber urteilt, hält deshalb beides auseinander: Dass es selbsterfüllende Prophezeiungen im Klassenzimmer gibt, ist belegt, aber meist klein; dass sie die Intelligenz verändern, ist offen. Die anderen Einschätzungen klingen für sich vernünftig, passen aber nicht zu den genannten Befunden: Ein Effekt, der meist über Jahre anhält, widerspricht der Beobachtung, dass er oft nicht von Dauer ist. Dass spätere Untersuchungen kaum etwas fanden, widerspricht dem wiederholten Nachweis im Klassenzimmer. Und dass noch keine Wiederholung vorliege, trifft nicht zu, denn spätere Untersuchungen gibt es.","coreRule":"⚡ „Erwartungen wirken“ ist belegt – „Erwartungen machen klüger“ ist es nicht.","beleg":"Werkstück E.3.4 (Hinweis zur Beleglage); Fn. gl-e-rosenthal (Jussim & Harber 2005, S. 131, 134 f., 140, 142 f.)","status":"entwurf","scenario":"In einem Lehrbuch steht: „Rosenthals Studie von 1966 beweist, dass Lehrer die Intelligenz ihrer Schüler allein durch Erwartungen steigern können.“ Du liest nach: In der Originalstudie erhielten zufällig ausgewählte Kinder („Überflieger“) einen Zuwachs von rund zwölf statt acht IQ-Punkten, und dieser Vorsprung zeigte sich fast nur in der ersten und zweiten Klasse. Spätere Untersuchungen fanden selbsterfüllende Prophezeiungen im Klassenzimmer zwar immer wieder, aber meist klein und oft nicht von Dauer. Außerdem schätzen Lehrkräfte die Leistungen ihrer Schüler oft schon vorab recht treffend ein.","kurz":"Spätere Forschung bestätigt Erwartungseffekte, findet sie aber meist klein und oft nicht von Dauer; ob die Intelligenz selbst steigt, bleibt offen. „Beweist“ und „allein“ im Lehrbuch gehen weit über diese Datenlage hinaus.","prueffrage":"Wie groß war der Vorsprung der „Überflieger“ gegenüber den übrigen Kindern in IQ-Punkten, und in welchen Klassen trat er auf?","rueckmeldung":[{"option":1,"text":"Dass der Effekt existiert und Erwartungen oft zutreffen, stimmt. Die Dauer trägt aber nicht: Die Wirkung war meist klein und oft nicht von Dauer, schon 1966 zeigte sie sich fast nur in den ersten beiden Klassen. Auch „geklärt“ ist zu viel, ob die Intelligenz selbst steigt, bleibt offen."},{"option":2,"text":"Dass Erwartungen oft einfach zutreffen, stimmt. Es hat aber nicht gefehlt am Effekt: Selbsterfüllende Prophezeiungen im Klassenzimmer fanden sich immer wieder, nur meist klein. Von „kaum bestätigt“ oder „Ausreißer“ kann deshalb keine Rede sein."},{"option":3,"text":"Dass die Studie von 1966 allein die große Behauptung nicht trägt, stimmt. Eine Wiederholung fehlt aber nicht: Spätere Untersuchungen fanden den Effekt immer wieder, meist klein. Offen ist nur, ob dadurch die Intelligenz selbst steigt."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2), 131–155 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0902_3","url":"https://pubmed.ncbi.nlm.nih.gov/15869379/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2) (Verlagsfassung)","oeffentlich":false,"seite":"134"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7bd8f9f3b838e4ed"}},{"id":"qx-e-050","clusterId":"E","werkstueckRef":"E.3.4","stufe":4,"question":"Wie sicher darfst du aus diesem Befund sein, und welche Schlussfolgerung ist angemessen?","options":["Der Mechanismus ist plausibel und damit für diese Gruppe hinreichend gestützt; die Studie zeigt Effekte bei anderen Gruppen, was diesen Fall nicht berührt.","Der Mechanismus ist plausibel, für diese Gruppe aber nicht belegt; die Studie spricht dagegen und zeigt Effekte bei anderen Gruppen.","Der Mechanismus ist für diese Gruppe widerlegt; die Studie zeigt, dass Erwartungen bei Mädchen in Mathematik überhaupt nicht wirken.","Die Schlussfolgerung bleibt vorerst richtig, denn ein einzelner Befund wiegt weniger als eine schlüssige Argumentation, auch wenn er in eine andere Richtung weist."],"correctIndex":1,"explanation":"Die Argumentation ist logisch glatt, aber sie behauptet einen Effekt, den man messen kann, und die Messung stützt ihn für diese Gruppe nicht: Bei Mädchen in Mathematik wirkten Lehrererwartungen in der großen Studie nicht stärker als bei Jungen, bei afroamerikanischen Schülern und bei leistungsschwachen Kindern aus ärmeren Familien dagegen deutlich stärker. Damit ist weder bewiesen, dass der Effekt überall wirkt, noch, dass es ihn nirgends gibt. Das Gesamtbild nennen die Autoren für diese Gruppenbefunde „mixed“; ob Stereotype so einen Golem-Effekt im großen Stil auslösen, ist offen. Ein einleuchtender Mechanismus liefert eine Hypothese, keinen Beleg; ob und bei wem er greift, entscheiden die Daten. Die anderen Einschätzungen greifen bekannte Gedanken auf, passen aber nicht zu diesem Befund: Plausibilität allein ersetzt keine Messung, wenn eine Messung vorliegt und nichts Stärkeres zeigt. Ein Befund, der nur „nicht stärker als bei Jungen“ lautet, ist kein Nachweis, dass gar keine Wirkung besteht. Dass man einzelne Studien vorsichtig gewichtet, ist richtig, rechtfertigt es aber nicht, eine Messung gegenüber einer bloßen Überlegung zu ignorieren.","coreRule":"⚡ Ein einleuchtender Mechanismus ist noch kein belegter Effekt in jeder Gruppe.","beleg":"Werkstück E.3.4 (Anwendung & Relevanz: Im Umgang mit sozialen Stereotypen); Fn. gl-e-rosenthal (Jussim & Harber 2005)","status":"entwurf","scenario":"In einer Diskussion heißt es: „Stereotype sind negative Erwartungen. Negative Erwartungen verschlechtern Leistungen. Also verschlechtert das Stereotyp ‚Mädchen sind schlecht in Mathe' die Mathematikleistungen von Mädchen.“ Du kennst eine große Studie zu Lehrererwartungen: Bei Mädchen in Mathematik wirkten die Erwartungen nicht stärker als bei Jungen. Deutlich stärker wirkten sie bei afroamerikanischen Schülern und bei leistungsschwachen Kindern aus ärmeren Familien.","kurz":"Ein einleuchtender Mechanismus ist eine Hypothese, kein Beleg. Hier spricht die Messung bei Mädchen in Mathematik nicht für ihn, während Erwartungen bei anderen Gruppen deutlich stärker wirkten. Widerlegt ist er damit allerdings nicht, das Gesamtbild bleibt offen.","prueffrage":"Was ließe sich an Leistungsdaten von Mädchen und Jungen messen, wenn der behauptete Effekt tatsächlich bestünde?","rueckmeldung":[{"option":0,"text":"Dass der Mechanismus plausibel klingt und bei anderen Gruppen Effekte auftraten, stimmt. Die Studie hat aber genau diese Gruppe untersucht und dort nicht mehr gefunden als bei Jungen. Plausibilität allein stützt dann nicht hinreichend."},{"option":2,"text":"Der Befund spricht tatsächlich gegen den Mechanismus. Er lautet aber nur „nicht stärker als bei Jungen“, das ist kein Nachweis, dass Erwartungen gar nicht wirken. „Widerlegt“ ist deshalb zu stark, offen bleibt die Frage trotzdem."},{"option":3,"text":"Einzelne Studien vorsichtig zu gewichten ist richtig. Hier steht aber keine bloße Überlegung gegen ein Gerücht, sondern eine Messung gegen eine Argumentation. Eine schlüssige Herleitung ersetzt keine Daten und lässt die Schlussfolgerung nicht einfach „richtig“ bleiben."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2), 131–155 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0902_3","url":"https://pubmed.ncbi.nlm.nih.gov/15869379/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Jussim, L.; Harber, K. D. (2005): Teacher Expectations and Self-Fulfilling Prophecies. Personality and Social Psychology Review 9(2) (Verlagsfassung)","oeffentlich":false,"seite":"142 f."}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f8fe4a0d89dbed21"}},{"id":"qx-e-051","clusterId":"E","werkstueckRef":"E.3.5","stufe":1,"question":"Eine Kommentatorin sagt: „Vor zwanzig Jahren hätte kein Politiker einen Vorschlag wie diesen öffentlich gemacht, heute wird er in Talkshows ernsthaft diskutiert. Dabei hat sich an den Argumenten kaum etwas geändert.“ Welche Schlussfolgerung passt am besten zu dieser Beobachtung?","options":["Der Rahmen des öffentlich Akzeptablen hat sich verschoben, sodass die Idee nun diskutierbar geworden ist.","Durch häufiges Hören hat sich die Öffentlichkeit an die Idee gewöhnt (Mere-Exposure-Effekt) und stimmt ihr nun zu.","In offener Debatte setzen sich stärkere Argumente durch, sodass die Idee diese Prüfung nun bestanden hat.","Kritiker schweigen aus Angst vor Isolation (Schweigespirale), sodass die Idee in Talkshows weit verbreitet wirkt."],"correctIndex":0,"explanation":"Die Beobachtung sagt nur, dass die Idee heute besprochen wird, nicht dass sie überzeugt oder mehrheitsfähig geworden ist. Politische Veränderung entsteht oft nicht dadurch, dass man die Wähler überzeugt, sondern dadurch, dass sich das „Fenster der Akzeptanz“ (das Overton-Fenster, benannt nach Joseph P. Overton) langsam verschiebt: Eine Idee kann also vom Undenkbaren zum Diskutablen werden, ohne dass die Mehrheit sie schon befürwortet. Wer aus „wird diskutiert“ auf „wird mehrheitlich befürwortet“ oder „war schon immer richtig“ schließt, verwechselt Sagbarkeit mit Zustimmung bzw. Wahrheit. Die anderen Gedanken sind für sich bekannte Mechanismen, passen aber nicht zur Beobachtung: Ein Gewöhnungseffekt würde Zustimmung erklären, von der hier nirgends die Rede ist. Dass sich die besseren Argumente durchsetzen, passt nicht dazu, dass sich an den Argumenten kaum etwas geändert hat. Und für eine Schweigespirale gibt es keinen Hinweis, denn niemand wird als verstummt beschrieben.","coreRule":"⚡ Dass etwas diskutiert wird, heißt nicht, dass es überzeugt hat. Prüfe, ob sich die Argumente geändert haben oder nur das, was als sagbar gilt.","beleg":"Werkstück E.3.5 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Aus der Beobachtung folgt nur, dass die Idee heute sagbar ist, nicht dass sie überzeugt. Der naheliegende Fehler ist, „wird diskutiert“ mit „wird befürwortet“ oder „ist richtig“ zu verwechseln, obwohl sich nur der Rahmen des Akzeptablen verschoben haben kann.","prueffrage":"Was hat sich laut Kommentatorin in zwanzig Jahren verändert, und was ist gleich geblieben?","rueckmeldung":[{"option":1,"text":"Dass häufiges Hören vertraut machen kann, ist ein bekannter Effekt. Die Beobachtung sagt aber nur, dass der Vorschlag besprochen wird, von Zustimmung ist nirgends die Rede. Diese Antwort macht aus „wird diskutiert“ stillschweigend „wird befürwortet“."},{"option":2,"text":"Offene Debatte kann bessere Argumente stärken. Hier hat sich aber an den Argumenten kaum etwas geändert, sie können also nicht der Grund für den Wandel sein. Auch dass die Idee eine Prüfung bestanden hätte, steht nirgends."},{"option":3,"text":"Eine Schweigespirale kann den Eindruck verbreiteter Meinungen erzeugen. Im Beispiel wird aber niemand als verstummt beschrieben, und es geht um das, was gesagt werden darf, nicht um einen vorgetäuschten Mehrheitseindruck. Für Angst vor Isolation gibt es keinen Hinweis."}],"familie":"sagbarkeit-verschiebt-sich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mackinac Center for Public Policy: The Overton Window","oeffentlich":true,"url":"https://www.mackinac.org/OvertonWindow","abruf":"2026-10-12"},{"typ":"url","kurz":"Lehman, J. G. (2023): The legacy of the Overton Window. Mackinac Center for Public Policy, Blog, 30.06.2023","oeffentlich":true,"url":"https://www.mackinac.org/blog/2023/the-legacy-of-the-overton-window","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1757f7494af97618"}},{"id":"qx-e-052","clusterId":"E","werkstueckRef":"E.3.5","stufe":2,"question":"In einer Gesellschaft, in der Rauchen überall normal ist, gilt ein Rauchverbot in Innenräumen zunächst als politisch undenkbar. Jahre später schlägt eine gemäßigte Gruppe vor: „Vielleicht nicht überall, aber in Krankenhäusern.“ Dieser Vorschlag findet breite Zustimmung. Was erklärt das am besten?","options":["Der Bestätigungsfehler: Menschen beachten vor allem Hinweise, die ihre Haltung stützen, sodass sich bestehende Meinungen verfestigen.","Das Overton-Fenster: Hartnäckige Verfechter rückten die Idee vom Undenkbaren zum Radikalen, sodass der Kompromiss nun gemäßigt wirkt.","Die Verlustaversion: Menschen gewichten drohende Verluste stärker als Gewinne, sodass sie Neuem zunächst skeptisch gegenüberstehen.","Der Rückschaufehler: Im Nachhinein wirkt die Zustimmung selbstverständlich, sodass man glaubt, die Mehrheit habe es immer gewollt."],"correctIndex":1,"explanation":"Politische Ideen gelten nicht aus sich heraus als „radikal“ oder „vernünftig“, sondern immer relativ zu dem, was eine Gesellschaft gerade für akzeptabel hält. Das Overton-Fenster beschreibt diese Bandbreite des öffentlich Akzeptablen. Es kann dazu beitragen, dass eine zuvor undenkbare Forderung wiederholt vorgetragen wird, Studien erscheinen und Medien das Thema aufgreifen: Die Idee rückt dann von „undenkbar“ zu „radikal“. Erst dadurch wirkt ein abgeschwächter Vorschlag wie ein vernünftiger Mittelweg. Zugleich verschiebt sich das Fenster meist durch den langsamen Wandel von Werten und Normen. Niemand muss dafür über Nacht überzeugt werden: Verschoben hat sich der Rahmen dessen, was als akzeptable Meinung gilt. Die anderen Optionen nennen echte Denkmuster, erklären den Fall aber nicht: Der Bestätigungsfehler erklärt, warum Haltungen stabil bleiben, nicht warum sie sich verschieben. Die Verlustaversion erklärt, warum Neues zunächst abgelehnt wird, nicht warum es später breite Zustimmung findet. Und der Rückschaufehler betrifft die Erinnerung an frühere Ansichten, erklärt aber nicht, warum der Vorschlag vorher als undenkbar galt.","coreRule":"⚡ Ein „vernünftiger Kompromiss“ ist oft nur deshalb vernünftig, weil der Rahmen des Akzeptablen sich vorher verschoben hat.","beleg":"Werkstück E.3.5 (Einstieg: Die Debatte, die niemand wollte; Kernidee)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Eine Idee gilt immer relativ zu dem, was gerade als akzeptabel durchgeht. Rückt die Forderung nach Rauchverbot vom Undenkbaren zum Radikalen, wirkt der Kompromiss für Krankenhäuser plötzlich vernünftig, ohne dass jemand umgestimmt werden müsste.","prueffrage":"Wie wurde der Krankenhaus-Vorschlag früher eingeschätzt, und was hat sich zwischen damals und heute verändert?","rueckmeldung":[{"option":0,"text":"Der Bestätigungsfehler ist ein echtes Muster, es erklärt aber, warum Haltungen stabil bleiben. Hier hat sich etwas bewegt: Was als akzeptabel gilt, hat sich verschoben, und das erklärt er nicht."},{"option":2,"text":"Verlustaversion erklärt gut, warum Neues zunächst auf Skepsis stößt, also die frühere Ablehnung. Warum der Vorschlag später breite Zustimmung findet und gemäßigt wirkt, bleibt damit offen."},{"option":3,"text":"Der Rückschaufehler betrifft, wie wir uns an frühere Ansichten erinnern. Hier geht es aber um eine tatsächliche Veränderung, und er erklärt nicht, warum der Vorschlag zuvor als undenkbar galt."}],"familie":"sagbarkeit-verschiebt-sich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mackinac Center for Public Policy: The Overton Window","oeffentlich":true,"url":"https://www.mackinac.org/OvertonWindow","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9b09af12c3896d1e"}},{"id":"qx-e-053","clusterId":"E","werkstueckRef":"E.3.5","stufe":3,"question":"Zwei Beobachter diskutieren über das Overton-Fenster, ein Modell dafür, was in der Öffentlichkeit als akzeptable Meinung gilt. Beobachterin A sagt: „Das Modell zeigt, dass solche Verschiebungen dessen, was gesagt werden darf, gefährlich sind.“ Beobachter B sagt: „Das Modell zeigt, dass solche Verschiebungen gesellschaftlichen Fortschritt bedeuten.“ Wie lässt sich der Denkfehler beider am besten auflösen?","options":["Das Modell beschreibt nur, dass sich Grenzen verschieben; ob das gut oder schlecht ist, hängt von Richtung und Inhalt der Idee ab.","Das Modell belegt keine Ursache: Es zeigt nur, dass sich Grenzen und Haltungen gemeinsam verändern, nicht, was das eine am anderen auslöst.","Das Modell misst nicht selbst, was Menschen akzeptieren; erst eine repräsentative Umfrage zeigt, wie weit sich das Fenster tatsächlich verschoben hat.","Das Modell erfasst nur Parteipolitik; für Normen wie das Wahlrecht oder Rauchverbote gilt es nicht, daher sind beide Aussagen gegenstandslos."],"correctIndex":0,"explanation":"Das Overton-Fenster ist ein neutrales Modell zur Beschreibung von sozialem Wandel: Es sagt, welche Ideen gerade als akzeptabel gelten und wie sich das ändern kann, aber nicht, ob eine Verschiebung wünschenswert ist. Die Gefahr liegt nicht im Modell, sondern in der Richtung der Verschiebung. Dieselbe Mechanik trug das Frauenwahlrecht und Umweltschutzgesetze in den Mainstream, sie dient aber auch extremistischen Bewegungen, die ihre fremdenfeindlichen oder autoritären Ideen als „akzeptabel“ oder „vernünftig“ erscheinen lassen wollen. A schließt von „Verschiebung möglich“ auf „Verschiebung gefährlich“, B auf „Verschiebung gut“. Beides überspringt die Bewertung des Inhalts und der Richtung. Die anderen Gedanken sind für sich sinnvoll, lösen den Fehler aber nicht: Dass das Modell keine Ursachen belegt, ändert nichts daran, dass beide aus einer Beschreibung ein Werturteil ableiten. Dass eine Umfrage zeigt, wie weit sich das Fenster verschoben hat, sagt noch nichts darüber, ob die Verschiebung gut ist. Und das Modell gilt für gesellschaftliche Normen ebenso, die genannten Beispiele zeigen es ja.","coreRule":"⚡ Ein Modell beschreibt, wie sich etwas verändert, nicht ob es gut ist – bewerten musst du Richtung und Inhalt der Veränderung.","beleg":"Werkstück E.3.5 (Der Kipppunkt; Anwendung & Relevanz)","status":"entwurf","scenario":"Das Overton-Fenster beschreibt, welche Ideen zu einem bestimmten Zeitpunkt als akzeptabel gelten. Früher undenkbare Ideen wie das Frauenwahlrecht, Umweltschutzgesetze oder Rauchverbote in öffentlichen Gebäuden wanderten über Jahrzehnte in den Mainstream. Extremistische Bewegungen versuchen ebenfalls, ihre Positionen schrittweise als „akzeptabel“ oder „vernünftig“ erscheinen zu lassen.","kurz":"Das Overton-Fenster beschreibt nur, dass sich Grenzen des Sagbaren verschieben, nicht ob das gut ist. A und B machen aus „möglich“ ein Urteil, ohne Richtung und Inhalt der jeweiligen Idee zu prüfen. Dieselbe Mechanik trug das Frauenwahlrecht und dient Extremisten.","prueffrage":"Wie würden A und B das Frauenwahlrecht beurteilen, und wie die Vorstöße extremistischer Bewegungen?","rueckmeldung":[{"option":1,"text":"Dass das Modell keine Ursachen belegt, stimmt, nur ist das nicht der Fehler von A und B. Sie behaupten gar keinen Auslöser, sondern machen aus einer bloßen Beschreibung ein Werturteil. Daran ändert eine Ursachenfrage nichts."},{"option":2,"text":"Eine Umfrage könnte tatsächlich zeigen, wie weit sich das Fenster verschoben hat. Sie klärt aber nur das Ausmaß, nicht den Wert: Ob eine Verschiebung wünschenswert ist, steht auch nach der Messung noch offen."},{"option":3,"text":"Das Modell wird oft in politischen Debatten benutzt, deshalb liegt der Gedanke nahe. Doch die genannten Beispiele wie Frauenwahlrecht oder Rauchverbote sind gesellschaftliche Normen, und das Modell greift auch dort. Gegenstandslos sind die Aussagen daher nicht."}],"familie":"sagbarkeit-verschiebt-sich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mackinac Center for Public Policy: The Overton Window","oeffentlich":true,"url":"https://www.mackinac.org/OvertonWindow","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d70548d20569b695"}},{"id":"qx-e-054","clusterId":"E","werkstueckRef":"E.3.5","stufe":4,"question":"Ein Artikel behauptet: „Joseph Overton hat die sechs Stufen von ‚undenkbar‘ bis ‚Politik‘ entwickelt, und Politiker verschieben das Fenster gezielt selbst.“ Du findest dazu eine Quelle, in der sein Kollege Joseph Lehman (selbst Mitarbeiter des Thinktanks, in dem Overton arbeitete) Overtons Rolle beschreibt. Lehman schreibt: Overton habe das Konzept Mitte der 1990er-Jahre entwickelt, Lehman selbst habe es nach Overtons Tod benannt und formalisiert; Overton habe dazu nie eine Arbeit veröffentlicht, und der Thinktank zeige das Fenster heute ohne die sechs Stufen. Politiker verschöben es nur selten selbst, meist wandle es sich durch den langsamen Wandel von Werten und Normen. Was ist die am besten begründete Schlussfolgerung für den Artikel?","options":["Die Behauptung ist in beiden Teilen überzogen: Die Sechs-Stufen-Skala lässt sich Overton nicht als eigener Wortlaut zuschreiben, und dass Politiker das Fenster gezielt verschieben, ist eher die Ausnahme.","Die Behauptung bleibt im Kern richtig: Ob ein Konzept taugt, hängt nicht davon ab, wer es erfunden hat, und die Skala beschreibt das Phänomen auch dann brauchbar, wenn Lehman sie benannte.","Die Behauptung ist falsch, weil Overton nie etwas veröffentlicht hat: Wer zu einem Konzept keine Arbeit vorlegt, kann es nicht entwickelt haben, und die Skala stammt deshalb allein von Lehman.","Die Behauptung ist glaubwürdiger als Lehmans Darstellung, weil sie in vielen Texten so steht: Was breit wiederholt wird, trifft meist im Kern zu, und Lehman schildert nur eine Außenseitersicht."],"correctIndex":0,"explanation":"Die Quelle stammt von einem direkten Kollegen Overtons und beschreibt dessen Rolle nüchtern: Overton entwickelte das Konzept Mitte der 1990er-Jahre, Lehman benannte und formalisierte es erst nach Overtons Tod, und Overton hat dazu nie eine Arbeit veröffentlicht. Die beliebte Sechs-Stufen-Skala ist Overtons eigener Wortlaut nicht, sondern eine spätere, gebräuchliche Ausarbeitung; auch der Thinktank selbst zeigt das Fenster heute ohne diese Stufen. Beim zweiten Teil gilt: Politiker können das Fenster mitunter selbst verschieben, aber das ist selten; meist wandeln sich Werte und Normen langsam, und Lehman nennt als Hebel Thinktank-Forschung, Analyse und Debatte. Der Artikel schreibt Overton also die Skala als eigenes Werk zu und überschätzt die Rolle der Politiker. Die anderen Schlussfolgerungen greifen für sich bekannte Gedanken auf, tragen aber hier nicht: Ob ein Konzept taugt, ist eine andere Frage als die, wem es zuzuschreiben ist, und der Artikel behauptet eine Zuschreibung. Dass Overton nichts veröffentlicht hat, heißt nicht, dass er das Konzept nicht entwickelt hat, und Lehman sagt ausdrücklich das Gegenteil. Eine Darstellung wird nicht dadurch richtiger, dass sie oft wiederholt wird, während Lehman als Kollege Overtons aus erster Hand berichtet.","coreRule":"⚡ Prüfe bei einem bekannten Modell, wie viel davon vom Urheber stammt und wie viel später dazugekommen ist.","beleg":"Werkstück E.3.5 (Kontext & Tiefe); Fn. gl-e-overton (Lehman 2023, Mackinac Center)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Die Quelle stammt von einem Kollegen aus erster Hand und widerspricht dem Artikel in beiden Teilen: Die Skala ist eine spätere Ausarbeitung, und Politiker verschieben das Fenster nur selten. Weit verbreitet heißt nicht belegt.","prueffrage":"Wer hat laut Quelle wann was zum Konzept beigetragen, und wer verschiebt das Fenster nach Lehmans Darstellung meistens?","rueckmeldung":[{"option":1,"text":"Dass ein Konzept unabhängig von seinem Urheber taugen kann, stimmt. Der Artikel macht aber Aussagen über die Herkunft der Skala und die Rolle der Politiker, nicht über ihre Brauchbarkeit. Genau diese Aussagen stützt die Quelle nicht."},{"option":2,"text":"Daran stimmt: Die Sechs-Stufen-Skala stammt nicht von Overton selbst. Fehlende Veröffentlichungen heißen aber nicht, dass er nichts entwickelt hat; Lehman schreibt ihm das Konzept ausdrücklich zu und hat es nur benannt und formalisiert."},{"option":3,"text":"Häufig Wiederholtes wirkt vertraut und damit glaubwürdig. Wie oft etwas steht, sagt aber nichts darüber, ob es stimmt. Lehman arbeitete im selben Thinktank wie Overton und berichtet aus erster Hand, er ist also keine Außenseitersicht."}],"familie":"zitat-am-original-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Lehman, J. G. (2023): The legacy of the Overton Window. Mackinac Center for Public Policy, Blog, 30.06.2023","oeffentlich":true,"url":"https://www.mackinac.org/blog/2023/the-legacy-of-the-overton-window","abruf":"2026-10-12"},{"typ":"url","kurz":"Mackinac Center for Public Policy: The Overton Window","oeffentlich":true,"url":"https://www.mackinac.org/OvertonWindow","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0aca52ea3d4893dd"}},{"id":"qx-e-055","clusterId":"E","werkstueckRef":"E.3.6","stufe":1,"question":"Eine Freundin sagt: „Ich habe es genau gesehen, ich weiß, was passiert ist. Meine Augen haben doch einfach aufgezeichnet, was da war.“ Welche Antwort trifft die Lage am besten?","options":["Wahrnehmung ist eine Vermutung des Gehirns aus lückenhaften Sinnesdaten und Erwartungen, und im Dämmerlicht kann die Erwartung gewinnen.","Aufmerksamkeit bestimmt, was man bemerkt, und wer abgelenkt ist, übersieht Dinge; sie hat auf etwas anderes geachtet und den Busch nicht beachtet.","Andere beeinflussen, was wir zu sehen glauben (Suggestion), und vermutlich hat ihr jemand das Bild eines Mannes nahegelegt, bevor sie ihn sah.","Müdigkeit verschlechtert die Sehleistung, und wer abgespannt ist, nimmt Umrisse unscharf auf und sieht deshalb auch Dinge, die nicht da sind."],"correctIndex":0,"explanation":"Das Gehirn arbeitet als Vorhersagemaschine: Es erstellt ständig Modelle dessen, was es zu sehen erwartet, und die Sinnesdaten dienen vor allem dazu, diese Vorhersagen zu korrigieren. Sind die Daten mehrdeutig (Dämmerung, ein menschenähnlicher Umriss), gewinnt oft die Erwartung. Schon der blinde Fleck im Sehfeld zeigt, dass das Gehirn Lücken unbemerkt mit der Umgebung auffüllt. Das Gefühl von Klarheit sagt deshalb nichts darüber, ob die Wahrnehmung stimmt. Wahrnehmung ist keine passive Aufzeichnung, sondern eine „kontrollierte Halluzination“: eine beste Vermutung des Gehirns, die mit den Sinnesdaten abgeglichen wird. Die anderen Erklärungen nennen echte Einflüsse, passen aber nicht zur Lage: Wer abgelenkt ist, übersieht etwas, sie hat aber gerade etwas gesehen, nur das Falsche. Für eine Beeinflussung durch andere gibt es im Szenario keinen Anhaltspunkt. Müdigkeit wird nirgends erwähnt und erklärt auch nicht, warum gerade ein Mensch erkannt wurde.","coreRule":"⚡ Wir sehen nicht, was da ist, sondern die beste Vermutung unseres Gehirns darüber. Wie sicher sich eine Wahrnehmung anfühlt, sagt nichts darüber, ob sie stimmt.","beleg":"Werkstück E.3.6 (Kernidee; Kontext & Tiefe); Fn. gl-e-halluzination (Grush 2004, S. 393; Seth 2016)","status":"entwurf","scenario":"Beim Spaziergang im Dämmerlicht erschrickt jemand vor einem „Mann“ am Wegrand. Beim Näherkommen ist es ein Busch. Hinterher beharrt die Person darauf, sie habe die ganze Zeit klar einen Menschen gesehen.","kurz":"Das Gehirn rät aus lückenhaften Daten und füllt Lücken mit Erwartung. Im Dämmerlicht kann sie gewinnen. Der Denkfehler: Das Gefühl, klar gesehen zu haben, wirkt wie ein Beleg, sagt aber nichts darüber, ob das Gesehene stimmt.","prueffrage":"Was war im Dämmerlicht tatsächlich zu erkennen, bevor die Person näher kam?","rueckmeldung":[{"option":1,"text":"Aufmerksamkeit lenkt tatsächlich, was man bemerkt, und Abgelenkte übersehen oft etwas. Hier hat sie aber nichts übersehen, sondern etwas Falsches gesehen: einen Mann, wo ein Busch stand."},{"option":2,"text":"Suggestion beeinflusst Wahrnehmung und Erinnerung wirklich. Im Szenario deutet aber nichts darauf hin, dass ihr jemand das Bild eines Mannes nahegelegt hat; das wäre eine bloße Annahme."},{"option":3,"text":"Müdigkeit kann die Wahrnehmung beeinträchtigen. Sie wird im Szenario aber nirgends erwähnt und erklärt nicht, warum gerade ein Mensch erkannt wurde statt irgendeiner anderen Form."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Powers, A. R.; Kelley, M.; Corlett, P. R. (2016): Hallucinations as Top-Down Effects on Perception. Biological Psychiatry: CNNI 1(5) (Autorenmanuskript frei in PMC5469545)","oeffentlich":true,"doi":"10.1016/j.bpsc.2016.04.003"},{"typ":"url","kurz":"Seth, A. K. (2016): The real problem. Aeon, 2.11.2016","oeffentlich":true,"url":"https://aeon.co/essays/the-hard-problem-of-consciousness-is-a-distraction-from-the-real-one"},{"typ":"doi","kurz":"Grush, R. (2004): The emulation theory of representation. Behavioral and Brain Sciences 27(3)","oeffentlich":false,"doi":"10.1017/S0140525X04000093"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"958aa4be3e55322e"}},{"id":"qx-e-056","clusterId":"E","werkstueckRef":"E.3.6","stufe":2,"question":"Welche Schlussfolgerung ist am besten begründet?","options":["Ihre Beschwerden sind echt; die Einzelheiten der Entführung stammen vermutlich aus Suggestion und bekannten Bildern, mit denen das Gehirn Lücken füllte.","Ihre Beschwerden sind echt; die Einzelheiten der Entführung stammen vermutlich aus einer Psychose, die solche Erlebnisse als Wahn hervorbringt, und nicht aus Suggestion.","Ihre Beschwerden sind echt; mehrere unabhängige Hinweise, nämlich Hypnose, Schlafparalyse und Angst, deuten in dieselbe Richtung und stützen deshalb ein reales Ereignis.","Ihre Beschwerden sind echt; sie sind erst durch die erinnerte Entführung entstanden, und die Einzelheiten stammen deshalb aus einem tatsächlichen Erlebnis."],"correctIndex":0,"explanation":"Hier greifen drei Dinge ineinander: echte Symptome, ein realer, furchteinflößender Zustand (Schlafparalyse: wach sein, sich nicht bewegen können, oft mit Halluzinationen) und ein Rahmen, der falsche Erinnerungen begünstigt. Die Erwartung des Therapeuten, die Hypnose und die bekannten Bilder aus Filmen und Büchern liefern dem Gehirn das Material, um die unzusammenhängenden Sinnesfetzen zu einer stimmigen Geschichte zu verbinden. Das Gehirn ruft dann nicht eine Erinnerung ab, sondern erzeugt sie. Echte Symptome beweisen nicht, dass die berichtete Ursache stimmt: Angst und Schlaflosigkeit treten auch dann auf, wenn die Erinnerung konstruiert ist. Auch Lebhaftigkeit und Emotionalität sagen wenig über Wahrheit; starke Gefühle können Erinnerungen festigen, aber ebenso anfälliger für Verzerrung machen. Die Erinnerungen sind für die Betroffenen real und emotional echt, ohne dass die Ereignisse so geschehen sein müssen. In der Laborstudie von Clancy u. a. (2002) bildeten Menschen mit „wiedergefundenen“ Entführungserinnerungen im Gedächtnistest häufiger falsche Erinnerungen als eine Vergleichsgruppe. Die anderen Gedanken klingen für sich nachvollziehbar, passen aber nicht zum Fall: Für eine Psychose nennt der Fall keinerlei Anzeichen, dafür aber mehrere bekannte Alltagsursachen. Die Hinweise sind nicht unabhängig, denn Hypnose, Erwartung des Therapeuten und bekannte Bilder beeinflussen sich gegenseitig und führen nicht zu einem realen Ereignis. Und die Beschwerden bestanden schon, bevor die Einzelheiten in den Sitzungen auftauchten, können also nicht erst daraus entstanden sein.","coreRule":"⚡ Dass sich eine Erinnerung echt anfühlt, beweist nicht, dass sie echt ist.","beleg":"Werkstück E.3.6 (Einstieg: Das Zeugnis des Entführten); Fn. gl-e-clancy (Clancy u. a. 2002, S. 455–461; Clancy 2005)","status":"entwurf","scenario":"Eine Frau berichtet, sie sei nachts von kleinen grauen Wesen an Bord eines Raumschiffs gebracht und dort untersucht worden. Sie leidet unter echter Angst und Schlaflosigkeit, und die Erinnerung fühlt sich für sie sehr lebhaft und real an. Details fielen ihr erst in Sitzungen bei einem Therapeuten unter Hypnose ein, der zuvor gesagt hatte, genau solche Erlebnisse seien bei ihren Beschwerden häufig. In Filmen und Büchern kennt sie das Motiv schon lange. Außerdem erwacht sie manchmal nachts bei vollem Bewusstsein und kann sich minutenlang nicht bewegen.","kurz":"Die Beschwerden sind echt, doch die Einzelheiten stammen vermutlich aus Suggestion und bekannten Bildern, die das Gehirn zu einer stimmigen Geschichte fügte. Der naheliegende Fehler: Aus echter Angst und lebhafter Erinnerung auf ein reales Ereignis zu schließen.","prueffrage":"Wann und unter welchen Umständen sind die Einzelheiten der Erinnerung zum ersten Mal aufgetaucht?","rueckmeldung":[{"option":1,"text":"Dass die Entführung nicht real war, trifft vermutlich zu. Für eine Psychose nennt der Fall aber kein einziges Anzeichen, dafür mehrere bekannte Alltagsursachen. Und Suggestion lässt sich hier nicht ausschließen, denn die Details tauchten erst in den Hypnosesitzungen auf."},{"option":2,"text":"Mehrere Hinweise stärken eine Deutung nur, wenn sie unabhängig voneinander sind. Hypnose, Erwartung des Therapeuten und bekannte Bilder beeinflussen sich aber gegenseitig. Zusammen erklären sie eine konstruierte Erinnerung, nicht ein reales Ereignis."},{"option":3,"text":"Die Beschwerden bestanden laut Fall schon, bevor die Einzelheiten in den Sitzungen auftauchten, können also nicht erst daraus entstanden sein. Auch sonst gilt: Echte Angst und Schlaflosigkeit zeigen nicht, dass die berichtete Ursache stimmt."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Clancy, S. A.; McNally, R. J.; Schacter, D. L.; Lenzenweger, M. F.; Pitman, R. K. (2002): Memory distortion in people reporting abduction by aliens. Journal of Abnormal Psychology 111(3)","oeffentlich":false,"doi":"10.1037/0021-843X.111.3.455"},{"typ":"doi","kurz":"Bhalerao, V. u. a. (2024): Recent Insights Into Sleep Paralysis: Mechanisms and Management. Cureus 16(7), e65413","oeffentlich":true,"doi":"10.7759/cureus.65413"},{"typ":"doi","kurz":"Murphy, G. u. a. (2023): Lost in the mall again. Memory 31(6)","oeffentlich":true,"doi":"10.1080/09658211.2023.2198327"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"43c5f81f93dab3a0"}},{"id":"qx-e-057","clusterId":"E","werkstueckRef":"E.3.6","stufe":3,"question":"Wie ordnest du den Wert dieser Aussage ein?","options":["Sehr sichere Aussagen sind weniger treffsicher, wenn der Zeuge nach seiner Wahl bestätigt wird, weil seine Sicherheit dadurch erst wächst.","Sehr sichere Aussagen sind unter sauberen Umständen treffsicher, bei unfairen Gegenüberstellungen oder späterer Beeinflussung nicht.","Sehr sichere Aussagen sind weniger treffsicher, wenn der Zeuge dieselben Personen mehrfach sieht, weil frühere Eindrücke die Wahl färben.","Sehr sichere Aussagen sind weniger treffsicher, wenn der Zeuge seine Sicherheit erst Wochen später angibt, weil sie sich bis dahin verändert."],"correctIndex":1,"explanation":"Beides ist belegt: In den USA waren falsche Augenzeugen-Identifizierungen an rund zwei Dritteln der später per DNA-Test aufgehobenen Fehlurteile beteiligt (Innocence Project: 69 % von 375 Entlastungen). Das hat Reformen bei Gegenüberstellungen angestoßen. Unter sauberen Bedingungen, also bei erster, unbeeinflusster Gegenüberstellung und sofort festgehaltener Sicherheit, sind sehr sichere Identifizierungen laut Wixted und Wells (2017) aber bemerkenswert treffsicher. Unzuverlässig werden sie vor allem durch unfaire Gegenüberstellungen und spätere Beeinflussung. Der Verteidiger schließt von „das Gedächtnis ist formbar“ auf „jede Aussage ist wertlos“, doch aus einer Schwäche folgt nicht, dass sie unter allen Bedingungen gleich stark wirkt. Der Wert einer sicheren Aussage hängt von den Umständen ab, unter denen sie zustande kam. Dass die Sicherheit nach einer Bestätigung wächst, ist bekannt, doch hier wurde der Zeuge nicht beeinflusst und seine Sicherheit sofort festgehalten. Mehrfache Gegenüberstellungen können spätere Eindrücke verfälschen, hier aber war es die erste. Eine erst Wochen später erfragte Sicherheit wäre tatsächlich verzerrt, hier lag sie von Anfang an vor.","coreRule":"⚡ Nicht nur wie sicher ein Zeuge ist, sondern unter welchen Bedingungen er sich festgelegt hat, zählt.","beleg":"Werkstück E.3.6 (Anwendung & Relevanz: In der Justiz); Fn. gl-e-dna (Innocence Project, abgerufen 06.10.2026); Fn. gl-e-wixted (Wixted & Wells 2017, S. 10, 19, 39)","status":"entwurf","scenario":"Ein Zeuge ist sich seiner Identifizierung des Täters „hundertprozentig“ sicher. Er hat sich schon bei der ersten Gegenüberstellung festgelegt, kein Ermittler hat ihn dabei beeinflusst, und seine Sicherheit wurde sofort festgehalten. Der Verteidiger entgegnet: „Das Gedächtnis ist ohnehin konstruiert, also ist jede Zeugenaussage wertlos.“","kurz":"Die Sicherheit dieses Zeugen entstand unter sauberen Bedingungen und wurde sofort festgehalten, und dann sind sehr sichere Identifizierungen sehr treffsicher. Aus „das Gedächtnis ist formbar“ folgt nicht, dass jede Aussage unter allen Umständen wertlos ist.","prueffrage":"Unter welchen Umständen kam die Identifizierung zustande, und was spricht in diesem Fall für oder gegen Beeinflussung?","rueckmeldung":[{"option":0,"text":"Bestätigung nach der Wahl kann die Sicherheit tatsächlich aufblähen. Das Szenario nennt aber keine Bestätigung: Kein Ermittler hat den Zeugen beeinflusst, und seine Sicherheit wurde sofort festgehalten. Der Effekt trifft den Fall also nicht."},{"option":2,"text":"Wiederholte Begegnungen mit denselben Personen können spätere Eindrücke färben. Hier war es jedoch die erste Gegenüberstellung, an der sich der Zeuge festlegte. Eine solche Verfälschung hatte damit noch keine Gelegenheit."},{"option":3,"text":"Eine erst Wochen später erfragte Sicherheit wäre tatsächlich mit Vorsicht zu lesen. Hier lag die Sicherheit aber von Anfang an vor und wurde sofort festgehalten, sodass diese Verzerrung nicht greift."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Innocence Project: DNA Exonerations in the United States (1989–2020)","oeffentlich":true,"url":"https://innocenceproject.org/dna-exonerations-in-the-united-states/","abruf":"2026-10-06"},{"typ":"doi","kurz":"Wixted, J. T.; Wells, G. L. (2017): The Relationship Between Eyewitness Confidence and Identification Accuracy: A New Synthesis. Psychological Science in the Public Interest 18(1)","oeffentlich":false,"doi":"10.1177/1529100616686966"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"87e4f02982505fb9"}},{"id":"qx-e-058","clusterId":"E","werkstueckRef":"E.3.6","stufe":4,"question":"Du siehst in einem Video einen Mund, der „GA“ formt, hörst aber den Ton „BA“ und nimmst „DA“ wahr. Schließt du die Augen, hörst du klar „BA“. Eine Freundin schließt daraus: „Dann hört mein Gehirn eben immer genau das, was der Mund zeigt.“ Was folgt aus der Beobachtung wirklich?","options":["Das Gehirn verrechnet Bild und Ton zu einer gemeinsamen Wahrnehmung; die Täuschung fällt je nach Person und Video unterschiedlich stark aus, bei manchen bleibt sie ganz aus.","Das Gehirn füllt unklare Sinneseindrücke mit Vorwissen und Erwartung auf; das „DA“ ist deshalb die Silbe, die die Person am ehesten erwartet hat, und das gelingt manchen besser als anderen.","Bei widersprüchlichen Reizen setzt sich meist der Sehsinn durch; wahrgenommen wird deshalb die Silbe, die der Mund formt, und der Ton spielt kaum eine Rolle, je nach Video mehr oder weniger deutlich.","Die Aufmerksamkeit wählt einen Sinneskanal aus; wer auf den Ton achtet, hört deshalb „BA“, wer auf den Mund achtet, nimmt „GA“ wahr, und wie leicht das gelingt, ist von Person zu Person verschieden."],"correctIndex":0,"explanation":"Die Beobachtung enthält zwei Hinweise. Erstens: Wahrgenommen wird „DA“, obwohl weder das Bild („GA“) noch der Ton („BA“) diese Silbe liefert. Wäre es immer das Bild, würdest du „GA“ wahrnehmen, wäre es immer der Ton, „BA“. Das spricht dafür, dass das Gehirn beide Sinnesdaten zu einem Kompromiss verrechnet, statt einfach eine Quelle abzulesen. Zweitens: Bei geschlossenen Augen hörst du klar „BA“. Der Ton selbst hat sich also nicht verändert; das Bild hat die Wahrnehmung mitgeformt. Dazu kommt eine Einschränkung, die der Befund selbst liefert: In einer Studie mit 165 Erwachsenen lag die Täuschungsrate je Person zwischen 0 und 100 % und je Video zwischen 17 und 58 % (Basu Mallick u. a. 2015). Ein Effekt, der so stark streut, darf nicht als Naturgesetz für alle behandelt werden. Wer ihn ohne diese Einschränkung verallgemeinert, überzieht den Befund. Dass das Gehirn Lücken mit Erwartungen füllt, stimmt allgemein, doch hier war der Ton bei geschlossenen Augen klar, und das „DA“ liegt zwischen den beiden Reizen. Setzte sich meist der Sehsinn durch, würdest du „GA“ wahrnehmen, nicht „DA“. Wählte die Aufmerksamkeit nur einen Kanal aus, käme „BA“ oder „GA“ heraus, nicht eine dritte Silbe.","coreRule":"⚡ Wahrnehmung ist keine Aufzeichnung: Das Gehirn verrechnet mehrere Sinnesdaten zu einem Ergebnis, und wie stark das wirkt, unterscheidet sich von Mensch zu Mensch.","beleg":"Werkstück E.3.6 (Die Schmiede-Übung); Fn. gl-e-mcgurk (McGurk & MacDonald 1976; Basu Mallick u. a. 2015, S. 1299–1307)","status":"entwurf","scenario":"Ein Experiment zur Wahrnehmung: Bild und Ton passen absichtlich nicht zusammen. Viele Menschen nehmen dabei eine Silbe wahr, die weder im Bild noch im Ton vorkommt. Bei geschlossenen Augen verschwindet der Effekt. Wie stark die Täuschung ausfällt, ist von Person zu Person und von Video zu Video sehr verschieden; manche erleben sie nie.","kurz":"Weil „DA\\" weder im Bild noch im Ton steckt, liest das Gehirn nicht einfach eine Quelle ab, sondern verrechnet beide; mit geschlossenen Augen ist wieder „BA\\" zu hören. Der Fehler wäre, daraus ein Gesetz für alle zu machen: Der Effekt schwankt stark.","prueffrage":"Was würdest du hören, wenn nur eine der beiden Quellen die Wahrnehmung bestimmte, und was hörst du tatsächlich?","rueckmeldung":[{"option":1,"text":"Dass das Gehirn Lücken mit Erwartung füllt, gilt allgemein. Hier gab es aber keine Lücke: Bei geschlossenen Augen war der Ton klar „BA\\", und „DA\\" liegt zwischen beiden Reizen, statt aus einer Erwartung zu stammen."},{"option":2,"text":"Dass das Bild die Wahrnehmung mitformt, stimmt: Ohne es verschwindet der Effekt. Setzte sich aber der Sehsinn durch, hörtest du „GA\\". Das „DA\\" zeigt, dass auch der Ton in die Wahrnehmung eingeht."},{"option":3,"text":"Eine Auswahl nur eines Kanals ergäbe „BA\\" oder „GA\\", nie eine dritte Silbe. Dass die Täuschung von Person zu Person verschieden ist, stimmt, erklärt aber nicht, wie „DA\\" zustande kommt. Von Aufmerksamkeit ist im Szenario auch keine Rede."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Basu Mallick, D.; Magnotti, J. F.; Beauchamp, M. S. (2015): Variability and stability in the McGurk effect. Psychonomic Bulletin & Review 22(5) (frei in PMC4580505)","oeffentlich":true,"doi":"10.3758/s13423-015-0817-4"},{"typ":"doi","kurz":"McGurk, H.; MacDonald, J. (1976): Hearing Lips and Seeing Voices. Nature 264","oeffentlich":false,"doi":"10.1038/264746a0"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"0bf8d374710e73f4"}},{"id":"qx-e-059","clusterId":"E","werkstueckRef":"E.3.7","stufe":1,"question":"Welche Antwort auf die Behauptung ist am wirksamsten?","options":["Sie sagt: „Der Redner würde an der Wachtruppe selbst verdienen. Prüft seine Behauptungen deshalb besonders kritisch, bevor ihr ihm folgt.“","Sie erklärt: „Der Feind ist keine Bande, sondern unsere Unachtsamkeit. Lasst uns gemeinsam Nachbarschaftsrunden einrichten, Schlösser nachrüsten und aufeinander achten.“","Sie fragt: „Welche Belege gibt es für Banden von außerhalb? Wer etwas behauptet, muss es belegen, und bisher hat der Redner nichts vorgelegt.“","Sie entgegnet: „Es gibt nicht nur die Wahl zwischen seiner Wachtruppe und ungeschützten Häusern. Das ist ein falsches Dilemma, und darauf sollten wir nicht hereinfallen.“"],"correctIndex":1,"explanation":"Eine reine Widerlegung zerstört die Geschichte des Redners, lässt aber eine Leere zurück: Die Angst bleibt, und das Gehirn füllt die Lücke oft wieder mit der vertrauten Erklärung. Wirksamer ist eine wahre Alternative, die die Lücke schließt, das Bedürfnis nach Sicherheit ernst nimmt und den Menschen eine aktive Rolle gibt. Genau das leistet die Antwort mit den Nachbarschaftsrunden: Sie bleibt bei den Fakten, benennt eine bessere Erklärung und zeigt, was die Gemeinschaft selbst tun kann. Der Hinweis auf den Interessenkonflikt ist berechtigt, bietet den Zuhörenden aber keine Erklärung für die Einbrüche. Die Frage nach Belegen setzt die Beweislast richtig, gibt der Angst aber nichts, woran sie sich halten könnte. Auch das Benennen des falschen Dilemmas ist ein echtes Denkwerkzeug, zeigt aber keinen eigenen Weg.","coreRule":"⚡ Wer eine falsche Geschichte nur zerstört, lässt eine Lücke; fülle sie mit der wahren, die Handlungsmacht gibt.","quote":"Was ist die wahre, aber ebenso fesselnde und ermächtigende Geschichte, die ich an ihrer Stelle erzählen kann?","quoteLabel":"Denkfrage:","beleg":"Werkstück E.3.7 (Einstieg: Die Brandstifter und der Gärtner; Kernidee; Kontext & Tiefe; Härten im Feuer: Aktivierungs-Frage)","status":"entwurf","scenario":"In einer Kleinstadt häufen sich Einbrüche. Auf einer Bürgerversammlung behauptet ein Redner: „Das sind organisierte Banden von außerhalb! Nur wenn ihr mir folgt und meine Wachtruppe bezahlt, seid ihr sicher.“ Viele nicken, denn die Geschichte gibt ihrer Angst einen klaren Schuldigen. Die Polizeistatistik zeigt: Die meisten Einbrüche geschahen durch offene Fenster und unverschlossene Türen, die Täter waren überwiegend Gelegenheitstäter aus der Gegend. Eine Anwohnerin meldet sich zu Wort.","kurz":"Wer nur widerlegt, lässt die Angst ohne Antwort zurück, und die füllt sich oft wieder mit der alten Erklärung. Wirksamer ist eine wahre Alternative: Unachtsamkeit statt Banden, dazu Schritte, die die Nachbarn selbst tun können.","prueffrage":"Womit verlassen die Zuhörenden den Saal, wenn die Anwohnerin fertig ist, und was davon hilft ihnen gegen die Einbrüche?","rueckmeldung":[{"option":0,"text":"Der mögliche Interessenkonflikt ist ein berechtigter Hinweis. Er erklärt den Zuhörenden aber nicht, warum eingebrochen wird, und so bleibt ihre Angst ohne Antwort."},{"option":2,"text":"Die Beweislast liegt tatsächlich beim Redner, und die Nachfrage setzt sie richtig. Nur gibt sie der Angst nichts, woran sie sich halten könnte, und die Lücke steht weiter offen."},{"option":3,"text":"Das falsche Dilemma ist hier zutreffend benannt und ein echtes Denkwerkzeug. Es zeigt den Zuhörenden aber nur, was nicht stimmt, und keinen eigenen Weg, wie sie ihre Häuser schützen können."}],"familie":"luecke-fuellen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020","oeffentlich":true,"doi":"10.17910/b7.1182"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"35fe170dcbe30d79"}},{"id":"qx-e-060","clusterId":"E","werkstueckRef":"E.3.7","stufe":2,"question":"Dein Freund hält Kondensstreifen am Himmel für „Chemtrails“, mit denen heimlich etwas versprüht wird. Welche Reaktion hat die beste Aussicht, seine Meinung tatsächlich zu verändern?","options":["Ihm erklären, wie Kondensstreifen entstehen und warum sie je nach Luftfeuchtigkeit unterschiedlich lange am Himmel bleiben.","Ihn vor typischen Tricks von Verschwörungserzählungen warnen, damit er künftige Behauptungen dieser Art kritischer prüft.","Ihn auffordern, einen Beleg für das heimliche Versprühen zu nennen, und ihm sagen, dass die Beweislast bei ihm liegt.","Ihm sagen, dass fast alle Fachleute die Chemtrail-Behauptung ablehnen, und ihn bitten, dem Fachkonsens zu folgen."],"correctIndex":0,"explanation":"Wer nur widerspricht oder Fehler aufzählt, nimmt dem Freund eine Erklärung weg, ohne eine neue anzubieten. Gerade das Rätsel, das ihn beschäftigt (warum bleiben manche Streifen stundenlang, andere nicht?), bleibt dann offen, und das Gehirn füllt solche Lücken oft mit der alten, vertrauten Behauptung. Forschung zum Richtigstellen von Falschinformationen (Lewandowsky u. a., 2020) zeigt: Eine sachliche Alternativerklärung, die die Lücke schließt, wirkt besser als ein bloßes Dementi. Für Kondensstreifen liefert diese Alternativerklärung die Atmosphärenphysik. Dass ein Widerspruch den Irrtum sogar verstärkt, kommt zwar nur selten vor, doch auch ohne diesen Effekt bleibt das Dementi schwächer als die Erklärung. Die Warnung vor Tricks hilft, bevor jemand einer Behauptung begegnet, ändert aber kaum, was er schon glaubt. Die Beweislast ist ein gutes Prinzip, beantwortet aber nicht seine Frage nach den unterschiedlich langen Streifen. Der Verweis auf den Fachkonsens nennt ein Ergebnis, ohne zu erklären, wie es zustande kommt.","coreRule":"⚡ Wer eine Behauptung widerlegen will, braucht mehr als ein Nein: Eine bessere, nachprüfbare Erklärung füllt die Lücke, die sonst die alte Behauptung wieder füllt.","beleg":"Werkstück E.3.7 (Anwendung & Relevanz: Verschwörungsmythen; Red Flags; Kontext & Tiefe, Fn. gl-e-luecke: Lewandowsky u. a. 2020, Debunking Handbook; Backfire-Effekt selten)","status":"entwurf","scenario":"Du stehst mit einem Freund draußen, am Himmel ziehen sich weiße Streifen. Er sagt: „Siehst du? Die sprühen da was aus. Warum bleiben manche Streifen stundenlang und andere verschwinden sofort?“","kurz":"Er hat eine echte Frage, und die Antwort darauf schließt die Lücke: Die Physik erklärt, warum Streifen je nach Luftfeuchtigkeit unterschiedlich lange bleiben. Ein bloßes Dementi nimmt ihm die Erklärung weg und bietet keine neue an.","prueffrage":"Was genau hat dein Freund gefragt, als ihr die Streifen am Himmel gesehen habt?","rueckmeldung":[{"option":1,"text":"Eine Vorwarnung kann nützlich sein, bevor jemand einer Behauptung begegnet. Dein Freund glaubt sie aber schon, und die Warnung ändert daran kaum etwas. Seine Frage nach den unterschiedlich langen Streifen bleibt dabei unbeantwortet."},{"option":2,"text":"Dass die Beweislast bei dem liegt, der etwas behauptet, ist ein gutes Prinzip. Es beantwortet aber nicht, warum manche Streifen bleiben und andere verschwinden. Ohne Erklärung bleibt die Lücke, und die füllt er leicht mit seiner alten Deutung."},{"option":3,"text":"Der Fachkonsens ist tatsächlich eindeutig und ein wichtiger Hinweis. Er nennt aber nur ein Ergebnis und nicht, wie es zustande kommt. Auf die Frage deines Freundes gibt das keine Antwort, und die Bitte, einfach zu folgen, ersetzt keine Erklärung."}],"familie":"luecke-fuellen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020","oeffentlich":true,"doi":"10.17910/b7.1182"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"2141f18d6ada8d0c"}},{"id":"qx-e-061","clusterId":"E","werkstueckRef":"E.3.7","stufe":3,"question":"Was folgt aus diesem Befund für die Planung einer Richtigstellung?","options":["Die Erzählform bringt für sich genommen keinen Vorteil; entscheidend ist, wie gut die Richtigstellung die Lücke im Weltbild mit einer Erklärung füllt.","Richtigstellungen erreichen noch Unentschlossene leichter als Überzeugte; die Behörde sollte deshalb zuerst die Unentschlossenen ansprechen.","Ein einzelnes Studienergebnis reicht nicht für Konsequenzen; die Behörde sollte weitere Studien abwarten, bevor sie überhaupt eine Richtigstellung veröffentlicht.","Entscheidend ist vor allem, wer die Richtigstellung überbringt; eine Quelle, der die Zielgruppe vertraut, wirkt stärker als jede Darstellungsform."],"correctIndex":0,"explanation":"Aus dem Befund folgt: Wenn eine erzählte und eine sachliche Richtigstellung gleich viel erklären, wirken sie ähnlich gut. Der Mitarbeiter schließt also von „Geschichte“ auf „wirksamer“, ohne dass das belegt ist. Wirksam ist eine sachliche Alternativerklärung, die die entstandene Lücke füllt; ohne sie greift das Gehirn oft wieder zur vertrauten Falschinformation. Die Geschichtenform kann Aufmerksamkeit und Merkbarkeit unterstützen, ersetzt aber nie die erklärende Substanz. Dass Unentschlossene leichter zu erreichen sind, mag stimmen, sagt aber nichts über die Form der Richtigstellung. Vorsicht gegenüber einzelnen Studien ist grundsätzlich richtig, doch drei vorregistrierte Experimente mit über 2.000 Personen sind eine tragfähige Planungsgrundlage, und Abwarten lässt das Gerücht weiterwirken. Auch die Vertrauenswürdigkeit der Quelle spielt eine Rolle, der Befund vergleicht aber nur zwei Darstellungsformen.","coreRule":"⚡ Frage bei einer Richtigstellung zuerst, welche Erklärung die Lücke füllt, nicht, wie spannend sie erzählt ist.","beleg":"Werkstück E.3.7 (Kontext & Tiefe); Fn. gl-e-erzaehlform (Ecker, Butler, Hamby 2020, Abstract); Fn. gl-e-luecke (Lewandowsky u. a. 2020, PDF-S. 9 und 12)","status":"entwurf","scenario":"Eine Gesundheitsbehörde will ein hartnäckiges Gerücht über einen Impfstoff richtigstellen. Ein Mitarbeiter schlägt vor: „Wir packen die Richtigstellung in eine spannende Geschichte, dann wirkt sie von selbst besser als ein nüchterner Text.“ In drei vorregistrierten Experimenten mit zusammen 2.279 Teilnehmenden zeigte sich: Erzählte Richtigstellungen wirkten nicht besser als sachlich formulierte, sofern beide gleich viel erklärten.","kurz":"Wenn Erzählung und Sachtext gleich viel erklären, wirken sie ähnlich gut. Wirksam ist die Erklärung, die die Lücke im Weltbild füllt. Der naheliegende Fehler: von „spannende Geschichte“ auf „wirksamer“ zu schließen, obwohl die Form allein das nicht belegt.","prueffrage":"Was wurde in den drei Experimenten miteinander verglichen, und welcher Unterschied zeigte sich dabei?","rueckmeldung":[{"option":1,"text":"Dass Unentschlossene leichter zu erreichen sind, mag sein. Der Befund vergleicht aber nur zwei Darstellungsformen, nicht Zielgruppen, und lässt deshalb keinen Schluss darauf zu, wen die Behörde zuerst ansprechen sollte."},{"option":2,"text":"Vorsicht gegenüber einzelnen Studien ist grundsätzlich richtig. Hier liegen aber drei vorregistrierte Experimente mit über 2.000 Personen vor, und Abwarten lässt das Gerücht in der Zwischenzeit weiterwirken."},{"option":3,"text":"Die Glaubwürdigkeit des Überbringers spielt tatsächlich eine Rolle. Der Befund vergleicht aber nur zwei Darstellungsformen und sagt nichts über Quellen; dass sie „stärker als jede Form“ wirkt, ist damit nicht belegt."}],"familie":"luecke-fuellen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Ecker, U. K. H.; Butler, L. H.; Hamby, A. (2020): You don't have to tell a story! Cognitive Research: Principles and Implications 5, Art. 64","oeffentlich":true,"doi":"10.1186/s41235-020-00266-x"},{"typ":"doi","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020","oeffentlich":true,"doi":"10.17910/b7.1182"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9546701582c74b1d"}},{"id":"qx-e-062","clusterId":"E","werkstueckRef":"E.3.7","stufe":4,"question":"Du willst eine verbreitete Falschmeldung bekämpfen. Weil sachliche Richtigstellungen kaum durchdringen, überlegst du, eine mitreißende Heldengeschichte zu erfinden, die zwar nicht ganz stimmt, aber wirkt. Wie beurteilst du diesen Plan?","options":["Der Plan ist vertretbar: Der gute Zweck rechtfertigt das Mittel, solange die erfundene Geschichte besser wirkt als die Falschmeldung.","Der Plan ist ein Fehler: Wer eine Lüge mit einer anderen bekämpft, ersetzt das eine Problem durch ein neues und gibt die Wahrheitsverpflichtung auf.","Der Plan ist ratsam: Eine Gegengeschichte hat nur dann Wirkung, wenn sie frei erfunden und damit emotionaler ist als die Wahrheit.","Der Plan ist unbedenklich: Eine kurze, erfundene Geschichte schadet nicht, solange das Publikum sie nicht überprüft."],"correctIndex":1,"explanation":"Eine Gegenerzählung soll Menschen eine bessere Erklärung anbieten, die die entstandene Lücke füllt, und diese Erklärung muss auf der Wahrheit beruhen. Sie muss immer der Wahrheit und der intellektuellen Redlichkeit verpflichtet bleiben. Wer eine falsche, aber emotional ansprechende Geschichte konstruiert, um eine andere falsche Erzählung zu bekämpfen, überschreitet den Kipppunkt von der Nützlichkeit zur Gefahr: Er benutzt genau die Methode, die er bekämpfen wollte. Ein guter Zweck macht ein unredliches Mittel nicht gültig, denn ob eine Aussage stimmt, hängt nicht davon ab, wofür man sie einsetzt. Die bessere Lösung ist eine wahre Geschichte, die fesselt: mit einer klaren Erklärung, einer aktiven Rolle für die Zuhörenden und einer Erzählung, die mit den Fakten übereinstimmt.","coreRule":"⚡ Gegen Lügen hilft keine bessere Lüge – nur eine wahre Geschichte, die auch fesselt.","beleg":"Werkstück E.3.7 (Der Kipppunkt; Kontext & Tiefe: Komponenten)","status":"entwurf","scenario":"","kurz":"Eine Gegenerzählung soll die entstandene Lücke mit einer besseren Erklärung füllen, und die muss auf der Wahrheit beruhen. Wer eine Falschmeldung mit einer Erfindung bekämpft, benutzt genau die Methode, die er bekämpfen wollte.","prueffrage":"Worin unterscheidet sich die geplante Heldengeschichte von der Falschmeldung, die sie bekämpfen soll?","rueckmeldung":[{"option":0,"text":"Wirkung ist ein berechtigtes Anliegen. Ob eine Aussage stimmt, hängt aber nicht davon ab, wofür man sie einsetzt, und ein guter Zweck macht ein unredliches Mittel nicht gültig."},{"option":2,"text":"Eine Gegengeschichte braucht tatsächlich Anschaulichkeit und eine Erklärung, die die Lücke füllt. Dafür muss sie aber nicht erfunden sein: Auch eine wahre Geschichte kann fesseln, etwa mit klarer Erklärung und einer aktiven Rolle für die Zuhörenden."},{"option":3,"text":"Ob eine Aussage stimmt, hängt nicht davon ab, ob jemand sie nachprüft. Eine erfundene Geschichte bleibt unredlich, auch wenn sie unbemerkt bleibt, und sie wäre genau das Mittel, das man der Falschmeldung vorwirft."}],"familie":"luecke-fuellen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020","oeffentlich":true,"doi":"10.17910/b7.1182"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"88924737b6241ca3"}},{"id":"qx-e-063","clusterId":"E","werkstueckRef":"E.4.1","stufe":1,"question":"Was ist an dieser Schlussfolgerung fehlerhaft?","options":["Sie schließt aus der Nutzung einer Mechanik durch eine Gruppe, dass die Mechanik selbst den Hass hervorbringt; dieselbe Mechanik kann aber auch harmlose Inhalte tragen.","Sie verzerrt die Ansicht, Spielmechaniken seien harmlos, zu einer Karikatur und widerlegt dann nur diese Verzerrung, statt auf das eigentliche Argument einzugehen (Strohmann).","Sie beruft sich auf das Ansehen von Fachleuten für Radikalisierung, ohne Belege für den Einfluss von Punkten und Rängen zu nennen (Autoritätsargument).","Sie hält Punkte und Ränge für die Ursache, weil bisher niemand bewiesen hat, dass sie keine Ursache sind (Appell an die Unwissenheit)."],"correctIndex":0,"explanation":"Eine Mechanik ist ein Werkzeug, kein Inhalt. Punkte, Ränge und Gemeinschaft motivieren Menschen, egal wofür: In Lern- und Fitness-Apps fördern sie nützliche Gewohnheiten, in einer extremistischen Gruppe binden sie Mitglieder an eine hasserfüllte Ideologie. Der Fehler liegt nicht in der Mechanik, sondern darin, wofür sie eingesetzt wird. Wer von „wird dort benutzt“ auf „ist die Ursache“ schließt, verwechselt Mittel und Zweck. Richtig wäre die Frage, ob die Belohnung eine Gruppe bindet, die Menschen schrittweise an immer radikalere Inhalte gewöhnt, ohne dass sie es merken. Ein Strohmann setzt voraus, dass eine Gegenposition verzerrt wiedergegeben wird, davon ist hier nichts zu sehen. Ein Autoritätsargument bräuchte eine genannte Autorität, die im Szenario fehlt. Und mit fehlenden Gegenbeweisen argumentiert die Person nicht, sie behauptet eine Ursache, ohne sie zu belegen.","coreRule":"⚡ Eine Mechanik, die Menschen bindet, ist noch kein Beleg für schädliche Absichten: Entscheidend ist, wofür sie eingesetzt wird und wohin sie führt.","beleg":"Werkstück E.4.1 (Einstieg; Kernidee; Das Adaptive Talent)","status":"entwurf","scenario":"In einer Diskussion über Online-Radikalisierung sagt jemand: „Die Gruppe benutzt Punkte, Ränge und Belohnungen, um ihre Mitglieder zu binden. Also sind diese Spielmechaniken selbst der Grund für Hass und Gewalt. Wer solche Mechaniken einsetzt, verbreitet Extremismus.“ Dieselben Mechaniken stecken auch in Lern-Apps, Fitness-Apps und Videospielen.","kurz":"Dass eine Gruppe Punkte und Ränge nutzt, macht die Mechanik nicht zur Ursache des Hasses: Sie bindet Menschen, egal wofür. Der Fehler ist, „wird dort benutzt“ mit „ist der Grund“ zu verwechseln, also Mittel und Zweck.","prueffrage":"Wo kommen Punkte, Ränge und Belohnungen sonst noch vor, und was bewirken sie dort?","rueckmeldung":[{"option":1,"text":"Strohmann-Vorwürfe passen oft, wenn jemand eine Gegenseite überzeichnet. Hier aber widerlegt die Person keine verzerrte Gegenposition, sondern stellt eine eigene Behauptung auf. Das Problem liegt in dieser Behauptung selbst."},{"option":2,"text":"Es stimmt, dass für den Einfluss der Mechaniken keine Belege genannt werden. Doch die Person beruft sich auf keine Autorität oder Fachleute, sondern auf die bloße Beobachtung, dass die Gruppe sie nutzt. Der Fehler steckt im Schluss von dieser Nutzung auf die Ursache."},{"option":3,"text":"Das klingt nach einer Ursachenbehauptung ohne Gegenbeweis. Die Person sagt aber nicht, es sei noch nie widerlegt worden. Sie schließt vielmehr aus der Nutzung der Mechanik, ohne sie als Ursache zu belegen."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Schlegel, L. (2020): Jumanji Extremism? How games and gamification could facilitate radicalization processes. Journal for Deradicalization 23","oeffentlich":true,"url":"https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/359","seite":"PDF-S. 5, 13, 15","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Nocun, K.; Lamberty, P. (2020): Fake Facts. Wie Verschwörungstheorien unser Denken bestimmen. Quadriga","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"df4eba2239260ea1"}},{"id":"qx-e-064","clusterId":"E","werkstueckRef":"E.4.1","stufe":2,"question":"Was ist die sparsamste Erklärung dafür, dass der Nutzer beim nächsten Mal noch schärfer postet?","scenario":"In einem Forum bekommt ein Nutzer für einen besonders zugespitzten, „witzigen“ Beitrag hunderte Likes und neue Follower. Davor hatte er eher sachlich geschrieben und kaum Resonanz bekommen. Beim nächsten Mal wird er noch schärfer.","options":["Er fühlt sich von Kritikern unter seinem Beitrag angegriffen und verteidigt seine Position nun trotzig mit noch schärferen Worten.","Die Zustimmung wirkt wie Punkte: Für Zuspitzung gibt es Anerkennung, für Sachlichkeit nicht, also wiederholt er, was sich lohnt.","Er hat durch die vielen Likes erkannt, dass seine zugespitzte Haltung in der Sache stimmt, und will sie deshalb deutlicher vertreten.","Andere Mitglieder haben ihn gezielt angeleitet, immer extremere Beiträge zu schreiben, damit er in der Gruppe aufsteigt."],"correctIndex":1,"explanation":"Likes und neue Follower sind sofortiges, sichtbares Feedback. Verhalten, das belohnt wird, wird wiederholt und oft gesteigert. Das erklärt den Verlauf allein aus dem, was bekannt ist: sachlich gab es wenig Resonanz, zugespitzt gab es viel. Trotz als Reaktion auf Kritik ist ein bekanntes Muster, doch im Szenario ist nur von Zustimmung die Rede, nicht von Kritikern. Dass Likes etwas über die Richtigkeit seiner Haltung aussagen, wäre ein Trugschluss, denn Beliebtheit ist kein Wahrheitsbeleg. Eine gezielte Anleitung durch andere Mitglieder ist denkbar, wird aber nirgends angedeutet. Das heißt nicht, dass der Nutzer nichts meint; es heißt, dass sein Verhalten auch ohne Überzeugungswandel erklärbar ist.","coreRule":"⚡ Frag bei einer Community: Wofür gibt es hier Punkte – und wofür gibt es sie nicht? Wer die Belohnung kennt, versteht oft das Verhalten, ohne eine Gesinnung unterstellen zu müssen.","beleg":"Werkstück E.4.1 (Kontext & Tiefe (Die Analyse), Aufzählpunkt „Punkte & Sozialer Status“)","status":"entwurf","kurz":"Zuspitzung brachte Likes und Follower, Sachlichkeit kaum etwas, und belohntes Verhalten wird wiederholt und oft gesteigert. Der naheliegende Fehler ist, nach zusätzlichen Gründen wie Trotz, Überzeugung oder Anleitung zu suchen, die im Szenario nicht vorkommen.","prueffrage":"Was ist über den Nutzer tatsächlich bekannt, und was wird über ihn nur vermutet?","rueckmeldung":[{"option":0,"text":"Trotz auf Kritik gibt es durchaus, nur ist im Szenario von Kritikern keine Rede, sondern nur von Zustimmung. Diese Erklärung beruht auf einer Annahme, die nirgends auftaucht, während der Verlauf auch ohne sie verständlich ist."},{"option":2,"text":"Hunderte Likes zeigen Beliebtheit, aber keine Richtigkeit: Zustimmung ist kein Wahrheitsbeleg. Sein Verhalten lässt sich auch ohne Überzeugungswandel erklären, ob er meint, was er schreibt, bleibt offen."},{"option":3,"text":"Dass andere ihn gezielt anleiten, ist denkbar, wird aber nirgends angedeutet. Diese Erklärung braucht eine zusätzliche, unbelegte Annahme, obwohl der Verlauf ohne sie schon verständlich ist."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Brady, W. J.; McLoughlin, K.; Doan, T. N.; Crockett, M. J. (2021): How social learning amplifies moral outrage expression in online social networks. Science Advances 7(33)","oeffentlich":true,"doi":"10.1126/sciadv.abe5641","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lindström, B. u. a. (2021): A computational reward learning account of social media engagement. Nature Communications 12, 1311","oeffentlich":true,"doi":"10.1038/s41467-020-19607-x","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0015c34230f79b3f"}},{"id":"qx-e-065","clusterId":"E","werkstueckRef":"E.4.1","stufe":3,"question":"Wie lässt sich am besten beurteilen, ob eine Online-Gemeinschaft mit Punkten und Rängen schädlich ist?","options":["Wofür die Punkte vergeben werden und ob das Streben nach Rang in Belästigung, Hass oder Gewalt außerhalb des Forums mündet, denn daran zeigt sich der Schaden.","Wer das Forum betreibt und womit es sein Geld verdient, denn das Geschäftsmodell verrät, wessen Interessen das Forum in erster Linie dient.","Ob deine Freundin im Forum auffallend viel Zeit verbringt, denn eine sehr lange Nutzungsdauer deutet auf eine ungesunde Bindung hin.","Ob die Mitglieder mit dem Forum zufrieden sind, denn wer sich in einer Gemeinschaft wohlfühlt, ist dort in der Regel nicht gefährdet."],"correctIndex":0,"explanation":"Punkte, Ränge und Gemeinschaft sind an sich neutral: Dieselben Mechanismen motivieren in Lern- und Fitness-Apps und sind dort nützlich. Entscheidend ist, wofür sie eingesetzt werden. Warnzeichen sind, wenn Ansehen von Extremität oder Provokation abhängt, wenn es einen Pfad von harmloseren zu immer radikaleren Inhalten gibt oder wenn Kritik als Angriff von „Spielverderbern“ abgetan wird. Kritisch wird es, wenn der „Highscore“ in der Gruppe zu Belästigung, Hass oder Gewalt im echten Leben führt. Die Frage nach dem Betreiber ist ein gutes Werkzeug, um Interessen zu klären, sagt aber nichts darüber, was im Forum belohnt wird. Viel Zeit im Forum gibt es auch in harmlosen Gemeinschaften, sie sagt also nicht, wofür die Punkte stehen. Zufriedenheit ist hier kein Prüfstein, denn deine Freundin ist schon begeistert, und das gilt für schädliche wie für harmlose Gemeinschaften.","coreRule":"⚡ Nicht die Spielmechanik ist das Problem, sondern wofür sie eingesetzt wird.","beleg":"Werkstück E.4.1 (Der Kipppunkt; Das Adaptive Talent; Red Flags)","status":"entwurf","scenario":"Eine Freundin erzählt dir von einem Online-Forum, in dem man für gute Beiträge Punkte sammelt und in Ränge aufsteigt. Sie ist begeistert. Du fragst dich, ob das harmlos ist oder ob du sie warnen solltest.","quote":"","quoteLabel":"","kurz":"Punkte und Ränge sind an sich neutral, entscheidend ist, wofür sie vergeben werden. Schädlich wird es, wenn Rang in Belästigung, Hass oder Gewalt außerhalb des Forums mündet. Wer nur auf Form oder Begeisterung schaut, übersieht gerade das.","prueffrage":"Was postet deine Freundin dort konkret, und wie reagieren die anderen darauf?","rueckmeldung":[{"option":1,"text":"Zu wissen, wer das Forum betreibt und wie es sich finanziert, ist ein gutes Werkzeug, um Interessen zu klären. Es verrät aber nicht, was im Forum belohnt wird, und gerade das entscheidet über Schaden oder Nutzen."},{"option":2,"text":"Viel Zeit im Forum fällt auf und wirkt wie ein Alarmsignal. Lange Nutzung gibt es aber auch in harmlosen Gemeinschaften, etwa in Lern- und Fitness-Apps. Sie sagt daher nicht, wofür die Punkte stehen."},{"option":3,"text":"Zufriedene Mitglieder klingen nach einem guten Zeichen. Deine Freundin ist aber längst begeistert, und das trifft auf harmlose wie auf schädliche Gemeinschaften zu. Wohlbefinden unterscheidet die beiden also nicht."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Schlegel, L. (2020): Jumanji Extremism? How games and gamification could facilitate radicalization processes. Journal for Deradicalization 23","oeffentlich":true,"url":"https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/359","seite":"PDF-S. 5, 15","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Nocun, K.; Lamberty, P. (2020): Fake Facts. Wie Verschwörungstheorien unser Denken bestimmen. Quadriga","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f5fd98fba3c6ed8b"}},{"id":"qx-e-066","clusterId":"E","werkstueckRef":"E.4.1","stufe":4,"question":"Du liest die Schlagzeile: „Spiel macht Menschen immun gegen Fake News!“ Dahinter steckt eine Studie mit 196 Teilnehmenden einer Online-Plattform. Eine Gruppe spielte eine Viertelstunde lang ein Spiel, in dem man selbst Falschmeldungen verbreitet und dabei Manipulationstechniken kennenlernt, die Vergleichsgruppe spielte Tetris. Direkt danach bewerteten beide Gruppen erfundene Beiträge. Die Spielgruppe erkannte die Manipulationstechniken besser. Was darfst du aus diesem Ergebnis folgern?","options":["Der Effekt wurde nur direkt nach dem Spiel und an erfundenen Beiträgen gemessen; Dauer und Verhalten im Netz bleiben deshalb offen.","Der Schutz hält dauerhaft an, weil man Techniken, die man einmal selbst angewendet hat, nicht wieder vergisst und auch Wochen später noch erkennt.","Die Teilnehmenden teilen künftig weniger Falschmeldungen, weil wer eine Manipulationstechnik erkennt, im Alltag auch entsprechend handelt.","Der Effekt gilt für alle Internetnutzenden, weil eine Online-Plattform Menschen aus allen Gruppen erreicht und die Stichprobe damit ein Abbild ist."],"correctIndex":0,"explanation":"Die Spielgruppe schnitt direkt nach dem Spiel besser ab als die Tetris-Gruppe. Mehr trägt die Messung aber nicht: Es wurde nur unmittelbar nach dem Spiel gemessen, und zwar an erfundenen Beiträgen. Ob das Erkennen nach Wochen noch funktioniert und ob Menschen im echten Netz anders handeln, wurde nicht geprüft. Zudem stammen die 196 Personen aus einer Online-Plattform und sind nach Angabe der Autoren wohl nicht repräsentativ. Der Vergleich mit der Tetris-Gruppe spricht zugleich gegen einen reinen Zufallsbefund. Dass Gelerntes lange haftet, ist möglich, wurde hier aber nicht nachgemessen. Dass Erkennen und Handeln zusammenhängen, ist eine Annahme, die erst eine Verhaltensmessung belegen könnte. Und eine Online-Plattform erreicht zwar viele Menschen, ihre Nutzenden sind aber nicht automatisch ein Abbild aller.","coreRule":"⚡ Prüfe bei jeder Studienschlagzeile, was genau gemessen wurde und wann: Ein Effekt direkt nach der Intervention sagt nichts über Dauer oder Verhalten im Alltag.","beleg":"Werkstück E.4.1 (Verbindungen: Kognitive Immunisierung); Fn. gl-e-badnews (Basol, Roozenbeek, van der Linden 2020, S. 1–3 und 6)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Gemessen wurde nur direkt nach dem Spiel und an erfundenen Beiträgen; die Spielgruppe schnitt besser ab als die Tetris-Gruppe. Dauer und Verhalten im echten Netz blieben ungeprüft, und von „besser erkannt“ auf „immun“ zu schließen, ist der naheliegende Sprung.","prueffrage":"Wie sah die Aufgabe aus, an der der Erfolg des Spiels gemessen wurde, und wer hat sie bearbeitet?","rueckmeldung":[{"option":1,"text":"Dass Gelerntes lange haftet, ist möglich, nur wurde es hier nicht nachgemessen: Getestet wurde allein direkt nach dem Spiel. Aus einer Möglichkeit wird so eine Gewissheit, die die Daten nicht stützen."},{"option":2,"text":"Erkennen und Handeln können zusammenhängen, gemessen wurde aber nur das Bewerten erfundener Beiträge, nie das Teilen im echten Netz. Der Zusammenhang bleibt eine Annahme, bis eine Verhaltensmessung ihn belegt."},{"option":3,"text":"Eine Online-Plattform erreicht viele Menschen, doch ihre Nutzenden sind nicht automatisch ein Abbild aller. Die 196 Personen gelten laut den Autoren wohl nicht als repräsentativ, ein Effekt für alle ist damit nicht gedeckt."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Basol, M.; Roozenbeek, J.; van der Linden, S. (2020): Good News about Bad News: Gamified Inoculation Boosts Confidence and Cognitive Immunity Against Fake News. Journal of Cognition 3(1)","oeffentlich":true,"doi":"10.5334/joc.91"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"8aca53a4530219dd"}},{"id":"qx-e-067","clusterId":"E","werkstueckRef":"E.4.2","stufe":1,"question":"Welche Frage bringt am schnellsten ans Licht, womit sich dieses Angebot finanziert?","options":["Wie viele Nutzer hat die App schon, und wie schnell wächst sie?","Wer bezahlt dem Unternehmen Geld, und was bekommt er dafür?","Wie viel zahlen Nutzer für Zusatzfunktionen, und wie viele kaufen sie?","Wie hoch sind die Kosten für Personal und Technik, und wie steigen sie?"],"correctIndex":1,"explanation":"Ein Unternehmen mit hohen Kosten muss Einnahmen haben. Wenn die Nutzer nichts zahlen, muss das Geld von jemand anderem kommen. Beim bekanntesten Geschäftsmodell solcher Gratisdienste sind das Werbetreibende, die für die Aufmerksamkeit der Nutzer bezahlen. Für die Plattform sind dann nicht die Nutzer die Kunden, sondern ihre Aufmerksamkeit und ihr vorhersagbares Verhalten die Ware. Die Frage nach Zahlungsströmen deckt das Geschäftsmodell auf, und aus dem Geschäftsmodell folgt, worauf der Dienst ausgelegt ist: Das Design zielt auf maximale Verweildauer, denn gebundene Aufmerksamkeit wird an Werbetreibende verkauft. Die Frage nach Zusatzfunktionen läuft ins Leere, weil die App keine Bezahlfunktionen hat. Die Kosten für Personal und Technik zeigen den Geldbedarf, den du schon kennst, aber nicht, woher das Geld kommt. Nutzerzahlen und Wachstum sagen etwas über den Erfolg, nicht darüber, wer das Geld liefert.","coreRule":"⚡ Frag bei jedem Gratisdienst: Wer bezahlt hier – und was bekommt er dafür?","beleg":"Werkstück E.4.2 (Kernidee; Kontext & Tiefe: Das Geschäftsmodell; Du bist nicht der Kunde)","status":"entwurf","scenario":"Eine neue Video-App ist komplett kostenlos, ohne Abo und ohne Bezahlfunktionen. Trotzdem beschäftigt das Unternehmen Hunderte Angestellte und betreibt riesige Rechenzentren. Eine Freundin sagt: „Ist doch super, das kostet mich gar nichts.“ Du willst herausfinden, wie das Geschäftsmodell funktioniert.","kurz":"Wer hohe Kosten trägt, ohne dass die Nutzer zahlen, muss sein Geld von anderen bekommen, und die Frage nach dem Zahlenden deckt das auf. Der Denkfehler ist, „kostenlos“ für „ohne Einnahmen“ zu halten; oft bezahlen Werbetreibende für Aufmerksamkeit.","prueffrage":"Angenommen, die App hätte morgen doppelt so viele Nutzer: Hätte das Unternehmen dann mehr Geld, und von wem?","rueckmeldung":[{"option":0,"text":"Nutzerzahlen und Wachstum sagen, wie erfolgreich die App ist. Aus ihnen geht aber nicht hervor, wer dem Unternehmen Geld überweist, und genau das ist die Frage."},{"option":2,"text":"Zusatzkäufe sind bei vielen Gratisangeboten eine übliche Einnahmequelle. Das Szenario sagt aber ausdrücklich, dass diese App keine Bezahlfunktionen hat, die Frage geht hier also ins Leere."},{"option":3,"text":"Personal und Rechenzentren erklären, warum viel Geld nötig ist, und das zeigt schon das Szenario. Sie verraten aber nicht, woher das Geld kommt, und danach wird gefragt."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Montag, C.; Lachmann, B.; Herrlich, M.; Zweig, K. (2019): Addictive Features of Social Media/Messenger Platforms and Freemium Games against the Background of Psychological and Economic Theories. IJERPH 16(14), 2612","oeffentlich":true,"doi":"10.3390/ijerph16142612","abruf":"2026-10-12"},{"typ":"url","kurz":"Franck, G. (1999): The Economy of Attention. Telepolis, 7.12.1999","oeffentlich":true,"url":"https://archiv.telepolis.de/features/The-Economy-of-Attention-3444929.html"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"4a2c3b1c5edc1fb9"}},{"id":"qx-e-068","clusterId":"E","werkstueckRef":"E.4.2","stufe":2,"question":"Welche Gestaltung ist bei diesem Erfolgsmaßstab am wahrscheinlichsten, und warum?","scenario":"Eine kostenlose App finanziert sich ausschließlich über Werbung. Ihr Produktteam erhält eine einzige Kennzahl als Erfolgsmaßstab: die durchschnittliche Zeit, die Nutzer pro Tag in der App verbringen. Nun muss das Team entscheiden, wie der Feed gestaltet werden soll.","options":["Ein Feed, der immer weiterlädt, mit Aktualisieren per Wischgeste und roten Hinweispunkten, weil jede Unterbrechung des Scrollens Nutzungszeit kostet.","Ein Feed mit festem Ende nach 20 Beiträgen und einem Hinweis, dass alles Neue gesehen wurde, weil zufriedene Nutzer später wiederkommen.","Ein Feed, der nur auf ausdrückliche Suche Beiträge anzeigt, weil Nutzer dann genau das finden, was sie brauchen.","Ein Feed ohne Benachrichtigungen und ohne automatische Aktualisierung, weil weniger Reize den Nutzern mehr Ruhe verschaffen."],"correctIndex":0,"explanation":"Die App verdient ihr Geld mit Werbung: Ihre Dienste wirken kostenlos, doch die gesammelte Aufmerksamkeit der Nutzer ist die eigentliche Ware, die an Werbetreibende verkauft wird. Deshalb ist jede Design-Entscheidung darauf ausgerichtet, den Nutzer so lange wie möglich auf der Plattform zu halten. Wird Nutzungszeit zum einzigen Erfolgsmaßstab, passen genau die Mechanismen dazu, die das Aufhören erschweren: Feeds ohne Ende, Aktualisieren per Wischgeste und rote Hinweispunkte, die zur Rückkehr locken. Die anderen Gestaltungen mögen für Nutzer angenehmer sein, würden aber genau diese Kennzahl senken. Gratis bedeutet hier nicht, dass es nichts kostet: Bezahlt wird mit Aufmerksamkeit, und das Ziel der App ist nicht automatisch dein eigenes Ziel.","coreRule":"⚡ Wenn ein Dienst gratis ist, frag, was er misst: Die Kennzahl verrät, wofür das Design gebaut ist.","beleg":"Werkstück E.4.2 (Kontext & Tiefe: Das Geschäftsmodell, Das Ziel ist die Maximierung der Verweildauer; Red Flags). Fachbegriffe Infinite Scroll und Pull-to-Refresh bewusst durch Beschreibungen ersetzt.","status":"entwurf","kurz":"Wenn nur die Nutzungszeit zählt, passt alles, was das Aufhören erschwert: endloses Scrollen, Wischen zum Aktualisieren, rote Hinweispunkte. Angenehmere Feeds mit Ende oder mehr Ruhe senken diese Kennzahl, und von ihr lebt eine App, die Aufmerksamkeit verkauft.","prueffrage":"Wie würde sich die durchschnittliche Zeit pro Tag verändern, wenn der Feed nach einer festen Zahl von Beiträgen endet?","rueckmeldung":[{"option":1,"text":"Zufriedene Nutzer, die später wiederkommen, sind ein gutes Ziel. Gemessen wird hier aber die Zeit pro Tag, und ein Feed mit Ende nach 20 Beiträgen verkürzt sie, weil die Nutzung dann von selbst aufhört."},{"option":2,"text":"Wer gezielt sucht, findet schnell, was er braucht, und das ist für Nutzer angenehm. Danach ist die Sitzung aber meist zu Ende, die Nutzungszeit bleibt also kurz, und genau sie gilt als Erfolgsmaßstab."},{"option":3,"text":"Weniger Reize können den Nutzern mehr Ruhe verschaffen. Doch ohne Hinweise und automatische Aktualisierung fehlt, was zur Rückkehr lockt und das Aufhören erschwert, und die Nutzungszeit sinkt."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Montag, C.; Lachmann, B.; Herrlich, M.; Zweig, K. (2019): Addictive Features of Social Media/Messenger Platforms and Freemium Games against the Background of Psychological and Economic Theories. IJERPH 16(14), 2612","oeffentlich":true,"doi":"10.3390/ijerph16142612","abruf":"2026-10-12"},{"typ":"url","kurz":"Franck, G. (1999): The Economy of Attention. Telepolis, 7.12.1999","oeffentlich":true,"url":"https://archiv.telepolis.de/features/The-Economy-of-Attention-3444929.html"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"00e7b23a7a0009e5"}},{"id":"qx-e-069","clusterId":"E","werkstueckRef":"E.4.2","stufe":3,"question":"Eine Nutzerin wundert sich, warum sie kaum aufhören kann zu scrollen: Mal erscheint ein lustiges Video, mal eine langweilige Anzeige, mal etwas Spannendes – nie vorhersehbar. Welche Erklärung trifft den Mechanismus am besten?","options":["Ein neutraler Reiz wird immer wieder mit einem unbedingten Reiz gekoppelt, bis er allein die Reaktion auslöst.","Eine alte Angst wird durch starke positive Reize schrittweise überschrieben und ersetzt.","Die Nutzerin redet sich nachträglich ein, dass ihr das Scrollen guttut und sinnvoll war.","Gelegentliche, unvorhersehbare Belohnungen halten ein Verhalten stärker am Laufen als verlässliche."],"correctIndex":3,"explanation":"Entscheidend ist das Muster der Belohnung: Sie kommt unregelmäßig und lässt sich nicht vorhersagen. Genau darauf baut der Sog auf, denn jeder weitere Wisch könnte der Treffer sein, und jede kleine Belohnung nährt den Drang, weiterzurollen. Fachlich spricht man von operanter Konditionierung mit variablen Belohnungen; Plattformen können dieses Prinzip nutzen, um Menschen möglichst lange zu halten. Die anderen Erklärungen passen nicht zur Situation: Hier wird kein neutraler Reiz an einen Auslöser gekoppelt, keine Angst abgebaut und keine nachträgliche Rechtfertigung beschrieben.","coreRule":"⚡ Unvorhersehbare Belohnungen sind der Haken, an dem das Weiterscrollen hängt.","beleg":"Werkstück E.4.2 (Einstieg: Der Daumen des Sisyphos; Verbindungen; Schmiede-Übung)","status":"entwurf","kurz":"Weil jeder Wisch der Treffer sein könnte, hält die Unvorhersehbarkeit das Scrollen am Laufen: Gelegentliche, unregelmäßige Belohnungen binden stärker als verlässliche. Kommt die Belohnung verlässlich, fehlt dieser Reiz des Ungewissen.","prueffrage":"Was tut die Nutzerin jeweils selbst, und was folgt unmittelbar darauf?","rueckmeldung":[{"option":0,"text":"Lernen durch Verknüpfung gibt es, etwa wenn ein Ton allein schon Erwartung weckt. Hier wird aber kein neutraler Reiz an einen Auslöser gekoppelt; es geht um ein Verhalten, das unregelmäßiger Lohn am Laufen hält."},{"option":1,"text":"Eine Angst, die überschrieben wird, kommt hier nirgends vor: Die Nutzerin wundert sich über ihren Drang weiterzuscrollen, von einer Furcht, die abgebaut würde, ist keine Rede."},{"option":2,"text":"Nachträgliches Schönreden eigenen Verhaltens kommt im Alltag durchaus vor. Beschrieben wird aber, dass sie sich über ihren Drang wundert, nicht, dass sie ihn schönredet. Der Sog entsteht, bevor irgendeine Rechtfertigung nötig ist."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Montag, C.; Lachmann, B.; Herrlich, M.; Zweig, K. (2019): Addictive Features of Social Media/Messenger Platforms and Freemium Games against the Background of Psychological and Economic Theories. IJERPH 16(14), 2612","oeffentlich":true,"doi":"10.3390/ijerph16142612","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lindström, B. u. a. (2021): A computational reward learning account of social media engagement. Nature Communications 12, 1311","oeffentlich":true,"doi":"10.1038/s41467-020-19607-x","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c200e7956df23c89"}},{"id":"qx-e-070","clusterId":"E","werkstueckRef":"E.4.3","stufe":2,"question":"Welche Erklärung für die Veränderung ihres Feeds ist am sparsamsten?","scenario":"Ein Mitarbeiter einer Plattform erklärt: „Unser Empfehlungssystem versteht keine Inhalte. Es misst nur, wie lange Nutzer bleiben und ob sie klicken, kommentieren oder teilen, und zeigt mehr von dem, was diese Werte erhöht.“ Eine Nutzerin hat bisher meist Yoga-Videos geliked. Dann teilt sie zum ersten Mal einen politischen Beitrag mit einem empörten Kommentar. Danach sieht sie in ihrem Feed deutlich mehr empörende politische Beiträge.","options":["Ihr empörter Kommentar hat mehr Engagement erzeugt als ihre Yoga-Likes, also zeigt das System ihr mehr davon.","Das System hat aus ihrem Alter und Wohnort abgeleitet, was zu ihr passt, und zeigt ihr deshalb Inhalte aus dieser Gruppe.","Sie hat in den Einstellungen politische Themen als Interesse eingetragen, deshalb zeigt das System ihr nun mehr davon.","Das System hat ihre politische Haltung erkannt und spielt ihr passende Beiträge zu, um sie auf eine Seite zu ziehen."],"correctIndex":0,"explanation":"Ein System, das nur Klicks, Kommentare, Shares und Verweildauer misst, braucht keine Absicht und kein Verständnis von Inhalten, um sein Verhalten zu ändern. Ihre Wut erzeugt viel mehr Engagement als ihre sanfte Zuneigung für Yoga, also lernt das System, ihr mehr davon zu zeigen. Die einfachste Erklärung braucht keine zusätzliche Annahme. Daraus folgt aber nicht, dass sie automatisch radikalisiert wird: Wie stark solche Feeds Einstellungen tatsächlich verändern, ist empirisch umstritten. Alter und Wohnort können Systeme durchaus nutzen, laut Beschreibung misst dieses aber nur Engagement. Dass sie politische Interessen eingetragen hätte, steht nirgends und müsste zusätzlich angenommen werden. Eine Absicht, sie umzustimmen, setzt ein Verständnis von Haltungen voraus, das das System nach der Beschreibung nicht hat.","coreRule":"⚡ Erkläre Verhalten mit der einfachsten Annahme, die zu den Daten passt: Ein System, das nur Engagement misst, folgt dem Engagement, nicht der Wahrheit oder einem Plan.","beleg":"Werkstück E.4.3 (Einstieg: Der unsichtbare Gott in der Maschine; Kontext & Tiefe: Der Mechanismus)","status":"entwurf","kurz":"Ein System, das nur Klicks, Kommentare und Verweildauer misst, braucht weder Absicht noch Inhaltsverständnis: Ihre Empörung erzeugt schlicht mehr Engagement als Yoga. Daraus folgt aber nicht, dass sie dadurch radikalisiert wird.","prueffrage":"Welche Signale kann das System laut Beschreibung überhaupt sehen, und was davon hat sich bei ihr nach dem Teilen verändert?","rueckmeldung":[{"option":1,"text":"Alter und Wohnort können Systeme tatsächlich nutzen, nach der Beschreibung misst dieses aber nur Engagement. Zudem blieben beide gleich, der Feed änderte sich aber erst nach dem geteilten Beitrag."},{"option":2,"text":"Ein eingetragenes Interesse würde die Veränderung erklären, davon steht im Szenario aber nichts, es wäre eine zusätzliche Annahme. Die einfachere Erklärung liegt im geteilten Beitrag selbst."},{"option":3,"text":"Eine Absicht, sie umzustimmen, setzt ein Verständnis von Haltungen voraus, das dieses System laut Beschreibung nicht hat. Dass solche Feeds Einstellungen verändern können, ist umstritten, aber hier gar nicht nötig, um den Feed zu erklären."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Rathje, S.; Van Bavel, J. J.; van der Linden, S. (2021): Out-group animosity drives engagement on social media. PNAS 118(26)","oeffentlich":true,"doi":"10.1073/pnas.2024292118"},{"typ":"doi","kurz":"Gauthier, G.; Hodler, R.; Widmer, P.; Zhuravskaya, E. (2026): The political effects of X's feed algorithm. Nature 652(8109)","oeffentlich":true,"doi":"10.1038/s41586-026-10098-2"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"51abc31fe1ad8494"}},{"id":"qx-e-071","clusterId":"E","werkstueckRef":"E.4.3","stufe":3,"question":"Eine Auswertung von rund 2,7 Millionen Beiträgen von Medienkonten und Abgeordneten zeigte, dass Posts über die politische Gegenseite etwa doppelt so oft geteilt wurden wie Posts über die eigene Seite. Was darfst du daraus schließen?","options":["Dass gewöhnliche Nutzer Beiträge über die Gegenseite bevorzugt teilen, weil sie sich damit von ihr abgrenzen wollen.","Dass Beiträge dieser Konten über die Gegenseite öfter geteilt wurden als solche über die eigene Seite.","Dass Plattform-Algorithmen Beiträge über die Gegenseite bevorzugt ausspielen und dadurch die Spaltung vertiefen.","Dass Empörung der Grund ist, warum Beiträge über die Gegenseite öfter geteilt wurden als andere."],"correctIndex":1,"explanation":"Die Auswertung zeigt nur, dass Beiträge dieser Konten über die Gegenseite häufiger geteilt wurden als solche über die eigene Seite. Untersucht wurden Beiträge von Medienkonten und Abgeordneten: Was gewöhnliche Nutzer selbst teilen und aus welchen Motiven, bleibt offen. Ob Feed-Algorithmen Haltungen verändern, zeigen erst Experimente mit gezielt veränderten Feeds; die größten fanden keine messbare Polarisierung durch den Feed-Algorithmus, ein kleineres eine geringe, kurzfristige Wirkung. Über die Ursache des häufigeren Teilens sagt die beschriebene Auswertung nichts; in der Studie selbst sagten Wörter über die andere Gruppe das Teilen rund 4,8-mal so stark voraus wie negative Gefühlswörter allgemein, negative Gefühle allein erklären es also nicht.","coreRule":"⚡ Frag bei einer Studie nicht nur, was sie zeigt, sondern auch, wen sie untersucht hat und was ihr Design überhaupt beweisen kann.","beleg":"Werkstück E.4.3 (Kontext & Tiefe: Die emotionale Asymmetrie); Fn. gl-e-empoerung (Rathje, Van Bavel, van der Linden 2021, PNAS 118(26))","status":"entwurf","kurz":"Gemessen wurde nur, was diese Konten posteten und wie oft es geteilt wurde: Beiträge über die Gegenseite öfter als über die eigene Seite. Wer daraus Motive, Algorithmen oder Ursachen liest, geht über die Daten hinaus.","prueffrage":"Von wem stammten die ausgewerteten Beiträge, und was genau wurde an ihnen gezählt?","rueckmeldung":[{"option":0,"text":"Abgrenzung als Motiv klingt plausibel. Untersucht wurden aber nur Beiträge von Medienkonten und Abgeordneten; was gewöhnliche Nutzer teilen und warum, zeigt die Auswertung nicht."},{"option":2,"text":"Die Auswertung misst, was geteilt wurde, nicht, was Algorithmen ausspielen. Ob Feeds Haltungen verändern, prüfen erst Experimente mit veränderten Feeds; sie fanden keine oder nur eine geringe, kurzfristige Wirkung."},{"option":3,"text":"Empörung kann mitspielen, doch die Auswertung sagt über die Ursache nichts. In der Studie sagten Wörter über die andere Gruppe das Teilen fast fünfmal stärker voraus als negative Gefühlswörter allgemein. Gefühle allein erklären es nicht."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Rathje, S.; Van Bavel, J. J.; van der Linden, S. (2021): Out-group animosity drives engagement on social media. PNAS 118(26)","oeffentlich":true,"doi":"10.1073/pnas.2024292118"},{"typ":"doi","kurz":"Guess, A. M. u. a. (2023): How Do Social Media Feed Algorithms Affect Attitudes and Behavior in an Election Campaign? Science 381(6656)","oeffentlich":false,"doi":"10.1126/science.abp9364"},{"typ":"doi","kurz":"Piccardi, T. u. a. (2025): Reranking partisan animosity in algorithmic social media feeds alters affective polarization. Science 390(6776)","oeffentlich":false,"doi":"10.1126/science.adu5584"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"6c48b76c64edc6e1"}},{"id":"qx-e-072","clusterId":"E","werkstueckRef":"E.4.3","stufe":4,"question":"Ein Beitrag behauptet: „Der Empfehlungs-Algorithmus einer Videoplattform führt Nutzer Schritt für Schritt in den Extremismus – ganz ohne dass sie es wollen.“ Wie sicher darfst du dieser Behauptung glauben, wenn du die Datenlage kennst?","options":["Die Behauptung ist offen: Befunde zu Feed-Algorithmen lassen sich nicht auf die Empfehlungen einer einzelnen Videoplattform übertragen, die Datenlage sagt dazu also nichts.","Die Behauptung ist durch das kleinere Experiment gestützt: Umsortierte Feeds verschoben Haltungen, und genau diesen Mechanismus beschreibt der Beitrag.","Die Behauptung ist als Bild eingängig, aber in den Felddaten schwächer belegt: Ein Verstärker-Effekt ist möglich, der erste Schritt war oft eine eigene Entscheidung.","Die Behauptung ist glaubwürdig: Dass sie sich so schnell verbreitet, zeigt, dass viele Nutzer das Muster aus eigener Erfahrung kennen und bestätigen."],"correctIndex":2,"explanation":"Eine eingängige Geschichte ist noch kein Beleg. Die Daten sprechen gegen die starke Version der Behauptung: Wer extremistische Kanäle nutzt, kommt meist über Abonnements und Links dorthin, und große Feldexperimente fanden keine messbare Polarisierung durch den Feed-Algorithmus. Auch ein siebenwöchiges Experiment auf X fand keine Wirkung auf Polarisierung. Ganz widerlegt ist die Behauptung damit nicht: Ein kleineres Experiment mit umsortierten X-Feeds zeigte eine leichte, kurzfristige Verschiebung der Haltung zur Gegenpartei, ob sie anhält, ist offen. Die vorsichtigste, belegbare Einordnung lautet daher: Ein Verstärker ist plausibel, aber der erste Schritt ist meist eine eigene Entscheidung. Die anderen Gedanken klingen vernünftig, passen aber nicht: Dass sich Befunde nicht beliebig übertragen lassen, stimmt, doch der erste Befund betrifft genau die Frage, wie Nutzer zu extremistischen Kanälen kommen. Das kleinere Experiment untersuchte die Haltung zur Gegenpartei über zehn Tage, nicht den Weg in den Extremismus. Und weite Verbreitung zeigt nur, dass das Bild eingängig ist, nicht, dass es stimmt.","coreRule":"⚡ Ein eingängiges Bild ist kein Beleg: Prüfe die Daten, bevor du eine Behauptung glaubst – und halte dein Urteil so stark wie die Belege, nicht stärker.","beleg":"Werkstück E.4.3 (Kontext & Tiefe: Der Kaninchenbau-Effekt, Hinweis zur Beleglage); Fn. gl-e-kaninchenbau (Chen u. a. 2023; Hosseinmardi u. a. 2021; Guess u. a. 2023; Piccardi u. a. 2025)","status":"entwurf","scenario":"Der Beitrag verbreitet sich schnell, weil das Bild vom „Kaninchenbau“ so eingängig ist. Du kennst folgende Befunde: Nutzer extremistischer Kanäle kamen laut Auswertungen großer Datensätze überwiegend über Abonnements und externe Links dorthin, nicht über Empfehlungen. Große Feldexperimente mit umgestellten Feed-Algorithmen (2023) fanden keine messbare Polarisierung. Ein kleineres Experiment mit gezielt umsortierten Feeds (2025, zehn Tage) zeigte eine leichte, kurzfristige Veränderung der Haltung zur Gegenpartei.","kurz":"Eine eingängige Geschichte ist noch kein Beleg: Meist führt der erste Schritt über Abonnements oder Links, große Feldexperimente fanden keine Polarisierung. Ein Verstärker bleibt plausibel, aber „ganz ohne eigenes Wollen“ trägt die Datenlage nicht.","prueffrage":"Auf welchem Weg sind Nutzer extremistischer Kanäle laut den Daten überhaupt dorthin gekommen?","rueckmeldung":[{"option":0,"text":"Befunde zu einem Feed lassen sich tatsächlich nicht einfach auf eine andere Plattform übertragen. Zu sagen hat die Datenlage trotzdem etwas: Dass Nutzer meist über Abonnements und Links zu extremistischen Kanälen kamen, betrifft genau die behauptete Wirkung."},{"option":1,"text":"Das kleinere Experiment zeigte eine Verschiebung, aber nur leicht, über zehn Tage und bei der Haltung zur Gegenpartei. Einen Weg in den Extremismus hat es nicht gemessen, und ob die Wirkung anhält, ist offen. Das trägt „gestützt“ nicht."},{"option":3,"text":"Ein Bild, das viele wiedererkennen, verbreitet sich schnell, und das macht es überzeugend. Es zeigt aber nur, dass die Geschichte eingängig ist. Ob der Algorithmus die Ursache ist, entscheiden Daten, nicht die Zahl der Zustimmenden."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Chen, A. Y.; Nyhan, B.; Reifler, J.; Robertson, R. E.; Wilson, C. (2023): Subscriptions and External Links Help Drive Resentful Users to Alternative and Extremist YouTube Channels. Science Advances 9(35)","oeffentlich":true,"doi":"10.1126/sciadv.add8080"},{"typ":"doi","kurz":"Gauthier, G.; Hodler, R.; Widmer, P.; Zhuravskaya, E. (2026): The political effects of X's feed algorithm. Nature 652(8109)","oeffentlich":true,"doi":"10.1038/s41586-026-10098-2"},{"typ":"doi","kurz":"Piccardi, T. u. a. (2025): Reranking partisan animosity in algorithmic social media feeds alters affective polarization. Science 390(6776)","oeffentlich":false,"doi":"10.1126/science.adu5584"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c33a85217d18cdea"}},{"id":"qx-e-073","clusterId":"E","werkstueckRef":"E.4.3","stufe":4,"question":"Du liest: „Eine Studie mit Twitter-Daten zeigt, dass Falschnachrichten sich weiter verbreiten als wahre. Der Algorithmus der Plattform ist also schuld.“ Wo liegt der Denkfehler, und was müsstest du dafür wissen?","options":["Der Schluss ist voreilig: Die Studie zeigt, dass Menschen Falsches häufiger teilten; zur Rolle des Algorithmus sagt sie nichts.","Der Schluss ist voreilig: Du müsstest zuerst wissen, ob Bots Falsches stärker beschleunigt haben als Wahres; erst dann ließe sich über den Algorithmus urteilen.","Der Schluss ist unzulässig verallgemeinert: Die Studie stützt sich auf zu wenige Geschichten, um etwas über die Verbreitung auf einer ganzen Plattform zu sagen.","Der Schluss überträgt Ergebnisse einer Plattform auf alle anderen: Aus Twitter-Daten lässt sich nicht ableiten, wie sich Nachrichten in anderen Netzwerken verbreiten."],"correctIndex":0,"explanation":"Ein Unterschied in der Verbreitung zeigt noch nicht, wodurch er entsteht. In der Auswertung von rund 126.000 Geschichten (Vosoughi, Roy, Aral 2018) teilten Menschen Falsches häufiger als Wahres, während Bots beide Sorten gleichermaßen beschleunigten. Ob Feed-Algorithmen mitwirkten, wurde nicht untersucht; dazu sagt die Studie also nichts. Wer „der Algorithmus ist schuld“ behauptet, schließt von einem gemessenen Effekt auf eine Ursache, die gar nicht geprüft wurde. Ein plausibler Mechanismus (Plattformen leben von Aufmerksamkeit) ersetzt keinen Beleg. Die Technik kann ein Verstärker sein, getragen wird die Verbreitung laut der Studie aber von Menschen. Die anderen Einwände sind für sich sinnvoll, treffen hier aber nicht: Bots beschleunigten Wahres und Falsches gleichermaßen und erklären den Unterschied daher nicht. Mit rund 126.000 Geschichten ist die Datenbasis nicht zu klein. Und der Beitrag schließt nur auf den Algorithmus der untersuchten Plattform, nicht auf andere Netzwerke.","coreRule":"⚡ Ein gemessener Effekt beweist keine Ursache, die nicht untersucht wurde: Frage immer, was die Studie tatsächlich geprüft hat.","beleg":"Werkstück E.4.3 (Anwendung & Relevanz: Bei Verschwörungsmythen & Desinformation); Fn. gl-e-vosoughi (Vosoughi, Roy, Aral 2018, Science 359(6380), S. 1146–1151)","status":"entwurf","scenario":"Eine Studie wertete rund 126.000 Geschichten auf Twitter aus und stellte fest: Falsche Nachrichten verbreiteten sich weiter als wahre. Beim Auswerten zeigte sich, dass Menschen Falsches häufiger teilten und dass Bots wahre und falsche Nachrichten gleichermaßen beschleunigten. Ob die Feed-Algorithmen der Plattform etwas dazu beitrugen, war nicht Gegenstand der Untersuchung.","quote":"","quoteLabel":"","kurz":"Dass sich Falsches weiter verbreitete, ist gemessen; was es antrieb, zeigt das nicht. Laut Studie teilten Menschen Falsches häufiger, den Algorithmus untersuchte sie nicht. Der Fehler: von einem Effekt auf eine ungeprüfte Ursache zu schließen.","prueffrage":"Welche möglichen Ursachen hat die Studie tatsächlich untersucht, und welche kommt in den Befunden gar nicht vor?","rueckmeldung":[{"option":1,"text":"Bots sind ein naheliegender Verdächtiger, doch laut Studie beschleunigten sie Wahres und Falsches gleichermaßen. Sie können den Unterschied also nicht erklären, und Bot-Daten würden auch nichts über einen nie untersuchten Algorithmus sagen."},{"option":2,"text":"Bei einer Verallgemeinerung lohnt der Blick auf die Datenmenge. Rund 126.000 Geschichten sind hier aber eine breite Basis. Das Problem liegt woanders: Der Schluss auf den Algorithmus wurde gar nicht untersucht."},{"option":3,"text":"Vorsicht beim Übertragen auf andere Plattformen ist grundsätzlich berechtigt, trifft aber diesen Beitrag nicht: Er behauptet nur etwas über den Algorithmus der untersuchten Plattform. Auch dafür liefert die Studie jedoch keinen Beleg."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"MIT News (Dizikes, P., 8.3.2018): Study: On Twitter, false news travels faster than true stories","oeffentlich":true,"url":"https://news.mit.edu/2018/study-twitter-false-news-travels-faster-true-stories-0308","abruf":"2026-10-12"},{"typ":"doi","kurz":"Vosoughi, S.; Roy, D.; Aral, S. (2018): The spread of true and false news online. Science 359(6380)","oeffentlich":false,"doi":"10.1126/science.aap9559"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1db782f4139a5e4a"}},{"id":"qx-e-074","clusterId":"E","werkstueckRef":"E.4.3","stufe":1,"question":"Du liest die Behauptung: „Die Plattform zeigt Nutzern absichtlich Wut-Posts, also muss jemand das so geplant haben.“ Was spricht gegen diesen Schluss?","options":["Ein einfaches Optimierungsziel kann ein Verhalten hervorbringen, das niemand eigens geplant hat; dass Wut im Feed auftaucht, setzt keine Absicht eines Menschen voraus.","Der Schluss setzt Bevorzugung voraus, doch dass Wut-Posts häufig im Feed stehen, belegt nicht, dass das System sie bevorzugt; beides muss getrennt belegt werden.","Ob ein Schluss auf Absicht trägt, hängt davon ab, wer ihn aufstellt; erst wenn die Interessen des Urhebers bekannt sind, lässt sich die Behauptung beurteilen.","Der Schluss ist zu pauschal, denn nicht jeder Beitrag im Feed hat mit Wut zu tun; über die übrigen Inhalte sagt das Beispiel nichts und kann daher nichts belegen."],"correctIndex":0,"explanation":"Aus dem Verhalten eines Systems lässt sich nicht auf die Absicht seiner Entwickler schließen. Ein selbstlernender Algorithmus, der nur Aufmerksamkeit maximiert, findet von allein heraus, dass empörende Inhalte besonders viele Reaktionen auslösen. Solche Eigenschaften, die aus dem Zusammenspiel von Ziel und Nutzerverhalten entstehen, ohne dass jemand sie angelegt hat, heißen emergent. Gleichzeitig ist das Ergebnis kein Zufall, denn es folgt zuverlässig aus dem Ziel, Aufmerksamkeit zu maximieren. Die Frage „Wer wollte das?“ führt hier in die Irre; besser fragt man: „Welches Ziel wird optimiert, und was belohnt es?“ Die anderen Einwände klingen sinnvoll, treffen den Kern aber nicht: Dass Wut-Posts häufiger gezeigt werden, beschreibt das Szenario schon als Folge der Klicks, Häufigkeit und Bevorzugung fallen hier also zusammen. Wer die Behauptung aufstellt, ändert nichts daran, dass von der Wirkung nicht auf eine Absicht zu schließen ist. Und dass nicht alle Inhalte Wut sind, berührt nicht die Frage, ob jemand die Wut-Posts geplant hat.","coreRule":"⚡ Ein Ergebnis ist nicht automatisch geplant: Prüfe das Optimierungsziel, bevor du nach einem Schuldigen mit Absicht suchst.","beleg":"Werkstück E.4.3 (Kontext & Tiefe: Emergente Eigenschaft; Der Mechanismus)","status":"entwurf","scenario":"Ein Empfehlungsalgorithmus lernt selbstständig aus dem Verhalten der Nutzer. Sein einziges Ziel: Verweildauer und Interaktionen steigern. Er „weiß“ nicht, was Wut oder Wahrheit ist, sondern nur, welche Inhalte zu mehr Klicks, Kommentaren und Shares führen. Empörende Beiträge lösen davon besonders viele aus, und so tauchen sie immer häufiger in den Feeds auf.","kurz":"Ein System, das nur Aufmerksamkeit maximieren soll, kann Wut-Posts von selbst nach vorn bringen, ohne dass jemand sie geplant hat. Der Fehler liegt darin, aus dem Ergebnis auf einen Plan zu schließen; das Ergebnis folgt aus dem Ziel.","prueffrage":"Was genau wurde dem Algorithmus als Ziel vorgegeben, und woher weiß er, welche Beiträge er öfter zeigen soll?","rueckmeldung":[{"option":1,"text":"Getrennt zu belegen wäre das im Allgemeinen. Hier steht die Bevorzugung aber schon im Szenario: Wut-Posts lösen viele Reaktionen aus und werden deshalb häufiger gezeigt. Der Fehler liegt im Sprung von dieser Wirkung auf einen menschlichen Plan."},{"option":2,"text":"Die Interessen eines Urhebers können Misstrauen wecken. Ob der Schluss von der Wirkung auf eine Absicht trägt, hängt aber nicht davon ab, wer ihn äußert, sondern davon, was die Beobachtung hergibt. Und das ist hier keine Absicht."},{"option":3,"text":"Natürlich besteht nicht jeder Beitrag aus Wut. Die Behauptung betrifft aber nur die Wut-Posts, und ob andere Inhalte im Feed stehen, ändert nichts an der Frage, ob jemand diese Wut-Posts geplant hat."}],"familie":"anreize-durchschauen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Rathje, S.; Van Bavel, J. J.; van der Linden, S. (2021): Out-group animosity drives engagement on social media. PNAS 118(26)","oeffentlich":true,"doi":"10.1073/pnas.2024292118"},{"typ":"doi","kurz":"Brady, W. J.; McLoughlin, K.; Doan, T. N.; Crockett, M. J. (2021): How social learning amplifies moral outrage expression in online social networks. Science Advances 7(33)","oeffentlich":true,"doi":"10.1126/sciadv.abe5641","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"726f21b27c86dbea"}},{"id":"qx-e-075","clusterId":"E","werkstueckRef":"E.4.4","stufe":1,"question":"Was ist hier das eigentliche Problem – und was prüfst du als Erstes?","options":["Das Material ist echt, aber sein Zusammenhang ist falsch. Du suchst zuerst die Originalquelle und die vollständige Aufnahme der Rede.","Das Material ist nachträglich vertont, der Ton gehört also nicht zum Bild. Du prüfst zuerst, ob Lippenbewegung und Ton zusammenpassen.","Das Material ist echt, aber seine rasante Verbreitung wirkt gesteuert. Du prüfst zuerst, ob Bots oder gekaufte Konten das Video verbreiten.","Das Material ist echt, aber es wurde wohl ohne Erlaubnis der Stadträtin verbreitet. Du prüfst zuerst, wer die Rechte an der Aufnahme besitzt."],"correctIndex":0,"explanation":"Ob eine Aufnahme echt ist und ob sie das zeigt, was behauptet wird, sind zwei getrennte Fragen. Hier ist das Material echt, aber der Kontext falsch: Der Satz stammt aus einer Rede über ein ganz anderes Thema und wurde mit einer neuen Überschrift versehen. Solche einfachen Manipulationen mit echtem Material sind viel leichter herzustellen als KI-Fälschungen und deshalb häufiger. Im Bild findet sich nichts Gefälschtes. Wer nur nach Bildfehlern sucht, übersieht sie. Wirksam ist die Frage nach der Herkunft: Wo stammt die Aufnahme ursprünglich her, wann wurde sie gemacht, und was kam davor und danach? Die Suche nach der Originalquelle und der vollständigen Aufnahme klärt das am schnellsten. Die anderen Wege sind in anderen Fällen sinnvoll, passen hier aber nicht: Dass Ton und Bild nicht zusammengehören, hat der Faktencheck ausgeschlossen. Auch eine gesteuerte Verbreitung erklärt nicht, warum der Satz irreführt, denn das liegt im fehlenden Zusammenhang. Wem die Rechte an der Aufnahme gehören, ist eine andere Frage als die, ob das Video die Wahrheit zeigt.","coreRule":"⚡ Echtes Material kann täuschen: Prüfe nicht nur, ob ein Bild echt ist, sondern ob es das zeigt, was behauptet wird.","beleg":"Werkstück E.4.4 (Kernidee, Absatz zu „Cheap Fakes“)","status":"entwurf","scenario":"Ein Video zeigt eine Stadträtin bei einer Rede, in der sie scheinbar sagt: „Das ist mir alles egal.“ Es verbreitet sich rasant. Ein Faktencheck stellt fest: Bild und Ton sind echt und nicht per KI erzeugt. Das Video stammt aus einer Rede von vor drei Jahren, in der sie über ein ganz anderes Thema sprach; der Satz ist aus einem längeren Zusammenhang herausgeschnitten und mit einer neuen Überschrift versehen.","kurz":"Echt ist die Aufnahme, falsch ist der Zusammenhang: Der Satz stammt aus einer Rede über ein anderes Thema. Wer nur nach Bildfehlern sucht, findet nichts; erst die Frage nach Herkunft, Datum und Vorher/Nachher bringt es an den Tag.","prueffrage":"Was hat der Faktencheck über Bild und Ton herausgefunden, und was über die Überschrift?","rueckmeldung":[{"option":1,"text":"Nachträgliche Vertonung kommt als Fälschungsmuster tatsächlich vor. Hier hat der Faktencheck aber Bild und Ton als echt bestätigt, ein Lippenabgleich bliebe also ohne Befund und sagt nichts über den herausgeschnittenen Satz."},{"option":2,"text":"Eine rasante Verbreitung weckt leicht den Verdacht auf Steuerung, und manchmal stimmt er. Selbst wenn Bots mitmischen, erklärt das aber nicht, warum der Satz irreführt: Dafür ist der fehlende Zusammenhang entscheidend."},{"option":3,"text":"Wem die Rechte an einer Aufnahme gehören, ist eine reale Frage, aber eine andere. Sie klärt nicht, ob das Video zeigt, was es behauptet. Genau daran scheitert dieses Video: Der Satz steht außerhalb seines Zusammenhangs."}],"familie":"bild-und-video-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Brennen, J. S.; Simon, F.; Howard, P. N.; Nielsen, R. K. (2020): Types, Sources, and Claims of COVID-19 Misinformation. Reuters Institute Factsheet","oeffentlich":true,"doi":"10.60625/risj-awvq-sr55"},{"typ":"url","kurz":"Dufour, N. u. a. (2024): AMMeBa: A Large-Scale Survey and Dataset of Media-Based Misinformation In-The-Wild. arXiv:2405.11697v2 (Preprint)","oeffentlich":true,"url":"https://arxiv.org/abs/2405.11697"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"d6e68dad246c301c"}},{"id":"qx-e-076","clusterId":"E","werkstueckRef":"E.4.4","stufe":2,"question":"Du siehst ein Video, in dem ein Politiker etwas Schockierendes sagt. Dein Puls rast, und du willst es sofort teilen. Was ist der klügste erste Schritt?","options":["Warten, bis sich der Puls beruhigt hat, und das Video dann teilen, weil Entscheidungen im Ruhezustand verlässlicher ausfallen als im Affekt.","Das Video als bloße Behauptung behandeln, nichts teilen und nach Originalquelle und unabhängiger Bestätigung suchen, weil die Quelle mehr Sicherheit gibt.","Auf Blinzeln, Hautglätte und Lippensynchronität achten und erst bei Auffälligem zweifeln, weil sich viele Fälschungen daran verraten.","Nachsehen, wie viele Menschen das Video schon gesehen haben, und bei großer Reichweite teilen, weil viele Zuschauer eine Fälschung eher bemerken würden."],"correctIndex":1,"explanation":"Dein rasender Puls ist selbst ein Warnsignal: Genau auf solche Gefühle zielen Fälschungen. Ein aufrührerisches Video ist zunächst nur eine Behauptung, kein Beweis. Der Blick aufs Bild trägt wenig: In Experimenten erkannten Menschen Deepfakes kaum besser als der Zufall, hielten Fälschungen eher für echt als umgekehrt und überschätzten ihre Trefferquote. Typische Merkmale wie Blinzeln oder wachsartige Haut verschwinden zudem mit besserer Technik. Auch mit Fragezeichen geteilt, erreicht das Video viele Menschen; das spätere Dementi erreicht nur einen Bruchteil, und selbst ein Fälschungshinweis nimmt der Wirkung nur einen Teil. Mehr Sicherheit gibt die Frage nach der Originalquelle und ob unabhängige, seriöse Stellen das Video bestätigen. Die anderen Wege klingen vernünftig, klären aber nicht, ob das Video echt ist: Abwarten beruhigt zwar den Puls, prüft aber nichts. Eine große Reichweite sagt nichts über Echtheit, denn viele Betrachter erkennen Fälschungen ebenso schlecht wie du.","coreRule":"⚡ Je stärker ein Video auf dich wirkt, desto wichtiger ist die Frage nach seiner Quelle.","beleg":"Werkstück E.4.4 (Das Anti-Denkmuster: Aktivierungs-Fragen 1 und 2; Red Flags)","status":"entwurf","scenario":"","kurz":"Ein aufrührerisches Video ist zunächst nur eine Behauptung, und den Blick aufs Bild überschätzt man: Fälschungen erkennt man kaum besser als per Zufall. Verlässlicher ist die Frage, woher es stammt und ob unabhängige Stellen es bestätigen.","prueffrage":"Was genau macht dich gerade so sicher, dass der Politiker das wirklich gesagt hat?","rueckmeldung":[{"option":0,"text":"Ein ruhigerer Kopf hilft zwar, und der rasende Puls ist tatsächlich ein Warnsignal. Das Video ist danach aber genauso ungeprüft wie vorher; zu klären, ob es echt ist, bleibt aus."},{"option":2,"text":"Auf Fehler im Bild zu achten wirkt gründlich, ist aber unzuverlässig: Menschen erkennen Deepfakes kaum besser als der Zufall, und gute Fälschungen zeigen Blinzel- oder Hautfehler gar nicht mehr. Ein unauffälliges Bild beweist nichts."},{"option":3,"text":"Viele Aufrufe wirken wie ein Echtheitssiegel, denn so viele Augen müssten doch etwas merken. Doch Betrachter erkennen Fälschungen ebenso schlecht wie du, und Empörendes verbreitet sich gerade schnell. Reichweite sagt über Echtheit nichts."}],"familie":"bild-und-video-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Diel, A. u. a. (2024): Human Performance in Detecting Deepfakes: A Systematic Review and Meta-Analysis of 56 Papers. Computers in Human Behavior Reports 16","oeffentlich":true,"doi":"10.1016/j.chbr.2024.100538"},{"typ":"doi","kurz":"Köbis, N. C.; Doležalová, B.; Soraperra, I. (2021): Fooled Twice: People Cannot Detect Deepfakes but Think They Can. iScience 24(11)","oeffentlich":true,"doi":"10.1016/j.isci.2021.103364"},{"typ":"doi","kurz":"Clark, S.; Lewandowsky, S. (2026): The Continued Influence of AI-Generated Deepfake Videos Despite Transparency Warnings. Communications Psychology 4, 13","oeffentlich":true,"doi":"10.1038/s44271-025-00381-9"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"2b8f82bbd5d110d1"}},{"id":"qx-e-077","clusterId":"E","werkstueckRef":"E.4.4","stufe":3,"question":"Ein Kollege folgert: „Dann prüfe ich eben jedes verdächtige Video genau und vertraue danach meinem Eindruck.“ Welche Schlussfolgerung ist angemessen?","options":["Die schwache Erkennung liegt vermutlich an zu geringer Anstrengung; wer sich bemüht und genau hinsieht, darf seinem Eindruck deshalb weitgehend trauen.","Bei unbekannten Personen kann der Augenschein allein eine Fälschung nicht sicher verraten; sicherer ist es, die Herkunft des Videos zu prüfen.","Da die Erkennung kaum über dem Zufall lag, ist jedes Video gleich verdächtig; auch eine Prüfung der Herkunft kann daher keine Sicherheit bringen.","Einzelne irren sich zwar oft, in der Gruppe gleichen sich solche Fehler aber aus; Videos sollten deshalb im Team beurteilt werden, bis die Mehrheit zustimmt."],"correctIndex":1,"explanation":"Eine Metaanalyse von 56 Arbeiten (Diel u. a. 2024) ergab eine Trefferquote von 55,5 %, also kaum über dem Zufall. Im Versuch mit 210 Teilnehmenden (Köbis u. a. 2021) wurden Fälschungen eher für echt gehalten als umgekehrt, und die Teilnehmenden überschätzten ihre Trefferquote. Wenn weder ein Warntext noch eine Prämie für richtige Antworten die Erkennung verbessern, ist das Gefühl „sieht echt aus“ keine brauchbare Prüfung, und das Selbstvertrauen taugt nicht als Gütesiegel. Wer das Urteil auf die Herkunft stützt (Originalquelle, unabhängige Bestätigung), umgeht die Schwäche des Augenscheins. Ein Training mit Rückmeldung verbesserte die Erkennung in den meisten Experimenten, bloße Hinweise auf typische Fehler brachten gemischte Ergebnisse. Die anderen Gedanken klingen vernünftig, passen aber nicht zu den Befunden: Mangelnde Anstrengung erklärt sie nicht, denn auch die bezahlte Gruppe schnitt nicht besser ab. Liegen schon die Einzelurteile kaum über dem Zufall, werden sie in der Gruppe nicht zu einem verlässlichen Urteil. Und aus der schwachen Erkennung folgt nicht, dass sich nichts mehr beurteilen lässt, denn die Herkunft lässt sich prüfen.","coreRule":"⚡ Dein Gefühl für „echt“ trügt – verlass dich auf Quellenprüfung statt auf Augenschein.","beleg":"Werkstück E.4.4 (Red Flags); Fn. gl-e-erkennung (Köbis u. a. 2021; Diel u. a. 2024, S. 7); Fn. gl-e-deepfake (Diel u. a. 2024, 55,5 %)","status":"entwurf","scenario":"Ein Forschungsteam zeigte 210 Online-Teilnehmenden 16 kurze Videos unbekannter Personen; die Hälfte war gefälscht. Bei den meisten Clips lag die Erkennung nicht verlässlich über dem Zufall. Wer vorab einen Text über die Gefahren von Deepfakes las oder für richtige Antworten bezahlt wurde, schnitt nicht besser ab als die übrigen. Die Selbsteinschätzung lag deutlich über der tatsächlichen Trefferquote.","kurz":"Wenn weder Warntext noch Bezahlung die Erkennung verbessern, taugt das Gefühl „sieht echt aus“ nicht als Prüfung. Der Fehler wäre, dem eigenen Eindruck zu trauen, nur weil man genau hingesehen hat. Verlässlicher ist, die Herkunft zu prüfen.","prueffrage":"Wie gut lagen die Teilnehmenden tatsächlich, und wie gut glaubten sie selbst zu liegen?","rueckmeldung":[{"option":0,"text":"Mehr Mühe liegt als Erklärung nahe. Im Versuch schnitt aber auch die Gruppe nicht besser ab, die für richtige Antworten bezahlt wurde. Gründliches Hinsehen allein macht den Eindruck also nicht verlässlich."},{"option":2,"text":"Dass der Augenschein hier wenig taugt, stimmt. Daraus folgt aber nicht, dass sich nichts mehr beurteilen lässt: Die Schwäche betrifft das Hinsehen, nicht die Herkunft, und die lässt sich nachprüfen."},{"option":3,"text":"Das Zusammenlegen mehrerer Urteile hilft, wenn die Einzelurteile im Schnitt stimmen und nur zufällig streuen. Hier liegen schon sie kaum über dem Zufall, und Fälschungen wurden eher für echt gehalten. Eine Mehrheit macht daraus kein verlässliches Urteil."}],"familie":"bild-und-video-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Diel, A. u. a. (2024): Human Performance in Detecting Deepfakes: A Systematic Review and Meta-Analysis of 56 Papers. Computers in Human Behavior Reports 16","oeffentlich":true,"doi":"10.1016/j.chbr.2024.100538"},{"typ":"doi","kurz":"Köbis, N. C.; Doležalová, B.; Soraperra, I. (2021): Fooled Twice: People Cannot Detect Deepfakes but Think They Can. iScience 24(11)","oeffentlich":true,"doi":"10.1016/j.isci.2021.103364"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"2d7e4e0e95b2c05d"}},{"id":"qx-e-078","clusterId":"E","werkstueckRef":"E.4.4","stufe":4,"question":"Welche Prüffrage trifft die Schwachstelle der Behauptung am besten?","options":["Wie groß ist der Anteil von KI-Bildern unter allen gezählten Bildfälschungen insgesamt?","Wie stark hat die Zahl der KI-Bilder in sozialen Netzwerken in den letzten Jahren zugenommen?","Wie viele Menschen halten KI-Bilder inzwischen für die häufigste Art der Fälschung?","Wie oft wurden die KI-Bilder, die dem Verfasser aufgefallen sind, in sozialen Netzwerken geteilt?"],"correctIndex":0,"explanation":"Die Behauptung betrifft einen Anteil, und dafür braucht es eine systematische Zählung aller Bildfälschungen; auffällige Einzelfälle reichen nicht, denn spektakuläre KI-Bilder bleiben besser im Gedächtnis als unscheinbare Fälschungen. Die vorhandenen Zählungen sprechen gegen die Behauptung: In 225 englischsprachigen Covid-19-Falschmeldungen (Januar bis März 2020) fand sich kein einziger Deepfake, alle manipulierten Bilder und Videos waren mit einfachen Mitteln bearbeitet (Brennen u. a. 2020). Auch in englischsprachigen Faktenchecks bis November 2023 überwogen einfache Mittel, vor allem echte Bilder in falschem Zusammenhang, obwohl KI-Bilder ab Frühjahr 2023 rasch zunahmen (Dufour u. a. 2024, Preprint). Wie es seither steht, ist offen. Die anderen Fragen klingen interessant, klären den Anteil aber nicht: Dass KI-Bilder zunehmen, sagt nichts darüber, ob andere Fälschungen noch häufiger sind. Was Menschen glauben, ist kein Beleg für die tatsächliche Verteilung. Und wie oft einzelne Bilder geteilt wurden, misst Reichweite, nicht den Anteil unter allen Fälschungen.","coreRule":"⚡ Auffälligkeit ist keine Häufigkeit: Wer „die meisten“ behauptet, braucht eine Zählung, keinen Eindruck.","beleg":"Werkstück E.4.4 (Werkbank-Frage); Fn. gl-e-haeufiger (Brennen u. a. 2020, Factsheet S. 4; Dufour u. a. 2024, Preprint); Anm. anm-gl-e-haeufiger","status":"entwurf","scenario":"Du liest einen Artikel über Desinformation. Er behauptet, die meisten Bildfälschungen im Netz seien heute KI-erzeugt. Als einzigen Beleg führt der Verfasser an, dass ihm in letzter Zeit auffällig viele KI-Bilder in sozialen Netzwerken begegnet sind.","quote":"","quoteLabel":"","kurz":"Eine Behauptung über einen Anteil braucht eine Zählung aller Fälschungen, nicht den Eindruck einzelner Funde. Spektakuläre KI-Bilder bleiben im Gedächtnis haften, unscheinbare Fälschungen fallen kaum auf und werden leicht unterschätzt.","prueffrage":"Worauf stützt sich der Verfasser, und in welchem Ausschnitt des Netzes hat er seine Beobachtungen gemacht?","rueckmeldung":[{"option":1,"text":"Dass KI-Bilder zunehmen, kann stimmen und klingt nach einem Beleg. Über den Anteil sagt es aber nichts: Andere Fälschungen können trotzdem weiter häufiger sein, und genau dieser Vergleich fehlt."},{"option":2,"text":"Eine verbreitete Überzeugung wirkt wie ein Hinweis auf die Lage. Sie zeigt aber nur, was Menschen glauben, und nicht, wie sich die Fälschungen tatsächlich verteilen. Das lässt sich nur durch Zählen klären."},{"option":3,"text":"Die Reichweite einzelner Bilder ist interessant, bleibt aber bei genau den Einzelfällen stehen, die dem Verfasser aufgefallen sind. Wie oft Bilder geteilt wurden, misst Verbreitung, nicht den Anteil unter allen Fälschungen."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Brennen, J. S.; Simon, F.; Howard, P. N.; Nielsen, R. K. (2020): Types, Sources, and Claims of COVID-19 Misinformation. Reuters Institute Factsheet","oeffentlich":true,"doi":"10.60625/risj-awvq-sr55"},{"typ":"url","kurz":"Dufour, N. u. a. (2024): AMMeBa: A Large-Scale Survey and Dataset of Media-Based Misinformation In-The-Wild. arXiv:2405.11697v2 (Preprint)","oeffentlich":true,"url":"https://arxiv.org/abs/2405.11697"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"2f6f82f98b38e6ad"}}]`);export{t as n,n as t};